INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c0b401a-6771-4507-9487-bbcf9c938473', '往河陽宿峽陵寄李侍御', '往河陽宿峽陵寄李侍御', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["莫天寒風悲屑屑，啼鳥遶樹泉水噎。","行路解鞍投古陵，蒼蒼隔山見微月。","鴞鳴犬吠霜煙昏，開囊拂巾對盤飧。","人生窮達感知己，明日投君申片言。"]', '["莫天寒风悲屑屑，啼鸟遶樹泉水噎。","行路解鞍投古陵，蒼蒼隔山见微月。","鴞鳴犬吠霜煙昏，开囊拂巾对盤飧。","人生窮達感知己，明日投君申片言。"]', '诗', 'shi', '', NULL, '往河陽宿峽陵寄李侍御 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198e0d6d-50d7-4893-8299-6565d82ba247', '鵶路溪行呈陸中丞', '鵶路溪行呈陸中丞', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["鵶路不可越，三十六渡溪。","有物飲碧水，高林挂青蜺。","歷覽道更險，驅使跡頻暌。","視聽易常主，心魂互相迷。","浪石忽搖動，沙堤信難躋。","危峰紫霄外，古木浮雲齊。","出阻望汝郡，大賢多招攜。","疲馬戀舊秣，羈禽思故棲。","應憐泣楚玉，棄置如塵泥。"]', '["鵶路不可越，三十六渡溪。","有物饮碧水，高林挂青蜺。","歷覽道更險，驱使跡頻暌。","視听易常主，心魂互相迷。","浪石忽搖动，沙堤信难躋。","危峰紫霄外，古木浮云齊。","出阻望汝郡，大賢多招携。","疲马戀旧秣，羈禽思故棲。","應怜泣楚玉，棄置如塵泥。"]', '诗', 'shi', '', NULL, '鵶路溪行呈陸中丞 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d9067e-1f3e-4789-81cb-4d11507c9601', '獨宿峴首憶長安故人', '独宿峴首憶长安故人', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["月迥無隱物，況復大江秋。","江城與沙村，人語風颼飀。","峴亭當此時，故人不同遊。","故人在長安，亦可將夢求。"]', '["月迥無隐物，況复大江秋。","江城與沙村，人語风颼飀。","峴亭當此时，故人不同游。","故人在长安，亦可將梦求。"]', '诗', 'shi', '', NULL, '獨宿峴首憶長安故人 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71700e1e-f443-4d15-8ad9-0b7d116afde5', '雜曲歌辭 伊州 歌第三', '杂曲歌辞 伊州 歌第三', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["聞道黃花戍，頻年不解兵。","可憐閨裏月，偏照漢家營。"]', '["闻道黄花戍，頻年不解兵。","可怜閨裏月，偏照漢家營。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 歌第三 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e9f7376-b439-4ae5-a7cc-c7b987b19317', '雜曲歌辭 伊州 歌第四', '杂曲歌辞 伊州 歌第四', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["千里東歸客，無心憶舊遊。","挂帆游白水，高枕到青州。"]', '["千里东归客，無心憶旧游。","挂帆游白水，高枕到青州。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 歌第四 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b8e8f4-e55f-44cc-9054-637f6babcce1', '雜曲歌辭 伊州 歌第五', '杂曲歌辞 伊州 歌第五', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["桂殿江烏對，彫屏海燕重。","秖應多釀酒，醉罷樂高鐘。"]', '["桂殿江烏对，彫屏海燕重。","秖應多釀酒，醉罷乐高鐘。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 歌第五 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623257f6-e8db-4c0a-9f5b-dfd49f8ff92a', '雜曲歌辭 伊州 入破第一', '杂曲歌辞 伊州 入破第一', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["千門今夜曉初晴，萬里天河徹帝京。","璨璨繁星駕秋色，稜稜霜氣韻鐘聲。"]', '["千门今夜晓初晴，万里天河徹帝京。","璨璨繁星駕秋色，稜稜霜氣韻鐘声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 入破第一 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d02e9b44-7604-4af9-b174-162d059c4d6c', '雜曲歌辭 伊州 入破第二', '杂曲歌辞 伊州 入破第二', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["長安二月柳依依，西出流沙路漸微。","閼氏山上春光少，相府庭邊驛使稀。"]', '["长安二月柳依依，西出流沙路漸微。","閼氏山上春光少，相府庭邊驛使稀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 入破第二 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc39afc-6e45-4b7e-a104-ab1d718aaf46', '雜曲歌辭 伊州 入破第三', '杂曲歌辞 伊州 入破第三', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["三秋大漠冷溪山，八月嚴霜變草顏。","卷斾風行宵渡磧，銜枚電掃曉應還。"]', '["三秋大漠冷溪山，八月嚴霜变草顏。","卷斾风行宵渡磧，銜枚電掃晓應還。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 入破第三 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('badca271-bf99-42c4-829c-2fcf20f16950', '雜曲歌辭 伊州 入破第四', '杂曲歌辞 伊州 入破第四', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["行樂三陽早，芳菲二月春。","閨中紅粉態，陌上看花人。"]', '["行乐三陽早，芳菲二月春。","閨中紅粉態，陌上看花人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 入破第四 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0c3044-abde-40f5-bd9f-ac83fdbe8319', '雜曲歌辭 伊州 入破第五', '杂曲歌辞 伊州 入破第五', '8544146d-bf03-4fff-bd85-b31012073164', '唐', '["君住孤山下，煙深夜徑長。","轅門渡綠水，遊苑遶垂楊。"]', '["君住孤山下，煙深夜徑长。","轅门渡綠水，游苑遶垂楊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 伊州 入破第五 蓋嘉運 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94292002-770c-46a9-8403-d5b4db792fbf', '雜曲歌辭 陸州 歌第一', '杂曲歌辞 陸州 歌第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["分野中峰變，陰晴衆壑殊。","欲投人處宿，隔浦問樵夫。"]', '["分野中峰变，陰晴衆壑殊。","欲投人处宿，隔浦问樵夫。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 歌第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df9a231-79b5-4ae0-8350-5e2ca6f08da7', '雜曲歌辭 陸州 歌第二', '杂曲歌辞 陸州 歌第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["共得煙霞徑，東歸山水遊。","蕭蕭望林夜，寂寂坐中秋。"]', '["共得煙霞徑，东归山水游。","蕭蕭望林夜，寂寂坐中秋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 歌第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d0eb43-3cb8-42b2-9ea0-c5614cadb1eb', '雜曲歌辭 陸州 歌第三', '杂曲歌辞 陸州 歌第三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["香氣傳空滿，妝花映薄紅。","歌聲天仗外，舞態御樓中。"]', '["香氣傳空满，妝花映薄紅。","歌声天仗外，舞態御楼中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 歌第三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a022fd2-30af-4cec-81fd-e5b991ecbfd5', '雜曲歌辭 陸州 排遍第一', '杂曲歌辞 陸州 排遍第一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["樹發花如錦，鶯嗁柳若絲。","更逢歡宴地，愁見別離時。"]', '["樹發花如錦，鶯嗁柳若絲。","更逢歡宴地，愁见別離时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 排遍第一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cc2e497-c243-49fc-a919-6e50b73ec5cf', '雜曲歌辭 陸州 排遍第二', '杂曲歌辞 陸州 排遍第二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明月照秋葉，西風響夜砧。","彊言徒自亂，往事不堪尋。"]', '["明月照秋葉，西风响夜砧。","彊言徒自亂，往事不堪尋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 排遍第二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599966fc-6eb9-4c49-97e8-89ca38dfbb78', '雜曲歌辭 陸州 排遍第三', '杂曲歌辞 陸州 排遍第三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["坐對銀釭曉，停留玉筯痕。","君門常不見，無處謝前恩。"]', '["坐对銀釭晓，停留玉筯痕。","君门常不见，無处謝前恩。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 排遍第三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b08a6a1-5fbc-4148-9992-fb1469abe45a', '雜曲歌辭 陸州 排遍第四', '杂曲歌辞 陸州 排遍第四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["曙月當窗滿，征人出塞遙。","畫樓終日閉，清管爲誰調。"]', '["曙月當窗满，征人出塞遙。","畫楼終日閉，清管爲誰調。"]', '诗', 'shi', '', NULL, '雜曲歌辭 陸州 排遍第四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfb0df6-df08-488c-a287-37a643ffa171', '雜曲歌辭 簇拍陸州', '杂曲歌辞 簇拍陸州', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["西去輪臺萬里餘，故鄉音耗日應疎。","隴山鸚鵡能言語，爲報閨人數寄書。"]', '["西去輪台万里餘，故乡音耗日應疎。","隴山鸚鵡能言語，爲報閨人數寄书。"]', '诗', 'shi', '', NULL, '雜曲歌辭 簇拍陸州 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867793fe-5429-4df3-b46a-8dd6e75220d2', '雜曲歌辭 石州', '杂曲歌辞 石州', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["自從君去遠巡邊，終日羅幃獨自眠。","看花情轉切，攬鏡淚如泉。","一自離君後，嗁多雙臉穿。","何時狂虜滅，免得更留連。"]', '["自從君去远巡邊，終日羅幃独自眠。","看花情轉切，攬镜泪如泉。","一自離君後，嗁多雙臉穿。","何时狂虜滅，免得更留連。"]', '诗', 'shi', '', NULL, '雜曲歌辭 石州 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7066e611-faa5-427c-8fce-e0bf10c55416', '雜曲歌辭 蓋羅縫 一', '杂曲歌辞 蓋羅縫 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["秦時明月漢時關，萬里征人尚未還。","但願龍庭神將在，不教胡馬渡陰山。"]', '["秦时明月漢时关，万里征人尚未還。","但願龙庭神將在，不教胡马渡陰山。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蓋羅縫 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc7ee41-850f-4bb2-999c-49c8bfa948c0', '雜曲歌辭 蓋羅縫 二', '杂曲歌辞 蓋羅縫 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["音書杜絕白狼西，桃李無顏黃鳥嗁。","寒鳥春深歸去盡，出門腸斷草萋萋。"]', '["音书杜絕白狼西，桃李無顏黄鸟嗁。","寒鸟春深归去尽，出门腸斷草萋萋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蓋羅縫 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab191eb-2b10-434e-ba32-cb1f8b0a2d93', '雜曲歌辭 雙帶子', '杂曲歌辞 雙带子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["私言切語誰人會，海燕雙飛繞畫梁。","君學秋胡不相識，妾亦無心去采桑。"]', '["私言切語誰人會，海燕雙飞繞畫梁。","君学秋胡不相識，妾亦無心去采桑。"]', '诗', 'shi', '', NULL, '雜曲歌辭 雙帶子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0376fc59-bd2b-4b6a-9105-50bf77dc6999', '雜曲歌辭 崑崙子', '杂曲歌辞 崑崙子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["[揚]子譚經去，淮王載酒過。","醉來嗁鳥喚，坐久落花多。"]', '["[揚]子譚經去，淮王載酒過。","醉来嗁鸟喚，坐久落花多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 崑崙子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1991aab-5e58-411b-81ec-9a6c85e4601f', '雜曲歌辭 祓禊曲 一', '杂曲歌辞 祓禊曲 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昨見春條綠，那知秋葉黃。","蟬聲猶未斷，寒鴈已成行。"]', '["昨见春條綠，那知秋葉黄。","蟬声猶未斷，寒鴈已成行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 祓禊曲 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f33dbfd-6e6d-4ec9-97fd-aa549782ca2f', '雜曲歌辭 祓禊曲 二', '杂曲歌辞 祓禊曲 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["金谷園中柳，春來已舞腰。","那堪好風景，獨上洛陽橋。"]', '["金谷园中柳，春来已舞腰。","那堪好风景，独上洛陽橋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 祓禊曲 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('926a2036-d651-4bda-a7ef-55dd30aeecf3', '雜曲歌辭 祓禊曲 三', '杂曲歌辞 祓禊曲 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["何處堪愁思，花間長樂宮。","君王不重客，泣淚向春風。"]', '["何处堪愁思，花间长乐宮。","君王不重客，泣泪向春风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 祓禊曲 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('697019d0-83f3-4cd1-ba6f-7738d9c31ce0', '雜曲歌辭 上巳樂', '杂曲歌辞 上巳乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["猩猩血綵繫頭標，天上齊聲舉畫橈。","卻是內人爭意切，六宮羅袖一時招。"]', '["猩猩血綵繫头標，天上齊声舉畫橈。","卻是內人爭意切，六宮羅袖一时招。"]', '诗', 'shi', '', NULL, '雜曲歌辭 上巳樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c8add6-7843-4c4f-b6c1-e18bb7e071bb', '雜曲歌辭 穆護砂', '杂曲歌辞 穆護砂', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["玉管朝朝弄，清歌日日新。","折花當驛路，寄與隴頭人。"]', '["玉管朝朝弄，清歌日日新。","折花當驛路，寄與隴头人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 穆護砂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cb1b2d2-0d2c-43ab-945c-b037aecbc027', '雜曲歌辭 思歸樂 一', '杂曲歌辞 思归乐 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["晚日催弦管，春風入綺羅。","杏花如有意，偏落舞衫多。"]', '["晚日催弦管，春风入綺羅。","杏花如有意，偏落舞衫多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 思歸樂 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ada04a-9a0c-4d4e-9fc1-223b9a670f76', '雜曲歌辭 思歸樂 二', '杂曲歌辞 思归乐 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["萬里春應盡，三江鴈亦稀。","連天漢水廣，孤客未言歸。"]', '["万里春應尽，三江鴈亦稀。","連天漢水廣，孤客未言归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 思歸樂 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('144cfce8-087e-423d-be53-e93551cdeb48', '雜曲歌辭 金殿樂', '杂曲歌辞 金殿乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["入夜秋砧動，千門起四鄰。","不緣樓上月，應爲隴頭人。"]', '["入夜秋砧动，千门起四鄰。","不緣楼上月，應爲隴头人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 金殿樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c455d41-a372-4356-a9ed-975ddd89ff9c', '雜曲歌辭 胡渭州 一', '杂曲歌辞 胡渭州 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["亭亭孤月照行舟，寂寂長江萬里流。","鄉國不知何處是？雲山漫漫使人愁。"]', '["亭亭孤月照行舟，寂寂长江万里流。","乡国不知何处是？云山漫漫使人愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 胡渭州 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1594acd-0832-44f9-a254-6abff067a1a4', '雜曲歌辭 胡渭州 二', '杂曲歌辞 胡渭州 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["楊柳千尋色，桃花一苑芳。","風吹入簾裏，惟有惹衣香。"]', '["楊柳千尋色，桃花一苑芳。","风吹入簾裏，惟有惹衣香。"]', '诗', 'shi', '', NULL, '雜曲歌辭 胡渭州 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e06f7f-0e09-4944-b773-b1583e0d29bd', '雜曲歌辭 戎渾', '杂曲歌辞 戎渾', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["風勁角弓鳴，將軍獵渭城。","草枯鷹眼疾，雪盡馬蹏輕。"]', '["风勁角弓鳴，將軍獵渭城。","草枯鷹眼疾，雪尽马蹏轻。"]', '诗', 'shi', '', NULL, '雜曲歌辭 戎渾 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ad53a0-5a07-4866-aa4a-e782065bf905', '雜曲歌辭 牆頭花 一', '杂曲歌辞 牆头花 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蟋蟀鳴洞房，梧桐落金井。","爲君裁舞衣，天寒翦刀冷。"]', '["蟋蟀鳴洞房，梧桐落金井。","爲君裁舞衣，天寒翦刀冷。"]', '诗', 'shi', '', NULL, '雜曲歌辭 牆頭花 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7864efd-7500-46b6-82b7-fbf9be8267b0', '雜曲歌辭 牆頭花 二', '杂曲歌辞 牆头花 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["妾有羅衣裳，秦王在時作。","爲舞春風多，秋來不堪著。"]', '["妾有羅衣裳，秦王在时作。","爲舞春风多，秋来不堪著。"]', '诗', 'shi', '', NULL, '雜曲歌辭 牆頭花 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b86487-a06d-4efb-9858-cf3d9065aba0', '雜曲歌辭 采桑', '杂曲歌辞 采桑', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["自古多征戰，由來尚甲兵。","長驅千里去，一舉兩蕃平。","按劒從沙漠歌謠滿帝京寄言天下將須立武功名。"]', '["自古多征戰，由来尚甲兵。","长驱千里去，一舉兩蕃平。","按劒從沙漠歌謠满帝京寄言天下將須立武功名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 采桑 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca9c4f70-c296-4005-b36c-20c4de16d530', '雜曲歌辭 [楊]下採桑', '杂曲歌辞 [楊]下採桑', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["飛絲惹綠塵，軟葉對孤輪。","今朝入園去，物色彊看人。"]', '["飞絲惹綠塵，軟葉对孤輪。","今朝入园去，物色彊看人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 [楊]下採桑 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c8d82d0-2f42-4b39-a90d-0ee7e8e4bc4d', '雜曲歌辭 破陣樂 一', '杂曲歌辞 破陣乐 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["秋來四面足風沙，塞外征人暫別家。","千里不辭行路遠，時光早晚到天涯。"]', '["秋来四面足风沙，塞外征人暫別家。","千里不辞行路远，时光早晚到天涯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 破陣樂 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07d180a6-24fb-43f7-b04c-298962aa03b5', '雜曲歌辭 破陣樂 二', '杂曲歌辞 破陣乐 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["漢兵出頓金微，照日明光鐵衣。","百里火幡熖熖，千行雲騎騑騑。","蹙踏遼河自竭，鼓噪燕山可飛。","正屬四方朝賀，端知萬舞皇威。"]', '["漢兵出頓金微，照日明光鐵衣。","百里火幡熖熖，千行云騎騑騑。","蹙踏遼河自竭，鼓噪燕山可飞。","正屬四方朝賀，端知万舞皇威。"]', '诗', 'shi', '', NULL, '雜曲歌辭 破陣樂 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbceb077-c964-4d19-8fa4-3b2c6613c08c', '雜曲歌辭 破陣樂 三', '杂曲歌辞 破陣乐 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["少年膽氣凌雲，共許驍雄出羣。","匹馬城南挑戰，單刀薊北從軍。","一鼓鮮卑送欵，五餌單于解紛。","誓欲成名報國，羞將開口論勳。"]', '["少年膽氣凌云，共許驍雄出羣。","匹马城南挑戰，單刀薊北從軍。","一鼓鲜卑送欵，五餌單于解紛。","誓欲成名報国，羞將开口論勳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 破陣樂 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02baf687-c1d8-49bb-9847-688b4b0db9c4', '雜曲歌辭 戰勝樂', '杂曲歌辞 戰勝乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["百戰得功名，天兵意氣生。","三邊永不戰，此是我皇英。"]', '["百戰得功名，天兵意氣生。","三邊永不戰，此是我皇英。"]', '诗', 'shi', '', NULL, '雜曲歌辭 戰勝樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1dde17d-5fd4-496f-a262-b24ac571e95a', '雜曲歌辭 劒南臣', '杂曲歌辞 劒南臣', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不分君恩斷，觀妝視鏡中。","容華尚春日，嬌愛已秋風。","枕席臨窗曉，屏帷對月空。","年年後庭樹，芳悴在深宮。"]', '["不分君恩斷，观妝視镜中。","容华尚春日，嬌愛已秋风。","枕席臨窗晓，屏帷对月空。","年年後庭樹，芳悴在深宮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 劒南臣 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24d198e-752f-482c-aa79-d48fed994530', '雜曲歌辭 征步郎', '杂曲歌辞 征步郎', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["塞外虜塵飛，頻年度磧西。","死生隨玉劒，辛苦向金微。"]', '["塞外虜塵飞，頻年度磧西。","死生隨玉劒，辛苦向金微。"]', '诗', 'shi', '', NULL, '雜曲歌辭 征步郎 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f42e692d-0221-4d2a-afbb-c99700a0fe7f', '雜曲歌辭 [歎]疆場', '杂曲歌辞 [歎]疆場', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聞道行人至，妝梳對鏡臺。","淚痕猶尚在，笑靨自然開。"]', '["闻道行人至，妝梳对镜台。","泪痕猶尚在，笑靨自然开。"]', '诗', 'shi', '', NULL, '雜曲歌辭 [歎]疆場 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ae5a2a-e1ad-41a8-997d-5944e0fc9aab', '雜曲歌辭 塞姑', '杂曲歌辞 塞姑', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昨日盧梅塞口，整見諸人鎮守。","都護三年不歸，折盡江邊楊柳。"]', '["昨日盧梅塞口，整见諸人鎮守。","都護三年不归，折尽江邊楊柳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 塞姑 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfb73a2-ed75-48f1-afb8-eda13036d320', '雜曲歌辭 水鼓子', '杂曲歌辞 水鼓子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雕弓白羽獵初回，薄夜牛羊復下來。","夢水河邊秋草合，黑山峰外陣雲開。"]', '["雕弓白羽獵初回，薄夜牛羊复下来。","梦水河邊秋草合，黑山峰外陣云开。"]', '诗', 'shi', '', NULL, '雜曲歌辭 水鼓子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1320c1f-949a-4cbe-ad23-4806878632c5', '雜曲歌辭 婆羅門', '杂曲歌辞 婆羅门', 'dfda641e-dabc-46dc-96c4-6eabb949e3e2', '唐', '["迴樂峰前沙似雪，受降城外月如霜。","不知何處吹蘆管？一夜征人盡望鄉。"]', '["迴乐峰前沙似雪，受降城外月如霜。","不知何处吹蘆管？一夜征人尽望乡。"]', '诗', 'shi', '', NULL, '雜曲歌辭 婆羅門 楊敬述進 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102d5f4d-6b07-4d8a-9d98-52af69d55cbf', '雜曲歌辭 浣沙女 一', '杂曲歌辞 浣沙女 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["南陌春風早，東鄰去日斜。","千花開瑞錦，香撲美人車。"]', '["南陌春风早，东鄰去日斜。","千花开瑞錦，香撲美人车。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浣沙女 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a3e9a54-f14b-4e37-9d2c-6c9b231df309', '雜曲歌辭 浣沙女 二', '杂曲歌辞 浣沙女 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["長樂青門外，宜春小苑東。","樓開萬戶上，人向百花中。"]', '["长乐青门外，宜春小苑东。","楼开万戶上，人向百花中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浣沙女 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a423eb43-701c-4dd0-b979-52027c8bb410', '雜曲歌辭 鎮西', '杂曲歌辞 鎮西', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天邊物色更無春，祗有羊羣與馬羣。","誰家營裏吹羌笛，哀怨教人不忍聞。"]', '["天邊物色更無春，祗有羊羣與马羣。","誰家營裏吹羌笛，哀怨教人不忍闻。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鎮西 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f4af038-8199-49be-a010-aa7ac9a67f9b', '雜曲歌辭 鎮西 二', '杂曲歌辞 鎮西 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["歲去年來拜聖朝，更無山闕對溪橋。","九門楊柳渾無半，猶自千條與萬條。"]', '["歲去年来拜聖朝，更無山闕对溪橋。","九门楊柳渾無半，猶自千條與万條。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鎮西 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4216a7-1983-433b-bfd6-54ae9855d629', '雜曲歌辭 回紇', '杂曲歌辞 回紇', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["曾聞瀚海使難通，幽閨少婦罷裁縫。","緬想邊庭征戰苦，誰能對鏡治愁容。","久戍人將老，須臾變作白頭翁。"]', '["曾闻瀚海使难通，幽閨少婦罷裁縫。","緬想邊庭征戰苦，誰能对镜治愁容。","久戍人將老，須臾变作白头翁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 回紇 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fba1e28-e436-49dd-bb7c-ea006ec5eb51', '雜曲歌辭 長命女', '杂曲歌辞 长命女', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雲送關西雨，風傳渭北秋。","孤燈然客夢，寒杵擣鄉愁。"]', '["云送关西雨，风傳渭北秋。","孤灯然客梦，寒杵擣乡愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 長命女 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ff695a-6eff-4704-b986-d5e5f34360c5', '雜曲歌辭 醉公子', '杂曲歌辞 醉公子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昨日春園飲，今朝倒接䍦。","誰人扶上馬，不省下樓時。"]', '["昨日春园饮，今朝倒接䍦。","誰人扶上马，不省下楼时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 醉公子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba6002d-e6fe-4774-b34d-6d0e1399dc39', '雜曲歌辭 一片子', '杂曲歌辞 一片子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["柳色青山映，梨花雪鳥藏。","綠窗桃李下，閑坐歎春芳。"]', '["柳色青山映，梨花雪鸟藏。","綠窗桃李下，闲坐歎春芳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 一片子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61295446-6023-4dfe-9135-ae8c2c2acb72', '雜曲歌辭 甘州', '杂曲歌辞 甘州', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲使傳消息，空書意不任。","寄君明月鏡，偏照故人心。"]', '["欲使傳消息，空书意不任。","寄君明月镜，偏照故人心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 甘州 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e25a9ff8-af98-482b-8a10-ac04bad9eb57', '雜曲歌辭 濮陽女', '杂曲歌辞 濮陽女', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鴈來書不至，月照獨眠房。","賤妾多愁思，不堪秋夜長。"]', '["鴈来书不至，月照独眠房。","賤妾多愁思，不堪秋夜长。"]', '诗', 'shi', '', NULL, '雜曲歌辭 濮陽女 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad596df7-559f-4f97-81d3-7cba94b371c5', '雜曲歌辭 相府蓮', '杂曲歌辞 相府蓮', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["夜聞鄰婦泣，切切有餘哀。","即問緣何事，征人戰未迴。"]', '["夜闻鄰婦泣，切切有餘哀。","即问緣何事，征人戰未迴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 相府蓮 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b54cf0-094f-4f32-ae1b-d12cb826cead', '雜曲歌辭 蔟拍相府蓮', '杂曲歌辞 蔟拍相府蓮', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莫以今時寵，寧無舊日恩。","看花滿眼淚，不共楚王言。","閨燭無人影，羅屏有夢魂。","近來音耗絕，終日望應門。"]', '["莫以今时寵，寧無旧日恩。","看花满眼泪，不共楚王言。","閨燭無人影，羅屏有梦魂。","近来音耗絕，終日望應门。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蔟拍相府蓮 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e48a64e-3132-42f5-8903-cd1d7c497709', '雜曲歌辭 離別難', '杂曲歌辞 離別难', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["此別難重陳，花深復變人。","來時梅覆雪，去日柳含春。","物候催行客，歸途淑氣新。","剡川今已遠，魂夢暗相親。"]', '["此別难重陳，花深复变人。","来时梅覆雪，去日柳含春。","物候催行客，归途淑氣新。","剡川今已远，魂梦暗相親。"]', '诗', 'shi', '', NULL, '雜曲歌辭 離別難 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04cc4964-a77d-491f-ad66-b7d704843efa', '雜曲歌辭 離別難', '杂曲歌辞 離別难', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠楊陌上送行人，馬去車回一望塵。","不覺別時紅淚盡，歸來無淚可霑巾。"]', '["綠楊陌上送行人，马去车回一望塵。","不覺別时紅泪尽，归来無泪可霑巾。"]', '诗', 'shi', '', NULL, '雜曲歌辭 離別難 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc0f941e-daa1-4ec4-ace0-205c08f267b5', '雜曲歌辭 山鷓鴣 一', '杂曲歌辞 山鷓鴣 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["玉關征戍久，空閨人獨愁。","寒露溼青苔，別來蓬鬢秋。"]', '["玉关征戍久，空閨人独愁。","寒露溼青苔，別来蓬鬢秋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 山鷓鴣 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22aa7825-50bb-4538-8c64-07e9be2e0d20', '雜曲歌辭 山鷓鴣 二', '杂曲歌辞 山鷓鴣 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["人坐青樓晚，鶯語百花時。","愁人多自老，腸斷君不知。"]', '["人坐青楼晚，鶯語百花时。","愁人多自老，腸斷君不知。"]', '诗', 'shi', '', NULL, '雜曲歌辭 山鷓鴣 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ee2b22-3a2e-484b-a3be-ed05d933fdf6', '雜曲歌辭 鷓鴣詞', '杂曲歌辞 鷓鴣词', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["湘江斑竹枝，錦翼鷓鴣飛。","處處湘雲合，郎從何處歸。"]', '["湘江斑竹枝，錦翼鷓鴣飞。","处处湘云合，郎從何处归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鷓鴣詞 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a4b1e08-0a98-4cfc-bf09-df2d48032a83', '雜曲歌辭 鷓鴣詞 一', '杂曲歌辞 鷓鴣词 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["湘江煙水深，沙岸隔楓林。","何處鷓鴣飛？日斜斑竹陰。","二女虛垂淚，三閭枉自沈。","惟有鷓鴣鳥，獨傷行客心。"]', '["湘江煙水深，沙岸隔楓林。","何处鷓鴣飞？日斜斑竹陰。","二女虛垂泪，三閭枉自沈。","惟有鷓鴣鸟，独傷行客心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鷓鴣詞 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df84efd-f604-4f15-bb4b-02a967dc849f', '雜曲歌辭 鷓鴣詞 二', '杂曲歌辞 鷓鴣词 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["越岡連越井，越鳥更南飛。","何處鷓鴣嗁，夕煙東嶺歸。","嶺頭行人少，天涯北客稀。","鷓鴣嗁別處，相對淚霑衣。"]', '["越岡連越井，越鸟更南飞。","何处鷓鴣嗁，夕煙东嶺归。","嶺头行人少，天涯北客稀。","鷓鴣嗁別处，相对泪霑衣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鷓鴣詞 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f26ad4f-5b4e-4d68-a5de-9b8c6a9658c1', '雜曲歌辭 樂世', '杂曲歌辞 乐世', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["管急絲繁拍漸稠，綠腰宛轉曲終頭。","誠知樂世聲聲樂，老病人聽未免愁。"]', '["管急絲繁拍漸稠，綠腰宛轉曲終头。","誠知乐世声声乐，老病人听未免愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 樂世 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc51fef4-8791-4d57-8148-088441d6a3ab', '雜曲歌辭 急[樂世]', '杂曲歌辞 急[乐世]', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["正抽碧線繡紅羅，忽聽黃鶯斂翠蛾。","秋思冬愁春恨望，大都不得意時多。"]', '["正抽碧線繡紅羅，忽听黄鶯斂翠蛾。","秋思冬愁春恨望，大都不得意时多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 急[樂世] 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e5dc90f-39b3-40a2-8b94-5c4848fd301f', '雜曲歌辭 何滿子', '杂曲歌辞 何满子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世傳滿子是人名，臨就刑時曲始成。","一曲四詞歌八疊，從頭便是斷腸聲。"]', '["世傳满子是人名，臨就刑时曲始成。","一曲四词歌八叠，從头便是斷腸声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 何滿子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b21364-d2c7-4aef-95ec-106c41bd77ed', '雜曲歌辭 何滿子', '杂曲歌辞 何满子', '836bf652-34d2-4128-bfb5-84b33cc3a31c', '唐', '["繫馬宮槐老，持杯店菊黃。","故交今不見，流恨滿川光。"]', '["繫马宮槐老，持杯店菊黄。","故交今不见，流恨满川光。"]', '诗', 'shi', '', NULL, '雜曲歌辭 何滿子 薛逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5f1094b-b9be-43cf-8e04-9b984642a630', '雜曲歌辭 清平調 一', '杂曲歌辞 清平調 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雲想衣裳花想容，春風拂檻露華濃。","若非羣玉山頭見，會向瑤臺月下逢。"]', '["云想衣裳花想容，春风拂檻露华濃。","若非羣玉山头见，會向瑤台月下逢。"]', '诗', 'shi', '', NULL, '雜曲歌辭 清平調 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73dadc56-88ff-4f11-9ff5-da0e0adf533c', '雜曲歌辭 清平調 二', '杂曲歌辞 清平調 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["一枝紅豔露凝香，雲雨巫山枉斷腸。","借問漢宮誰得似，可憐飛燕倚新妝。"]', '["一枝紅豔露凝香，云雨巫山枉斷腸。","借问漢宮誰得似，可怜飞燕倚新妝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 清平調 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db5450e-f1e0-4d53-8106-529def535537', '雜曲歌辭 清平調 三', '杂曲歌辞 清平調 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["名花傾國兩相歡，長得君王帶笑看。","解釋春風無限恨，沈香亭北倚闌干。"]', '["名花傾国兩相歡，长得君王带笑看。","解釋春风無限恨，沈香亭北倚闌干。"]', '诗', 'shi', '', NULL, '雜曲歌辭 清平調 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4361ba5-68fa-40ca-8795-6dddc27ad023', '雜曲歌辭 回波樂', '杂曲歌辞 回波乐', '11b77852-49dc-4a2b-9c82-39cc01c2b85b', '唐', '["回波爾時酒巵，微臣職在箴規。","侍宴既過三爵，諠譁竊恐非儀。"]', '["回波爾时酒巵，微臣職在箴規。","侍宴既過三爵，諠譁竊恐非儀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 回波樂 李景伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c243b415-6685-4c96-9952-fd82f813199d', '雜曲歌辭 聖明樂 一', '杂曲歌辞 聖明乐 一', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["玉帛殊方至，歌鍾比屋聞。","華夷今一貫，同賀聖明君。"]', '["玉帛殊方至，歌鍾比屋闻。","华夷今一貫，同賀聖明君。"]', '诗', 'shi', '', NULL, '雜曲歌辭 聖明樂 一 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('826f0eb7-19d7-4a47-b186-26cc447991cc', '雜曲歌辭 聖明樂 二', '杂曲歌辞 聖明乐 二', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["九陌祥煙合，千春瑞月明。","宮花將苑柳，先發鳳皇城。"]', '["九陌祥煙合，千春瑞月明。","宮花將苑柳，先發鳳皇城。"]', '诗', 'shi', '', NULL, '雜曲歌辭 聖明樂 二 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53d63f2-c22e-41d7-81dd-f4529d2978a1', '雜曲歌辭 聖明樂', '杂曲歌辞 聖明乐', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["海浪恬丹徼，邊塵靜異山。","從今萬里外，不復鎖蕭關。"]', '["海浪恬丹徼，邊塵静異山。","從今万里外，不复鎖蕭关。"]', '诗', 'shi', '', NULL, '雜曲歌辭 聖明樂 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ea242b-dea0-40d6-8e0c-84be8761df5a', '雜曲歌辭 大酺樂', '杂曲歌辞 大酺乐', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["淚滴珠難盡，容殘玉易銷。","儻隨明月去，莫道夢魂遙。"]', '["泪滴珠难尽，容殘玉易銷。","儻隨明月去，莫道梦魂遙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 大酺樂 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3fc929a-d769-4b7f-86af-f2534b9a26e1', '雜曲歌辭 大酺樂 一', '杂曲歌辞 大酺乐 一', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["聖后乘乾日，皇明御曆辰。","紫宮初啓坐，蒼璧正臨春。","雷雨垂膏澤，金錢賜下人。","詔酺歡賞徧，交泰覩惟新。"]', '["聖后乘乾日，皇明御曆辰。","紫宮初啓坐，蒼璧正臨春。","雷雨垂膏澤，金錢賜下人。","詔酺歡賞徧，交泰覩惟新。"]', '诗', 'shi', '', NULL, '雜曲歌辭 大酺樂 一 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff257f62-6a13-4be9-b536-bfe07af7807e', '雜曲歌辭 大酺樂 二', '杂曲歌辞 大酺乐 二', 'b2b3ec5e-ceed-48dd-99ac-731465d8e9f0', '唐', '["毘陵震澤九州通，士女歡娛萬國同。","伐鼓撞鐘驚海上，新妝袨服照江東。","梅花落處疑殘雪，柳葉開時任好風。","大德不官逢道泰，天長地久屬年豐。"]', '["毘陵震澤九州通，士女歡娛万国同。","伐鼓撞鐘驚海上，新妝袨服照江东。","梅花落处疑殘雪，柳葉开时任好风。","大德不官逢道泰，天长地久屬年豐。"]', '诗', 'shi', '', NULL, '雜曲歌辭 大酺樂 二 杜審言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94934c3-03e9-4030-9668-8dee295256a8', '雜曲歌辭 大酺樂 一', '杂曲歌辞 大酺乐 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["車駕東來值太平，大酺三日洛陽城。","小兒一伎竿頭絕，天下傳呼萬歲聲。"]', '["车駕东来值太平，大酺三日洛陽城。","小兒一伎竿头絕，天下傳呼万歲声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 大酺樂 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b55e01e-a88a-4058-a516-243c818c9043', '雜曲歌辭 大酺樂 二', '杂曲歌辞 大酺乐 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紫陌酺歸日欲斜，紅塵開路薛王家。","雙鬟前說樓前鼓，兩伎爭輪好結花。"]', '["紫陌酺归日欲斜，紅塵开路薛王家。","雙鬟前说楼前鼓，兩伎爭輪好結花。"]', '诗', 'shi', '', NULL, '雜曲歌辭 大酺樂 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28a5507-0edb-48cc-b0c6-a61347d772de', '雜曲歌辭 千秋樂', '杂曲歌辞 千秋乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["八月平時花萼樓，萬方同樂奏千秋。","傾城人看長竿出，一伎初成趙解愁。"]', '["八月平时花萼楼，万方同乐奏千秋。","傾城人看长竿出，一伎初成趙解愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 千秋樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb36238-1a2b-41a3-9a5f-a7e910d7c16b', '雜曲歌辭 火鳳辭 一', '杂曲歌辞 火鳳辞 一', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["歌聲扇裏出，妝影扇中輕。","未能令掩笑，何處欲鄣聲。","知音自不惑，得念是分明。","莫見雙嚬斂，疑人含笑情。"]', '["歌声扇裏出，妝影扇中轻。","未能令掩笑，何处欲鄣声。","知音自不惑，得念是分明。","莫见雙嚬斂，疑人含笑情。"]', '诗', 'shi', '', NULL, '雜曲歌辭 火鳳辭 一 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce536af-9b75-421f-aca0-b5ec399dcfb4', '雜曲歌辭 火鳳辭 二', '杂曲歌辞 火鳳辞 二', '753bab59-f351-4f5a-a4e7-03286355de2b', '唐', '["佳人靚晚妝，清唱動蘭房。","影入含風扇，聲飛照日梁。","嬌嚬眉際斂，逸韻口中香。","自有橫陳分，應憐秋夜長。"]', '["佳人靚晚妝，清唱动蘭房。","影入含风扇，声飞照日梁。","嬌嚬眉際斂，逸韻口中香。","自有橫陳分，應怜秋夜长。"]', '诗', 'shi', '', NULL, '雜曲歌辭 火鳳辭 二 李百藥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53faf355-3055-4ddb-8285-6b42a984dbbf', '雜曲歌辭 熱戲樂', '杂曲歌辞 熱戲乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["熱戲爭心劇火燒，銅槌暗執不相饒。","上皇失喜寧王笑，百尺幢竿果動搖。"]', '["熱戲爭心劇火燒，銅槌暗執不相饒。","上皇失喜寧王笑，百尺幢竿果动搖。"]', '诗', 'shi', '', NULL, '雜曲歌辭 熱戲樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffefb2df-5b94-4f50-9907-4be92746cc4a', '雜曲歌辭 春鶯囀', '杂曲歌辞 春鶯囀', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["興慶池南柳未開，太真先把一枝梅。","內人已唱春鶯囀，花下傞傞軟舞來。"]', '["兴慶池南柳未开，太真先把一枝梅。","內人已唱春鶯囀，花下傞傞軟舞来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 春鶯囀 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f182179e-9140-43eb-97bb-78db53c97055', '雜曲歌辭 達摩支', '杂曲歌辞 達摩支', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["擣麝成塵香不滅，拗蓮作寸絲難絕。","紅淚文姬洛水春，白頭蘇武天山雪。","君不見無愁高緯花漫漫，漳浦宴餘清露寒。","一旦臣僚共囚虜，欲吹羌管先汍瀾。","舊臣頭鬢霜華早，可惜雄心醉中老。","萬古春歸夢不歸，鄴城風雨連天草。"]', '["擣麝成塵香不滅，拗蓮作寸絲难絕。","紅泪文姬洛水春，白头蘇武天山雪。","君不见無愁高緯花漫漫，漳浦宴餘清露寒。","一旦臣僚共囚虜，欲吹羌管先汍瀾。","旧臣头鬢霜华早，可惜雄心醉中老。","万古春归梦不归，鄴城风雨連天草。"]', '诗', 'shi', '', NULL, '雜曲歌辭 達摩支 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('516379b7-d6f7-4fd9-b5f5-d6dcd7dc92ee', '雜曲歌辭 如意娘', '杂曲歌辞 如意娘', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["看朱成碧思紛紛，憔悴支離爲憶君。","不信比來長下淚，開箱驗取石榴裙。"]', '["看朱成碧思紛紛，憔悴支離爲憶君。","不信比来长下泪，开箱驗取石榴裙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 如意娘 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ba8b942-3ced-425b-a5d4-8a890208df29', '雜曲歌辭 雨霖鈴', '杂曲歌辞 雨霖鈴', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["雨霖鈴夜卻歸秦，猶是張徽一曲新。","長說上皇垂淚教，月明南內更無人。"]', '["雨霖鈴夜卻归秦，猶是張徽一曲新。","长说上皇垂泪教，月明南內更無人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 雨霖鈴 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f36a88f-5b5d-4f50-87fa-ef10188af102', '雜曲歌辭 桂花曲', '杂曲歌辞 桂花曲', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["可憐天上桂花孤，試問姮娥更要無。","月宮幸有閒田地，何不中央種兩株。"]', '["可怜天上桂花孤，試问姮娥更要無。","月宮幸有閒田地，何不中央種兩株。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桂花曲 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a87504-f9a3-4599-b770-aba4afd3cb04', '雜曲歌辭 渭城曲', '杂曲歌辞 渭城曲', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["謂城朝雨浥輕塵，客舍青青柳色春。","勸君更盡一杯酒，西出陽關無故人。"]', '["謂城朝雨浥轻塵，客舍青青柳色春。","勸君更尽一杯酒，西出陽关無故人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 渭城曲 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5f0ec8-8c80-4fd6-aca5-1f283d430ad4', '雜曲歌辭 竹枝', '杂曲歌辞 竹枝', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["帝子蒼梧不復歸，洞庭葉下荆雲飛。","巴人夜唱竹枝後，腸斷曉猨聲漸稀。"]', '["帝子蒼梧不复归，洞庭葉下荆云飞。","巴人夜唱竹枝後，腸斷晓猨声漸稀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5640c81c-c876-463a-8e7a-1c64020e12b3', '雜曲歌辭 竹枝 一', '杂曲歌辞 竹枝 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白帝城頭春草生，白鹽山下蜀江清。","南人上來歌一曲，北人莫上動鄉情。"]', '["白帝城头春草生，白鹽山下蜀江清。","南人上来歌一曲，北人莫上动乡情。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6164ec67-303e-46b4-bbb8-193b64d9e23b', '雜曲歌辭 竹枝 二', '杂曲歌辞 竹枝 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山桃紅花滿上頭，蜀江春水拍江流。","花紅易衰似郎意，水流無限似儂愁。"]', '["山桃紅花满上头，蜀江春水拍江流。","花紅易衰似郎意，水流無限似儂愁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('597c32ad-6e79-437e-8725-63efff85d83a', '雜曲歌辭 竹枝 三', '杂曲歌辞 竹枝 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["江上朱樓新雨晴，瀼西春水縠文生。","橋東橋西好楊柳，人來人去唱歌行。"]', '["江上朱楼新雨晴，瀼西春水縠文生。","橋东橋西好楊柳，人来人去唱歌行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77121ae7-3102-441e-bb70-1a232193c92e', '雜曲歌辭 竹枝 四', '杂曲歌辞 竹枝 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日出三竿春霧消，江頭蜀客駐蘭橈。","憑寄狂夫書一紙，住在成都萬里橋。"]', '["日出三竿春霧消，江头蜀客駐蘭橈。","憑寄狂夫书一紙，住在成都万里橋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d87228-104c-4e95-96d3-4f17ecf86238', '雜曲歌辭 竹枝 五', '杂曲歌辞 竹枝 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["兩岸山花似雪開，家家春酒滿銀杯。","昭君坊中多女伴，永安宮外踏青來。"]', '["兩岸山花似雪开，家家春酒满銀杯。","昭君坊中多女伴，永安宮外踏青来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('130faeb2-00ea-4744-b85b-62baadfe8d82', '雜曲歌辭 竹枝 六', '杂曲歌辞 竹枝 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["瞿塘嘈嘈十二灘，此中道路古來難。","長恨人心不如水，等閑平地起波瀾。"]', '["瞿塘嘈嘈十二灘，此中道路古来难。","长恨人心不如水，等闲平地起波瀾。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08630597-508f-4bdd-b9b1-2d531a175574', '雜曲歌辭 竹枝 七', '杂曲歌辞 竹枝 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["巫峽蒼蒼煙雨時，清猨啼在最高枝。","箇裏愁人腸自斷，由來不是此聲悲。"]', '["巫峽蒼蒼煙雨时，清猨啼在最高枝。","箇裏愁人腸自斷，由来不是此声悲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fa962c2-c63a-47bb-842e-2125894fbaea', '雜曲歌辭 竹枝 八', '杂曲歌辞 竹枝 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城西門前灩澦堆，年年波浪不能摧。","懊惱人心不如石，少時東去復西來。"]', '["城西门前灩澦堆，年年波浪不能摧。","懊惱人心不如石，少时东去复西来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e139708b-9909-4489-acfd-9458dac6e8e4', '雜曲歌辭 竹枝 九', '杂曲歌辞 竹枝 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["山上層層桃李花，雲間煙火是人家。","銀釧金釵來負水，長刀短笠去燒畬。"]', '["山上層層桃李花，云间煙火是人家。","銀釧金釵来負水，长刀短笠去燒畬。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b000fd9-b9ce-4215-8777-32267dcc5456', '雜曲歌辭 竹枝 一', '杂曲歌辞 竹枝 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楊柳青青江水平，聞郎江上唱歌聲。","東邊日出西邊雨，道是無情還有情。"]', '["楊柳青青江水平，闻郎江上唱歌声。","东邊日出西邊雨，道是無情還有情。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c12c30c3-e7da-4123-994c-c007a05c13e0', '雜曲歌辭 竹枝 二', '杂曲歌辞 竹枝 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楚水巴山江雨多，巴人能唱本鄉歌。","今朝北客思歸去，迴入紇那披綠羅。"]', '["楚水巴山江雨多，巴人能唱本乡歌。","今朝北客思归去，迴入紇那披綠羅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4172a5d-55d3-42da-9db7-6dfda5034a88', '雜曲歌辭 竹枝 一', '杂曲歌辞 竹枝 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["瞿塘峽口冷煙低，白帝城頭月向西。","唱到竹枝聲咽處，寒猨晴鳥一時啼。"]', '["瞿塘峽口冷煙低，白帝城头月向西。","唱到竹枝声咽处，寒猨晴鸟一时啼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ca2017-0c5a-47a0-b04f-83282daa65b5', '雜曲歌辭 竹枝 二', '杂曲歌辞 竹枝 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹枝苦怨怨何人，夜靜山空歇又聞。","蠻兒巴女齊聲唱，愁殺江樓病使君。"]', '["竹枝苦怨怨何人，夜静山空歇又闻。","蠻兒巴女齊声唱，愁殺江楼病使君。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41998801-e03b-44b6-ae52-d8703c1a7b17', '雜曲歌辭 竹枝 三', '杂曲歌辞 竹枝 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巴東船舫上巴西，波面風生雨脚齊。","水蓼冷花紅蔟蔟，江蘺溼葉碧萋萋。"]', '["巴东船舫上巴西，波面风生雨脚齊。","水蓼冷花紅蔟蔟，江蘺溼葉碧萋萋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e192c25-d4a1-4a6c-aadc-a780ab6dfd34', '雜曲歌辭 竹枝 四', '杂曲歌辞 竹枝 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江畔誰人唱竹枝，前聲斷咽後聲遲。","怪來調苦緣詞苦，多是通州司馬詩。"]', '["江畔誰人唱竹枝，前声斷咽後声遲。","怪来調苦緣词苦，多是通州司马诗。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7d7a94e-be74-4b86-8512-35700e9dad55', '雜曲歌辭 竹枝 一', '杂曲歌辞 竹枝 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["荆門灘急水潺潺，兩岸猨啼煙滿山。","渡頭年少應官去，月落西陵望不還。"]', '["荆门灘急水潺潺，兩岸猨啼煙满山。","渡头年少應官去，月落西陵望不還。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e17c65-86f6-4948-9eec-b4e12c1c927a', '雜曲歌辭 竹枝 二', '杂曲歌辞 竹枝 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["巫峽雲開神女祠，綠潭紅樹影參差。","下牢戍口初相問，無義灘頭剩別離。"]', '["巫峽云开神女祠，綠潭紅樹影參差。","下牢戍口初相问，無義灘头剩別離。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c18fe0-deb7-4493-85d8-f3c602b3fd6c', '雜曲歌辭 竹枝 三', '杂曲歌辞 竹枝 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["石壁千重樹萬重，白雲斜掩碧芙蓉。","昭君溪上年年月，獨自嬋娟色最濃。"]', '["石壁千重樹万重，白云斜掩碧芙蓉。","昭君溪上年年月，独自嬋娟色最濃。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11a6b16-e984-4fd0-9978-4b97082f6a2b', '雜曲歌辭 竹枝 四', '杂曲歌辞 竹枝 四', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["十二峰頭月欲低，空濛江上子規啼。","孤舟一夜東歸客，泣向春風憶建溪。"]', '["十二峰头月欲低，空濛江上子規啼。","孤舟一夜东归客，泣向春风憶建溪。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 四 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f46758-bdec-41a6-b5bf-b329495828ba', '雜曲歌辭 竹枝 一', '杂曲歌辞 竹枝 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["門前春水白蘋花，岸上無人小艇斜。","商女經過江欲暮，散拋殘食飼神雅。"]', '["门前春水白蘋花，岸上無人小艇斜。","商女經過江欲暮，散拋殘食飼神雅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee3aac5-6076-488a-887f-40d547139cb9', '雜曲歌辭 竹枝 二', '杂曲歌辞 竹枝 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["亂繩千結絆人深，越羅萬丈表長尋。","楊柳在身垂意緒，藕花落盡見蓮心。"]', '["亂繩千結絆人深，越羅万丈表长尋。","楊柳在身垂意緒，藕花落尽见蓮心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 竹枝 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c798ff8d-5eb4-4926-82b2-bc7f6bbbdeb3', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一樹春風萬萬枝，嫩於金色軟於絲。","永豐西角荒園裏，盡日無人屬阿誰。"]', '["一樹春风万万枝，嫩於金色軟於絲。","永豐西角荒园裏，尽日無人屬阿誰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c279c714-6ac2-4c87-af9c-dc80e3c20ba7', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一樹衰殘委泥土，雙枝榮耀植天庭。","定知玄象今春後，柳宿光中添兩星。"]', '["一樹衰殘委泥土，雙枝榮耀植天庭。","定知玄象今春後，柳宿光中添兩星。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee3cd27-8bb4-49b5-9e23-7d054908e6e7', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六么水調家家唱，白雪梅花處處吹。","古歌舊曲君休聽，聽取新翻楊柳枝。"]', '["六么水調家家唱，白雪梅花处处吹。","古歌旧曲君休听，听取新翻楊柳枝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0affef8d-094a-4955-9ab1-04fb2a16966b', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陶令門前四五樹，亞夫營裏百千條。","何似東都正二月，黃金枝映洛陽橋。"]', '["陶令门前四五樹，亞夫營裏百千條。","何似东都正二月，黄金枝映洛陽橋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea9313c-3f8b-47be-bf52-0ba0c7b879b8', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["依依嫋嫋復青青，句引清風無限情。","白雪花繁空撲地，綠絲條弱不勝鶯。"]', '["依依嫋嫋复青青，句引清风無限情。","白雪花繁空撲地，綠絲條弱不勝鶯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('217cd97f-80d4-4b42-ade3-87e558da16a8', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅板江橋青酒旗，館娃宮暖日斜時。","可憐雨歇東風定，萬樹千條各自垂。"]', '["紅板江橋青酒旗，館娃宮暖日斜时。","可怜雨歇东风定，万樹千條各自垂。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3560c3d4-ef9f-4a41-b5eb-3c0a751df7f9', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘇州楊柳任君誇，更有錢塘勝館娃。","若解多情尋小小，綠楊深處是蘇家。"]', '["蘇州楊柳任君誇，更有錢塘勝館娃。","若解多情尋小小，綠楊深处是蘇家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0724d85f-da02-4fda-8ea4-23490ffec36c', '雜曲歌辭 楊柳枝 六', '杂曲歌辞 楊柳枝 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘇家小女舊知名，楊柳風前別有情。","剝條盤作銀環樣，卷葉吹爲玉笛聲。"]', '["蘇家小女旧知名，楊柳风前別有情。","剝條盤作銀环樣，卷葉吹爲玉笛声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7838c975-46db-4207-95ff-79cd5aa726eb', '雜曲歌辭 楊柳枝 七', '杂曲歌辞 楊柳枝 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉含濃露如啼眼，枝嫋輕風似舞腰。","小樹不禁攀折苦，乞君留取兩三條。"]', '["葉含濃露如啼眼，枝嫋轻风似舞腰。","小樹不禁攀折苦，乞君留取兩三條。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0485d5de-635b-4d89-8633-7c9bbf8cd319', '雜曲歌辭 楊柳枝 八', '杂曲歌辞 楊柳枝 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人言柳葉似愁眉，更有愁腸似柳絲。","柳絲挽斷腸牽斷，彼此應無續得期。"]', '["人言柳葉似愁眉，更有愁腸似柳絲。","柳絲挽斷腸牽斷，彼此應無續得期。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7919cf3e-24f0-494b-b1d7-cf441b743eb6', '雜曲歌辭 楊柳枝', '杂曲歌辞 楊柳枝', 'd3b7ce71-9ac2-4997-b8c1-4da0db5a9411', '唐', '["一樹依依在永豐，兩枝飛去杳無蹤。","玉皇曾采人間曲，應逐歌聲入九重。"]', '["一樹依依在永豐，兩枝飞去杳無蹤。","玉皇曾采人间曲，應逐歌声入九重。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 盧貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('187596fc-5d5c-482c-9d7d-2c6b8bab093c', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["塞北梅花羌笛吹，淮南桂樹小山詞。","請君莫奏前朝曲，聽唱新翻楊柳枝。"]', '["塞北梅花羌笛吹，淮南桂樹小山词。","請君莫奏前朝曲，听唱新翻楊柳枝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29482a7d-b353-48eb-8094-f08b572739b7', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["南陌東城春早時，相逢何處不依依。","桃紅李白皆誇好，須得垂楊相發輝。"]', '["南陌东城春早时，相逢何处不依依。","桃紅李白皆誇好，須得垂楊相發輝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7010856b-a328-4e29-b395-65b77f8f0f50', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鳳闕輕遮翡翠帷，龍墀遙望麴塵絲。","御溝春水柳暉映，狂殺長安年少兒。"]', '["鳳闕轻遮翡翠帷，龙墀遙望麴塵絲。","御溝春水柳暉映，狂殺长安年少兒。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1218522-a4b2-4bcb-b402-c44c032eed42', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["金谷園中鶯亂飛，銅駝陌上好風吹。","城東桃李須臾盡，爭似垂楊無限時。"]', '["金谷园中鶯亂飞，銅駝陌上好风吹。","城东桃李須臾尽，爭似垂楊無限时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('507c64d7-be4c-4c96-9297-7de37d506e3c', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["花萼樓前初種時，美人樓上鬬腰支。","如今拋擲上街裏，露葉如啼欲恨誰。"]', '["花萼楼前初種时，美人楼上鬬腰支。","如今拋擲上街裏，露葉如啼欲恨誰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eabde8a-de35-452e-abe5-c85d34bac1a7', '雜曲歌辭 楊柳枝 六', '杂曲歌辞 楊柳枝 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["煬帝行宮汴水濱，數株殘柳不勝春。","昨來風起花如雪，飛入宮牆不見人。"]', '["煬帝行宮汴水濱，數株殘柳不勝春。","昨来风起花如雪，飞入宮牆不见人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55560145-871c-4ff9-96d7-d30c1a7ddf6d', '雜曲歌辭 楊柳枝 七', '杂曲歌辞 楊柳枝 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["御陌青門拂地垂，千條金縷萬條絲。","如今綰作同心結，將贈行人知不知。"]', '["御陌青门拂地垂，千條金縷万條絲。","如今綰作同心結，將贈行人知不知。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5cbeee-3fc0-4e83-a702-1797d0a7d98d', '雜曲歌辭 楊柳枝 八', '杂曲歌辞 楊柳枝 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["城外春風滿酒旗，行人揮袂日西時。","長安陌上無窮樹，唯有垂楊管別離。"]', '["城外春风满酒旗，行人揮袂日西时。","长安陌上無窮樹，唯有垂楊管別離。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5618d671-daf5-475c-9334-15c8bbc8e0b8', '雜曲歌辭 楊柳枝 九', '杂曲歌辞 楊柳枝 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["輕盈嫋娜占春華，舞榭妝樓處處遮。","春盡絮飛留不得，隨風好去落誰家。"]', '["轻盈嫋娜占春华，舞榭妝楼处处遮。","春尽絮飞留不得，隨风好去落誰家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e5a3c9-7114-4dc8-8eb2-c8f7efdd8f40', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["[揚]子江頭煙景迷，隋家宮樹拂金堤。","嵯峨猶有當時色，半蘸波中水鳥棲。"]', '["[揚]子江头煙景迷，隋家宮樹拂金堤。","嵯峨猶有當时色，半蘸波中水鸟棲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('894c1eec-7e59-40ab-b7d1-0b6e47d96b2b', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["迎得春光先到來，淺黃輕綠映樓臺。","只緣嫋娜多情思，便被春風長請挼。"]', '["迎得春光先到来，淺黄轻綠映楼台。","只緣嫋娜多情思，便被春风长請挼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90663246-61d0-478b-932f-e57ba872f6d0', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["巫峽巫山楊柳多，朝雲暮雨遠相和。","因想陽臺無限事，爲君迴唱竹枝歌。"]', '["巫峽巫山楊柳多，朝云暮雨远相和。","因想陽台無限事，爲君迴唱竹枝歌。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec8d88be-15d5-4eab-9fb3-f7736e9a8e1e', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["暫憑樽酒送無憀，莫損愁眉與細腰。","人世死前唯有別，春風爭擬惜長條。"]', '["暫憑樽酒送無憀，莫損愁眉與細腰。","人世死前唯有別，春风爭擬惜长條。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55526114-de81-4cdc-94de-d691476415fb', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["含煙惹霧每依依，萬緒千條拂落暉。","爲報行人休盡折，半留相送半迎歸。"]', '["含煙惹霧每依依，万緒千條拂落暉。","爲報行人休尽折，半留相送半迎归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4199debb-ddf2-4883-b2ec-ab23bec67736', '雜曲歌辭 楊柳枝', '杂曲歌辞 楊柳枝', '639934f7-0c93-4e36-963c-b172b39e616d', '唐', '["梁苑隋堤事已空，萬條猶舞舊春風。","那堪更想千年後，誰見楊花入漢宮。"]', '["梁苑隋堤事已空，万條猶舞旧春风。","那堪更想千年後，誰见楊花入漢宮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 韓琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d53be0f-c369-4ae8-967b-29735494f879', '雜曲歌辭 楊柳枝', '杂曲歌辞 楊柳枝', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["傷見路傍楊柳春，一枝折盡一重新。","今年還折去年處，不送去年離別人。"]', '["傷见路傍楊柳春，一枝折尽一重新。","今年還折去年处，不送去年離別人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c91841-9fd9-4772-b208-7ae09ecd7c52', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["宜春苑外最長條，閑嫋春風伴舞腰。","正是玉人腸斷處，一渠春水赤欄橋。"]', '["宜春苑外最长條，闲嫋春风伴舞腰。","正是玉人腸斷处，一渠春水赤欄橋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcba2d3-56c8-4921-bbdb-fb446bc99993', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["南內牆東御路傍，預知春色柳絲黃。","杏花未肯無情思，何事情人最斷腸。"]', '["南內牆东御路傍，預知春色柳絲黄。","杏花未肯無情思，何事情人最斷腸。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4b8467-fff8-4589-a1b1-6541fa01d8be', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘇小門前柳萬條，毿毿金線拂平橋。","黃鶯不語東風起，深閉朱門伴細腰。"]', '["蘇小门前柳万條，毿毿金線拂平橋。","黄鶯不語东风起，深閉朱门伴細腰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c0dd44-612a-452e-9e21-ea93dca451ae', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["金縷毿毿碧瓦溝，六宮眉黛惹春愁。","晚來更帶龍池雨，半拂欄干半入樓。"]', '["金縷毿毿碧瓦溝，六宮眉黛惹春愁。","晚来更带龙池雨，半拂欄干半入楼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('835a0bce-abb5-4d6e-9daa-76dafcb7cde4', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["館娃宮外鄴城西，遠映征帆近拂堤。","繫得王孫歸意切，不關春草綠萋萋。"]', '["館娃宮外鄴城西，远映征帆近拂堤。","繫得王孫归意切，不关春草綠萋萋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a8de963-4820-4dbf-9dbb-152cbfb3770b', '雜曲歌辭 楊柳枝 六', '杂曲歌辞 楊柳枝 六', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["兩兩黃鸝色似金，嫋枝啼露動芳音。","春來幸自長如線，可惜牽纏蕩子心。"]', '["兩兩黄鸝色似金，嫋枝啼露动芳音。","春来幸自长如線，可惜牽纏蕩子心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 六 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2baec0cf-057f-451f-a85b-e68498daa912', '雜曲歌辭 楊柳枝 七', '杂曲歌辞 楊柳枝 七', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["御柳如絲映九重，鳳凰窗柱繡芙蓉。","景陽樓伴千條露，一面新妝待曉鍾。"]', '["御柳如絲映九重，鳳凰窗柱繡芙蓉。","景陽楼伴千條露，一面新妝待晓鍾。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 七 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133b4d40-ef24-4056-b825-9084969e7d0f', '雜曲歌辭 楊柳枝 八', '杂曲歌辞 楊柳枝 八', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["織錦機邊鶯語頻，停梭垂淚憶征人。","塞門三月猶蕭索，縱有垂楊未覺春。"]', '["织錦機邊鶯語頻，停梭垂泪憶征人。","塞门三月猶蕭索，縱有垂楊未覺春。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 八 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cfbda92-0eca-4326-84ff-29d47fbf85fd', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["春入行宮映翠微，玄宗侍女舞烟絲。","如今柳向空城綠，玉笛何人更把吹。"]', '["春入行宮映翠微，玄宗侍女舞烟絲。","如今柳向空城綠，玉笛何人更把吹。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f578ab9-742f-4b95-b53e-984209c4bbb2', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["爛熳春歸水國時，吳王宮殿柳垂絲。","黃鶯長呌空閨畔，西子無因更得知。"]', '["爛熳春归水国时，吳王宮殿柳垂絲。","黄鶯长呌空閨畔，西子無因更得知。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3298dac3-8bd3-440e-b4c2-463633a3373d', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["鳳樓高映綠陰陰，凝碧多含雨露深。","莫謂一枝柔軟力，幾曾牽破別離心。"]', '["鳳楼高映綠陰陰，凝碧多含雨露深。","莫謂一枝柔軟力，幾曾牽破別離心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37592b5c-0fd6-4d9a-828e-e7c6f7adccff', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["館娃宮畔響廊前，依託吳王養翠煙。","劒去國亡臺榭毀，却隨紅樹噪秋蟬。"]', '["館娃宮畔响廊前，依託吳王養翠煙。","劒去国亡台榭毀，却隨紅樹噪秋蟬。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4ddbbfb-d0c7-4800-972c-0c6e9f708f0c', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["穠低似中陶潛酒，軟極如傷宋玉風。","多謝將軍遶營種，翠中閑卓戰旗紅。"]', '["穠低似中陶潛酒，軟極如傷宋玉风。","多謝將軍遶營種，翠中闲卓戰旗紅。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68d7789-eef5-4c31-859a-74c28a8f4237', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["高僧愛惜遮江寺，遊子傷殘露野橋。","爭似著行垂上苑，碧桃紅杏對搖搖。"]', '["高僧愛惜遮江寺，游子傷殘露野橋。","爭似著行垂上苑，碧桃紅杏对搖搖。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353f48c1-b347-499a-a0c0-ed3f08740f1a', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["莫折宮前楊柳枝，玄宗曾向笛中吹。","傷心日暮煙霞起，無限春愁生翠眉。"]', '["莫折宮前楊柳枝，玄宗曾向笛中吹。","傷心日暮煙霞起，無限春愁生翠眉。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0a7d66-b63c-447b-ad4f-243373f868f2', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["凝碧池邊斂翠眉，景陽臺下綰青絲。","那勝妃子朝元閣，玉手和煙弄一枝。"]', '["凝碧池邊斂翠眉，景陽台下綰青絲。","那勝妃子朝元閣，玉手和煙弄一枝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('975a3b4e-ac73-41a7-bdff-616462179a5f', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["靈和風暖太昌春，舞線搖絲向昔人。","何似曉來江雨後，一行如畫隔遙津。"]', '["靈和风暖太昌春，舞線搖絲向昔人。","何似晓来江雨後，一行如畫隔遙津。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d37c0944-3e2e-4119-9cb0-1c538421dc88', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["彭澤初栽五樹時，只應閑看一枝枝。","不知天意風流處，要與佳人學畫眉。"]', '["彭澤初栽五樹时，只應闲看一枝枝。","不知天意风流处，要與佳人学畫眉。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49c6ed5-cfe9-4e7f-887b-09c32f5ea770', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["暖傍離亭靜拂橋，入流穿檻綠搖搖。","不知落日誰相送，魂斷千條與萬條。"]', '["暖傍離亭静拂橋，入流穿檻綠搖搖。","不知落日誰相送，魂斷千條與万條。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d1ec36-3569-4bd3-9f05-b4f067dcf9c6', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["春來綠樹遍天涯，未見垂楊未可誇。","晴日萬株烟一陣，閑坊兼是莫愁家。"]', '["春来綠樹遍天涯，未见垂楊未可誇。","晴日万株烟一陣，闲坊兼是莫愁家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449f2973-8648-4608-b5fa-ef40cc98ce69', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["十首當年有舊詞，唱青歌翠幾無遺。","未曾得向行人道，不爲離情莫折伊。"]', '["十首當年有旧词，唱青歌翠幾無遺。","未曾得向行人道，不爲離情莫折伊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15fdfac2-e4e5-4b8a-b766-47eb1c570459', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["華清高樹出離宮，南陌柔條帶暖風。","誰見輕陰是良夜，瀑泉聲畔月明中。"]', '["华清高樹出離宮，南陌柔條带暖风。","誰见轻陰是良夜，瀑泉声畔月明中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1d44017-5866-4cfb-86c1-7b7230ed9794', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["洛橋晴影覆江船，羌笛秋聲濕塞烟。","閑想習池公宴罷，水蒲風絮夕陽天。"]', '["洛橋晴影覆江船，羌笛秋声濕塞烟。","闲想習池公宴罷，水蒲风絮夕陽天。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fa9828-5ffe-4e34-a086-1906dcfa0edd', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["嫩綠輕懸似綴旒，路人遙見隔宮樓。","誰能更近丹墀種，解播皇風入九州。"]', '["嫩綠轻懸似綴旒，路人遙见隔宮楼。","誰能更近丹墀種，解播皇风入九州。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91f24a2-63c5-4a21-b733-94c8e94e3079', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["暖風晴日斷浮埃，廢路新條發釣臺。","處處輕輕可惆悵，後人攀處古人栽。"]', '["暖风晴日斷浮埃，廢路新條發釣台。","处处轻轻可惆悵，後人攀处古人栽。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8072e986-45ef-45ed-beb8-040dbc6faeb9', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["潭上江邊嫋嫋垂，日高風靜絮相隨。","青樓一樹無人見，正是女郎眠覺時。"]', '["潭上江邊嫋嫋垂，日高风静絮相隨。","青楼一樹無人见，正是女郎眠覺时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e5a4d7-0cbe-4661-af19-f8a890c39258', '雜曲歌辭 楊柳枝 六', '杂曲歌辞 楊柳枝 六', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["汴水高懸百萬條，風清兩岸一時搖。","隋家力盡虛栽得，無限春風屬聖朝。"]', '["汴水高懸百万條，风清兩岸一时搖。","隋家力尽虛栽得，無限春风屬聖朝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 六 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68465420-aa16-40f1-9135-c98161bc0b2d', '雜曲歌辭 楊柳枝 七', '杂曲歌辞 楊柳枝 七', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["和花烟樹九重城，夾路春陰十萬營。","唯向邊頭不堪望，一株顦顇少人行。"]', '["和花烟樹九重城，夾路春陰十万營。","唯向邊头不堪望，一株顦顇少人行。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 七 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f350f56a-236f-47b2-b5c3-88af4f812bc2', '雜曲歌辭 楊柳枝 八', '杂曲歌辞 楊柳枝 八', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["窗外齊垂旭日初，樓邊輕好暖風徐。","遊人莫道栽無益，桃李清陰却不如。"]', '["窗外齊垂旭日初，楼邊轻好暖风徐。","游人莫道栽無益，桃李清陰却不如。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 八 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce40b604-9dbf-4a8b-be5f-1087991411d2', '雜曲歌辭 楊柳枝 九', '杂曲歌辞 楊柳枝 九', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["衆木猶寒獨早青，御溝橋畔曲江亭。","陶家舊日應如此，一院春條綠遶廳。"]', '["衆木猶寒独早青，御溝橋畔曲江亭。","陶家旧日應如此，一院春條綠遶廳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 九 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7368668e-9eaa-47fc-a801-a4405e2d9b1c', '雜曲歌辭 楊柳枝 十', '杂曲歌辞 楊柳枝 十', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["帳偃纓垂細復繁，令人心想石家園。","風條月影皆堪重，何事侯門愛樹萱。"]', '["帳偃纓垂細复繁，令人心想石家园。","风條月影皆堪重，何事侯门愛樹萱。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 十 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4568b1d2-ed9f-4bbd-9947-064410a234a1', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["數首新詞帶恨成，柳絲牽我我傷情。","柔娥幸有腰支穩，試踏吹聲作唱聲。"]', '["數首新词带恨成，柳絲牽我我傷情。","柔娥幸有腰支穩，試踏吹声作唱声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e26ce07-d2d2-43d0-a4cc-7d9a429e6b9f', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["高出軍營遠映橋，賊兵曾斫火曾燒。","風流性在終難改，依舊春來萬萬條。"]', '["高出軍營远映橋，賊兵曾斫火曾燒。","风流性在終难改，依旧春来万万條。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f316508-f241-44b3-82c1-7c186ac94926', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["縣依陶令想嫌迂，營伴將軍即大麤。","此日與君除萬恨，數篇風調更應無。"]', '["縣依陶令想嫌迂，營伴將軍即大麤。","此日與君除万恨，數篇风調更應無。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f355cdf3-b0a6-464b-861a-470d7e0f6679', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["狂似纖腰軟勝綿，自多情態更誰憐。","遊人不折還堪恨，拋向橋邊與路邊。"]', '["狂似纖腰軟勝綿，自多情態更誰怜。","游人不折還堪恨，拋向橋邊與路邊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cf97cf0-3351-4ed8-b21f-5f5e4055194c', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["朝陽晴照綠楊烟，一別通波十七年。","應有舊枝無處覓，萬株風裏卓旌旃。"]', '["朝陽晴照綠楊烟，一別通波十七年。","應有旧枝無处覓，万株风裏卓旌旃。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39efc34-25d1-4773-9972-a9c79611eaaf', '雜曲歌辭 楊柳枝 六', '杂曲歌辞 楊柳枝 六', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["晴垂芳態吐牙新，雨擺輕條濕面春。"]', '["晴垂芳態吐牙新，雨擺轻條濕面春。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 六 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f92b6d4-b559-4e84-85e7-a8e7232502e2', '雜曲歌辭 楊柳枝 七', '杂曲歌辞 楊柳枝 七', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["暖梳簪朵事登樓，因挂垂楊立地愁。","牽斷綠絲攀不得，半空懸著玉搔頭。"]', '["暖梳簪朵事登楼，因挂垂楊立地愁。","牽斷綠絲攀不得，半空懸著玉搔头。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 七 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64583f72-708b-4491-9062-569139e487e0', '雜曲歌辭 楊柳枝 八', '杂曲歌辞 楊柳枝 八', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["西園高樹後庭根，處處尋芳有折痕。","終憶舊遊桃葉舍，一株斜映竹籬門。"]', '["西园高樹後庭根，处处尋芳有折痕。","終憶旧游桃葉舍，一株斜映竹籬门。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 八 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('995df10a-d084-450a-8a24-be1df69c6b6d', '雜曲歌辭 楊柳枝 九', '杂曲歌辞 楊柳枝 九', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["劉白蘇臺總近時，當初章句是誰推。","纖腰舞盡春楊柳，未有儂家一首詩。"]', '["劉白蘇台總近时，當初章句是誰推。","纖腰舞尽春楊柳，未有儂家一首诗。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 九 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77530e99-324a-4ce4-aeeb-986eea8c56c5', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["解凍風來末上青，解垂羅袖拜卿卿。","無端嫋娜臨官路，舞送行人過一生。"]', '["解凍风来末上青，解垂羅袖拜卿卿。","無端嫋娜臨官路，舞送行人過一生。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('418f0aad-1246-43c7-a2c1-923a7e133506', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["吳王宮裏色偏深，一簇纖條萬縷金。","不憤錢塘蘇小小，引郎枝下結同心。"]', '["吳王宮裏色偏深，一簇纖條万縷金。","不憤錢塘蘇小小，引郎枝下結同心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3537415c-e55b-452e-a231-35ceb376ee56', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["橋北橋南千萬條，恨伊張緒不相饒。","金羈白馬臨風望，認得羊家靜婉腰。"]', '["橋北橋南千万條，恨伊張緒不相饒。","金羈白马臨风望，認得羊家静婉腰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8419d199-45c2-4b1c-bf48-822198b24712', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["狂雪隨風撲馬飛，惹烟無力被風欹。","莫交移入靈和殿，宮女三千又妒伊。"]', '["狂雪隨风撲马飞，惹烟無力被风欹。","莫交移入靈和殿，宮女三千又妒伊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30d40e41-070f-4314-b279-17123fa9fc5a', '雜曲歌辭 楊柳枝 五', '杂曲歌辞 楊柳枝 五', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["裊翠籠煙拂暖波，舞裙新染麴塵羅。","章華臺畔隋堤上，倚得春風爾許多。"]', '["裊翠籠煙拂暖波，舞裙新染麴塵羅。","章华台畔隋堤上，倚得春风爾許多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 五 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f5b1c7-ca64-4ad1-8d52-158de29be63d', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["軟碧搖煙似送人，映花時把翠眉嚬。","青青自是風流主，漫颭金絲待洛神。"]', '["軟碧搖煙似送人，映花时把翠眉嚬。","青青自是风流主，漫颭金絲待洛神。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d9f990-20ad-456b-827d-dacd6ea09a70', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["瑟瑟羅裙金縷腰，黛眉偎破未重描。","醉來咬損新花子，拽住仙郎儘放嬌。"]', '["瑟瑟羅裙金縷腰，黛眉偎破未重描。","醉来咬損新花子，拽住仙郎儘放嬌。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d21445d0-930f-43ac-b31b-de28e5ec6e6b', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["鵲橋初就咽銀河，今夜仙郎自性和。","不是昔年攀桂樹，豈能月裏索姮娥。"]', '["鵲橋初就咽銀河，今夜仙郎自性和。","不是昔年攀桂樹，豈能月裏索姮娥。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d921b6-4f1c-4c4e-8947-febee301c85c', '雜曲歌辭 楊柳枝 一', '杂曲歌辞 楊柳枝 一', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["閭門風暖落花乾，飛遍江南雪不寒。","獨有晚來臨水驛，閑人多凭赤闌干。"]', '["閭门风暖落花乾，飞遍江南雪不寒。","独有晚来臨水驛，闲人多凭赤闌干。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 一 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6aba936-75bb-4b3b-a888-8444a74d0f93', '雜曲歌辭 楊柳枝 二', '杂曲歌辞 楊柳枝 二', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["有池有榭即濛濛，浸潤翻成長養功。","恰似有人長點檢，著行排立向春風。"]', '["有池有榭即濛濛，浸潤翻成长養功。","恰似有人长点檢，著行排立向春风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 二 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e88d5283-8031-4ecf-b613-826783d40296', '雜曲歌辭 楊柳枝 三', '杂曲歌辞 楊柳枝 三', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["根柢雖然傍濁河，無妨終日近笙歌。","驂驂金帶誰堪比，還笑黃鶯不較多。"]', '["根柢雖然傍濁河，無妨終日近笙歌。","驂驂金带誰堪比，還笑黄鶯不較多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 三 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e8d143-9385-411c-93ff-57b99918841a', '雜曲歌辭 楊柳枝 四', '杂曲歌辞 楊柳枝 四', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["萬株枯槁怨亡隋，似弔吳臺各自垂。","好是淮陰明月裏，酒樓橫笛不勝吹。"]', '["万株枯槁怨亡隋，似弔吳台各自垂。","好是淮陰明月裏，酒楼橫笛不勝吹。"]', '诗', 'shi', '', NULL, '雜曲歌辭 楊柳枝 四 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52598ca7-8d4b-40c4-9814-e82a51ec379d', '雜曲歌辭 浪淘沙 一', '杂曲歌辞 浪淘沙 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["九曲黃河萬里沙，浪淘風簸自天涯。","如今直上銀河去，同到牽牛織女家。"]', '["九曲黄河万里沙，浪淘风簸自天涯。","如今直上銀河去，同到牽牛织女家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc30758f-4193-49ff-af8d-dbc8695f082b', '雜曲歌辭 浪淘沙 二', '杂曲歌辞 浪淘沙 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["洛水橋邊春日斜，碧流輕淺見瓊沙。","無端陌上狂風急，驚起鴛鴦出浪花。"]', '["洛水橋邊春日斜，碧流轻淺见瓊沙。","無端陌上狂风急，驚起鴛鴦出浪花。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e0c0380-f696-4e39-ab6b-116e307d07cd', '雜曲歌辭 浪淘沙 三', '杂曲歌辞 浪淘沙 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["汴水東流虎眼文，清淮曉色鴨頭春。","君看渡口淘沙處，渡却人間多少人。"]', '["汴水东流虎眼文，清淮晓色鴨头春。","君看渡口淘沙处，渡却人间多少人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('529c0d3e-48e1-4c90-b552-53472032523c', '雜曲歌辭 浪淘沙 四', '杂曲歌辞 浪淘沙 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["鸚鵡洲頭浪颭沙，青樓春望日將斜。","銜泥燕子爭歸舍，獨自狂夫不憶家。"]', '["鸚鵡洲头浪颭沙，青楼春望日將斜。","銜泥燕子爭归舍，独自狂夫不憶家。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0980785c-7c0b-4dad-8ce9-7412dab56f0e', '雜曲歌辭 浪淘沙 五', '杂曲歌辞 浪淘沙 五', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["濯錦江邊兩岸花，春風吹浪正淘沙。","女郎剪下鴛鴦錦，將向中流疋晚霞。"]', '["濯錦江邊兩岸花，春风吹浪正淘沙。","女郎剪下鴛鴦錦，將向中流疋晚霞。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 五 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29b3e4b-125f-4b2f-a0fb-44e5d40694f5', '雜曲歌辭 浪淘沙 六', '杂曲歌辞 浪淘沙 六', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日照澄洲江霧開，淘金女伴滿江隈。","美人首飾侯王印，盡是沙中浪底來。"]', '["日照澄洲江霧开，淘金女伴满江隈。","美人首飾侯王印，尽是沙中浪底来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 六 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff1a5ac4-3d25-4735-a33a-175b394c5d88', '雜曲歌辭 浪淘沙 七', '杂曲歌辞 浪淘沙 七', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["八月濤聲吼地來，頭高數丈觸山迴。","須臾却入海門去，卷起沙堆似雪堆。"]', '["八月濤声吼地来，头高數丈觸山迴。","須臾却入海门去，卷起沙堆似雪堆。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 七 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4d7c75-238b-4f92-917c-bcdf16e8c7a4', '雜曲歌辭 浪淘沙 八', '杂曲歌辞 浪淘沙 八', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["莫道讒言如浪深，莫言遷客似沙沈。","千淘萬漉雖辛苦，吹盡狂沙始到金。"]', '["莫道讒言如浪深，莫言遷客似沙沈。","千淘万漉雖辛苦，吹尽狂沙始到金。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 八 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe65ba74-a10a-460f-b406-7ede22d6b4db', '雜曲歌辭 浪淘沙 九', '杂曲歌辞 浪淘沙 九', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["流水淘沙不暫停，前波未滅後波生。","令人忽憶瀟湘渚，迴唱迎神三兩聲。"]', '["流水淘沙不暫停，前波未滅後波生。","令人忽憶瀟湘渚，迴唱迎神三兩声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 九 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c752d8-19ad-4fb6-997c-372f0feb2ddc', '雜曲歌辭 浪淘沙 一', '杂曲歌辞 浪淘沙 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一泊沙來一泊去，一重浪滅一重生。","相攪相淘無歇日，會交山海一時平。"]', '["一泊沙来一泊去，一重浪滅一重生。","相攪相淘無歇日，會交山海一时平。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f2e998-354c-4294-a226-f1e86fb44df0', '雜曲歌辭 浪淘沙 二', '杂曲歌辞 浪淘沙 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白浪茫茫與海連，平沙浩浩四無邊。","暮去朝來淘不住，遂令東海變桑田。"]', '["白浪茫茫與海連，平沙浩浩四無邊。","暮去朝来淘不住，遂令东海变桑田。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efea582-e182-40d2-bdc6-e8f3ca1aa341', '雜曲歌辭 浪淘沙 三', '杂曲歌辞 浪淘沙 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青草湖中萬里程，黃梅雨裏一人行。","愁見灘頭夜泊處，風翻暗浪打船聲。"]', '["青草湖中万里程，黄梅雨裏一人行。","愁见灘头夜泊处，风翻暗浪打船声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84b9b43-e843-4bdd-b17d-1b08a0b2739b', '雜曲歌辭 浪淘沙 四', '杂曲歌辞 浪淘沙 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["借問江湖與海水，何似君情與妾心。","相恨不如潮有信，相思始覺海非深。"]', '["借问江湖與海水，何似君情與妾心。","相恨不如潮有信，相思始覺海非深。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d413cfff-0a86-4664-9cba-b6f83972c332', '雜曲歌辭 浪淘沙 五', '杂曲歌辞 浪淘沙 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海底飛塵終有日，山頭化石豈無時。","誰道小郎拋小婦，船頭一去沒迴期。"]', '["海底飞塵終有日，山头化石豈無时。","誰道小郎拋小婦，船头一去沒迴期。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42435311-9d8b-476d-96b3-20f36c22325b', '雜曲歌辭 浪淘沙 六', '杂曲歌辞 浪淘沙 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隨波逐浪到天涯，遷客生還有幾家。","却到帝鄉重富貴，請君莫忘浪淘沙。"]', '["隨波逐浪到天涯，遷客生還有幾家。","却到帝乡重富貴，請君莫忘浪淘沙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96ade28-3647-489f-b892-e404be2b6c26', '雜曲歌辭 浪淘沙 一', '杂曲歌辞 浪淘沙 一', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["灘頭細草接疎林，浪惡罾船半欲沈。","宿鷺眠洲非舊浦，去年沙觜是江心。"]', '["灘头細草接疎林，浪惡罾船半欲沈。","宿鷺眠洲非旧浦，去年沙觜是江心。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 一 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('259186b3-61f5-4a2f-9e97-9af5e32a4fdd', '雜曲歌辭 浪淘沙 二', '杂曲歌辞 浪淘沙 二', '37062e0e-9110-41cd-9fa9-382cc9ed45d4', '唐', '["蠻歌豆蔻北人愁，松雨蒲風夜艇秋。","浪起鵁鶄眠不得，寒沙細細入江流。"]', '["蠻歌豆蔻北人愁，松雨蒲风夜艇秋。","浪起鵁鶄眠不得，寒沙細細入江流。"]', '诗', 'shi', '', NULL, '雜曲歌辭 浪淘沙 二 皇甫松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('180ab533-0c67-4513-b77d-268b0bfbac0e', '雜曲歌辭 紇那曲 一', '杂曲歌辞 紇那曲 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["楊柳鬱青青，竹枝無限情。","同郎一回顧，聽唱紇那聲。"]', '["楊柳鬱青青，竹枝無限情。","同郎一回顧，听唱紇那声。"]', '诗', 'shi', '', NULL, '雜曲歌辭 紇那曲 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103d5c6f-d81f-4350-9208-82a04347c662', '雜曲歌辭 紇那曲 二', '杂曲歌辞 紇那曲 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["踏曲興無窮，調同詞不同。","願郎千萬壽，長作主人翁。"]', '["踏曲兴無窮，調同词不同。","願郎千万壽，长作主人翁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 紇那曲 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a0ec327-a23d-4dec-aa45-2ff058ef8579', '雜曲歌辭 瀟湘神二曲 一', '杂曲歌辞 瀟湘神二曲 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["湘水流，湘水流，九疑雲物至今愁。","君問二妃何處所？零陵香草露中秋。"]', '["湘水流，湘水流，九疑云物至今愁。","君问二妃何处所？零陵香草露中秋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 瀟湘神二曲 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c3c5caf-0800-47ea-99b6-05dc96cd6cbd', '雜曲歌辭 瀟湘神二曲 二', '杂曲歌辞 瀟湘神二曲 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["斑竹枝，斑竹枝，淚痕點點寄相思。","楚客欲聽瑤瑟怨，瀟湘深夜月明時。"]', '["斑竹枝，斑竹枝，泪痕点点寄相思。","楚客欲听瑤瑟怨，瀟湘深夜月明时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 瀟湘神二曲 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9901206-250a-4157-863a-fb6a2f4113af', '雜曲歌辭 拋毬樂 一', '杂曲歌辞 拋毬乐 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["五綵繡團團，登君玳瑁筵。","最宜紅燭下，偏稱落花前。","上客如先起，應須贈一船。"]', '["五綵繡團團，登君玳瑁筵。","最宜紅燭下，偏稱落花前。","上客如先起，應須贈一船。"]', '诗', 'shi', '', NULL, '雜曲歌辭 拋毬樂 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69232a1f-6d59-4055-b3fc-d235ce463406', '雜曲歌辭 拋毬樂 二', '杂曲歌辞 拋毬乐 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春早見花枝，朝朝恨發遲。","及看花落後，却憶未開時。","幸有拋毬樂，一杯君莫辭。"]', '["春早见花枝，朝朝恨發遲。","及看花落後，却憶未开时。","幸有拋毬乐，一杯君莫辞。"]', '诗', 'shi', '', NULL, '雜曲歌辭 拋毬樂 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acdced11-4d57-4972-86ca-857760554500', '雜曲歌辭 太平樂 一', '杂曲歌辞 太平乐 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲豐仍節儉，時泰更銷兵。","聖念長如此，何憂不太平。"]', '["歲豐仍節儉，时泰更銷兵。","聖念长如此，何憂不太平。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太平樂 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b6120ba-8af3-4172-9efe-a90d38f4d10f', '雜曲歌辭 太平樂 二', '杂曲歌辞 太平乐 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湛露浮堯酒，薰風起舜歌。","願同堯舜意，所樂在人和。"]', '["湛露浮堯酒，薰风起舜歌。","願同堯舜意，所乐在人和。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太平樂 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41291a11-919c-4007-af8a-8fc503de866a', '雜曲歌辭 太平樂', '杂曲歌辞 太平乐', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["風俗今和厚，君王在穆清。","行看采花曲，盡是太階平。"]', '["风俗今和厚，君王在穆清。","行看采花曲，尽是太階平。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太平樂 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd7f91f-9022-4396-b34e-390a0746680a', '雜曲歌辭 太平樂', '杂曲歌辞 太平乐', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["聖德超千古，皇威靜四方。","蒼生今息戰，無事覺時長。"]', '["聖德超千古，皇威静四方。","蒼生今息戰，無事覺时长。"]', '诗', 'shi', '', NULL, '雜曲歌辭 太平樂 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e837b2b0-b44b-4d86-b9b1-043ab9774cd5', '雜曲歌辭 昇平樂 一', '杂曲歌辞 昇平乐 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["正氣遶宮樓，皇居信上遊。","遠岡延聖祚，平地載神州。","會合皆重譯，潺湲近八流。","中興豈假問，據此自千秋。"]', '["正氣遶宮楼，皇居信上游。","远岡延聖祚，平地載神州。","會合皆重譯，潺湲近八流。","中兴豈假问，據此自千秋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00addf50-d832-47a4-85a1-ff8796bd5edb', '雜曲歌辭 昇平樂 二', '杂曲歌辞 昇平乐 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["寥泬敞延英，朝班立位橫。","宣傳無草動，拜舞有衣聲。","鴛瓦雲消濕，蟲絲日照明。","辛勤自不到，遙見似前生。"]', '["寥泬敞延英，朝班立位橫。","宣傳無草动，拜舞有衣声。","鴛瓦云消濕，蟲絲日照明。","辛勤自不到，遙见似前生。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('515a01f6-41e7-4625-ba41-eb834abe7803', '雜曲歌辭 昇平樂 三', '杂曲歌辞 昇平乐 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["處處足歡聲，時康歲已深。","不同三尺劒，應似五絃琴。","壽笑山猶盡，明嫌日有陰。","何當憐一物，亦遣斷愁吟。"]', '["处处足歡声，时康歲已深。","不同三尺劒，應似五絃琴。","壽笑山猶尽，明嫌日有陰。","何當怜一物，亦遣斷愁吟。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d97b17ac-4563-4046-a953-42837eb64a8f', '雜曲歌辭 昇平樂 四', '杂曲歌辞 昇平乐 四', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["曙質絕埃氛，彤庭列禁軍。","聖顏初對日，龍尾競緣雲。","珮響交成韻，簾陰暖帶紋。","逍遙豈有事，於此詠南薰。"]', '["曙質絕埃氛，彤庭列禁軍。","聖顏初对日，龙尾競緣云。","珮响交成韻，簾陰暖带紋。","逍遙豈有事，於此詠南薰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 四 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73d5a3e5-e678-458d-b62a-8d73ca6043dc', '雜曲歌辭 昇平樂 五', '杂曲歌辞 昇平乐 五', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["一物周天至，洪纖盡晏然。","車書無異俗，甲子竝豐年。","奇技皆歸朴，征夫亦服田。","君王故不有，台鼎合韋弦。"]', '["一物周天至，洪纖尽晏然。","车书無異俗，甲子竝豐年。","奇技皆归朴，征夫亦服田。","君王故不有，台鼎合韋弦。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 五 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b7e0702-6145-454a-9e1b-4c64fb357804', '雜曲歌辭 昇平樂 六', '杂曲歌辞 昇平乐 六', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["日日聽歌謠，區中盡祝堯。","蟲蝗初不害，夷狄近全銷。","史筆唯書瑞，天臺絕見祆。","因令匹夫志，轉欲事清朝。"]', '["日日听歌謠，區中尽祝堯。","蟲蝗初不害，夷狄近全銷。","史笔唯书瑞，天台絕见祆。","因令匹夫志，轉欲事清朝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 六 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4396e12f-b7af-4d77-980b-8ada24e1009e', '雜曲歌辭 昇平樂 七', '杂曲歌辞 昇平乐 七', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["品物盡昭蘇，神功復帝謨。","他時應有壽，當代且無虞。","賜曆通遐俗，移關入半胡。","鷦鷯一何幸，於此寄微軀。"]', '["品物尽昭蘇，神功复帝謨。","他时應有壽，當代且無虞。","賜曆通遐俗，移关入半胡。","鷦鷯一何幸，於此寄微軀。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 七 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a7b745a-4764-4c5d-bc09-f1d06da27bb0', '雜曲歌辭 昇平樂 八', '杂曲歌辞 昇平乐 八', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["無戰復無私，堯時即此時。","焚香臨極早，待月卷簾遲。","端拱乾坤內，何言黈纊垂。","君看聖明驗，只此是神龜。"]', '["無戰复無私，堯时即此时。","焚香臨極早，待月卷簾遲。","端拱乾坤內，何言黈纊垂。","君看聖明驗，只此是神龟。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 八 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133d8de1-7491-465f-b6e5-8aa16c7fcb29', '雜曲歌辭 昇平樂 九', '杂曲歌辞 昇平乐 九', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["旭日上清穹，明堂坐聖聰。","衣裳承瑞氣，冠冕蓋重曈。","花木經宵露，旌旗立仗風。","何期於此地，見說似仙宮。"]', '["旭日上清穹，明堂坐聖聰。","衣裳承瑞氣，冠冕蓋重曈。","花木經宵露，旌旗立仗风。","何期於此地，见说似仙宮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 九 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1505b3fd-6f22-4fb6-aa75-c11e19a160ce', '雜曲歌辭 昇平樂 十', '杂曲歌辞 昇平乐 十', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["五帝三皇主，蕭曹魏邴臣。","文章惟反朴，戈甲盡生塵。","諫紙應無用，朝綱自有倫。","昇平不可紀，所見是閑人。"]', '["五帝三皇主，蕭曹魏邴臣。","文章惟反朴，戈甲尽生塵。","諫紙應無用，朝綱自有倫。","昇平不可紀，所见是闲人。"]', '诗', 'shi', '', NULL, '雜曲歌辭 昇平樂 十 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8617715-ad59-4da8-8071-e9aeb1760e6a', '雜曲歌辭 金縷衣', '杂曲歌辞 金縷衣', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["勸君莫惜金縷衣，勸君惜取少年時。","花開堪折直須折，莫待無花空折枝。"]', '["勸君莫惜金縷衣，勸君惜取少年时。","花开堪折直須折，莫待無花空折枝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 金縷衣 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80df557-f7fa-4a5c-89f5-29722daf7412', '雜曲歌辭 鳳歸雲 一', '杂曲歌辞 鳳归云 一', '3a0ad6d9-6176-4bcc-a8f7-ddbaf56950ca', '唐', '["金井欄邊見羽儀，梧桐樹上宿寒枝。","五陵公子憐文綵，畫與佳人刺繡衣。"]', '["金井欄邊见羽儀，梧桐樹上宿寒枝。","五陵公子怜文綵，畫與佳人刺繡衣。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鳳歸雲 一 滕潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd22b9a5-8bcc-48db-8572-276d97b97b38', '雜曲歌辭 鳳歸雲 二', '杂曲歌辞 鳳归云 二', '3a0ad6d9-6176-4bcc-a8f7-ddbaf56950ca', '唐', '["飲啄蓬山最上頭，和烟飛下禁城秋。","曾將弄玉歸雲去，金翿斜開十二樓。"]', '["饮啄蓬山最上头，和烟飞下禁城秋。","曾將弄玉归云去，金翿斜开十二楼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 鳳歸雲 二 滕潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22991a8-329e-4ec2-9c1e-b0648d7ab01b', '雜曲歌辭 拜新月', '杂曲歌辞 拜新月', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["開簾見新月，便即下階拜。","細語人不聞，北風吹裙帶。"]', '["开簾见新月，便即下階拜。","細語人不闻，北风吹裙带。"]', '诗', 'shi', '', NULL, '雜曲歌辭 拜新月 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('452ca2e5-a3f8-4dd1-b262-6ba2af5f3ea3', '雜曲歌辭 拜新月', '杂曲歌辞 拜新月', 'f9765ecf-c84b-4375-8e42-4057ae14eca1', '唐', '["拜新月，拜月出堂前。","暗魄深籠桂，虛弓未引弦。","拜新月，拜月妝樓上。","鸞鏡未安臺，蛾眉已相向。","拜新月，拜月不勝情，庭前風露清。","月臨人自老，望月更長生。","東家阿母亦拜月，一拜一悲聲斷絕。","昔年拜月逞容儀，如今拜月雙淚垂。","回看衆女拜新月，却憶紅閨年少時。"]', '["拜新月，拜月出堂前。","暗魄深籠桂，虛弓未引弦。","拜新月，拜月妝楼上。","鸾镜未安台，蛾眉已相向。","拜新月，拜月不勝情，庭前风露清。","月臨人自老，望月更长生。","东家阿母亦拜月，一拜一悲声斷絕。","昔年拜月逞容儀，如今拜月雙泪垂。","回看衆女拜新月，却憶紅閨年少时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 拜新月 吉中孚妻張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae558bdc-1af9-404f-887e-d65e4c57a166', '雜曲歌辭 憶江南 一', '杂曲歌辞 憶江南 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南好，風景舊曾諳。"]', '["江南好，风景旧曾諳。"]', '诗', 'shi', '', NULL, '雜曲歌辭 憶江南 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fccef71a-e31a-4cc4-980b-f1122d7043e2', '雜曲歌辭 憶江南 二', '杂曲歌辞 憶江南 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南憶，最憶是杭州。"]', '["江南憶，最憶是杭州。"]', '诗', 'shi', '', NULL, '雜曲歌辭 憶江南 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03cfc7ce-df84-4edb-a044-a169d1535f89', '雜曲歌辭 憶江南 三', '杂曲歌辞 憶江南 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南憶，其次憶吳宮。","吳酒一杯春竹葉，吳娃雙舞醉芙蓉，早晚復相逢。"]', '["江南憶，其次憶吳宮。","吳酒一杯春竹葉，吳娃雙舞醉芙蓉，早晚复相逢。"]', '诗', 'shi', '', NULL, '雜曲歌辭 憶江南 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('636705d2-4664-4762-b616-0857814bba5e', '雜曲歌辭 憶江南 一', '杂曲歌辞 憶江南 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春過也，共惜豔陽年。","猶有桃花流水上，無辭竹葉醉樽前，惟待見青天。"]', '["春過也，共惜豔陽年。","猶有桃花流水上，無辞竹葉醉樽前，惟待见青天。"]', '诗', 'shi', '', NULL, '雜曲歌辭 憶江南 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f23cbd2-c44c-4e09-af67-32bf12a463a2', '雜曲歌辭 憶江南 二', '杂曲歌辞 憶江南 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春去也，多謝洛城人。","弱柳從風疑舉袂，叢蘭裛露似霑巾，獨笑亦含嚬。"]', '["春去也，多謝洛城人。","弱柳從风疑舉袂，叢蘭裛露似霑巾，独笑亦含嚬。"]', '诗', 'shi', '', NULL, '雜曲歌辭 憶江南 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ca6564-0ee2-4b05-8666-b0208aebe17b', '雜曲歌辭 宮中調笑 一', '杂曲歌辞 宮中調笑 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["團扇，團扇，美人病來遮面。","玉顏憔悴三年，誰復商量管弦。","弦管，弦管，春草昭陽路斷。"]', '["團扇，團扇，美人病来遮面。","玉顏憔悴三年，誰复商量管弦。","弦管，弦管，春草昭陽路斷。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中調笑 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3116d012-d687-422e-8414-7fed23074cb6', '雜曲歌辭 宮中調笑 二', '杂曲歌辞 宮中調笑 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["胡蝶，胡蝶，飛上金花枝葉。","君前對舞春風，百葉桃花樹紅。","紅樹，紅樹，燕語鶯啼日暮。"]', '["胡蝶，胡蝶，飞上金花枝葉。","君前对舞春风，百葉桃花樹紅。","紅樹，紅樹，燕語鶯啼日暮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中調笑 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb619ecf-2c06-4948-a889-2fffd1cc1585', '雜曲歌辭 宮中調笑 三', '杂曲歌辞 宮中調笑 三', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["羅袖，羅袖，暗舞春風依舊。","遙看歌舞玉樓，好日新妝坐愁。","愁坐，愁坐，一世虛生虛過。"]', '["羅袖，羅袖，暗舞春风依旧。","遙看歌舞玉楼，好日新妝坐愁。","愁坐，愁坐，一世虛生虛過。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中調笑 三 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e6f3108-c72f-47d8-8fdf-42db8151d952', '雜曲歌辭 宮中調笑 四', '杂曲歌辞 宮中調笑 四', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["楊柳，楊柳，日暮白沙渡口。","船頭江水茫茫，商人少婦斷腸。","腸斷，腸斷，鷓鴣夜飛失伴。"]', '["楊柳，楊柳，日暮白沙渡口。","船头江水茫茫，商人少婦斷腸。","腸斷，腸斷，鷓鴣夜飞失伴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中調笑 四 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51458e21-16fe-46dd-bbce-466d8995dcec', '雜曲歌辭 宮中調笑 一', '杂曲歌辞 宮中調笑 一', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["胡馬，胡馬，遠放燕支山下。","咆沙咆雪獨嘶，東望西望路迷。","迷路，迷路，邊草無窮日暮。"]', '["胡马，胡马，远放燕支山下。","咆沙咆雪独嘶，东望西望路迷。","迷路，迷路，邊草無窮日暮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中調笑 一 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc254a8-0711-4e88-aa48-908d50d48364', '雜曲歌辭 宮中調笑 二', '杂曲歌辞 宮中調笑 二', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["河漢，河漢，曉挂秋城漫漫。","愁人起望相思，江南塞北別離。","離別，離別，河漢雖同路絕。"]', '["河漢，河漢，晓挂秋城漫漫。","愁人起望相思，江南塞北別離。","離別，離別，河漢雖同路絕。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中調笑 二 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64465c81-e318-49a7-9a36-924b59803c38', '雜曲歌辭 轉應詞', '杂曲歌辞 轉應词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["邊草，邊草，邊草盡來兵老。","山南山北雪晴，千里萬里月明。","明月，明月，胡笳一聲愁絕。"]', '["邊草，邊草，邊草尽来兵老。","山南山北雪晴，千里万里月明。","明月，明月，胡笳一声愁絕。"]', '诗', 'shi', '', NULL, '雜曲歌辭 轉應詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('107c1af3-4705-4b89-850e-e084085f36a4', '雜曲歌辭 宮中行樂詞 一', '杂曲歌辞 宮中行乐词 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小小生金屋，盈盈在紫微。","山花插寶髻，石竹繡羅衣。","每出深宮裏，常隨步輦歸。","只愁歌舞散，化作綵雲飛。"]', '["小小生金屋，盈盈在紫微。","山花插寶髻，石竹繡羅衣。","每出深宮裏，常隨步輦归。","只愁歌舞散，化作綵云飞。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20ca3373-a182-4906-985f-fd8e187fb57f', '雜曲歌辭 宮中行樂詞 二', '杂曲歌辞 宮中行乐词 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["柳色黃金嫩，梨花白雪香。","玉樓巢翡翠，金殿鎖鴛鴦。","選妓隨雕輦，徵歌出洞房。","宮中誰第一，飛燕在昭陽。"]', '["柳色黄金嫩，梨花白雪香。","玉楼巢翡翠，金殿鎖鴛鴦。","選妓隨雕輦，徵歌出洞房。","宮中誰第一，飞燕在昭陽。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('badc4095-7a06-4a24-ac6e-e341cede2f2c', '雜曲歌辭 宮中行樂詞 三', '杂曲歌辞 宮中行乐词 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["盧橘爲秦樹，蒲萄出漢宮。","煙花宜落日，絲管醉春風。","笛奏龍鳴水，簫吟鳳下空。","君王多樂事，何必向回中。"]', '["盧橘爲秦樹，蒲萄出漢宮。","煙花宜落日，絲管醉春风。","笛奏龙鳴水，簫吟鳳下空。","君王多乐事，何必向回中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd80c5d5-5ad6-4c2c-bb23-cafb578a4295', '雜曲歌辭 宮中行樂詞 四', '杂曲歌辞 宮中行乐词 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉樹春歸日，金宮樂事多。","後庭朝未入，輕輦夜相過。","笑出花間語，嬌來燭下歌。","莫教明月去，留著醉姮娥。"]', '["玉樹春归日，金宮乐事多。","後庭朝未入，轻輦夜相過。","笑出花间語，嬌来燭下歌。","莫教明月去，留著醉姮娥。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da8ea895-4886-4fd0-891b-02ef16d12f60', '雜曲歌辭 宮中行樂詞 五', '杂曲歌辞 宮中行乐词 五', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["繡戶香風暖，紗窗曙色新。","宮花爭笑日，池草暗生春。","綠樹聞歌鳥，青樓見舞人。","昭陽桃李月，羅綺自相親。"]', '["繡戶香风暖，紗窗曙色新。","宮花爭笑日，池草暗生春。","綠樹闻歌鸟，青楼见舞人。","昭陽桃李月，羅綺自相親。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 五 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf61fdf-ce02-4340-bb24-10f87e94b019', '雜曲歌辭 宮中行樂詞 六', '杂曲歌辞 宮中行乐词 六', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["今日明光裏，還須結伴遊。","春風開紫殿，天樂下珠樓。","豔舞全知巧，嬌歌半欲羞。","更憐花月夜，宮女笑藏鉤。"]', '["今日明光裏，還須結伴游。","春风开紫殿，天乐下珠楼。","豔舞全知巧，嬌歌半欲羞。","更怜花月夜，宮女笑藏鉤。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 六 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba15a6be-da1e-427f-9d4e-aa440f9951bc', '雜曲歌辭 宮中行樂詞 七', '杂曲歌辞 宮中行乐词 七', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["寒雪梅中盡，春風柳上歸。","宮鶯嬌欲醉，簷燕語還飛。","遲日明歌席，新花豔舞衣。","晚來移綵仗，行樂泥光輝。"]', '["寒雪梅中尽，春风柳上归。","宮鶯嬌欲醉，簷燕語還飞。","遲日明歌席，新花豔舞衣。","晚来移綵仗，行乐泥光輝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 七 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a67fa3fa-c2d8-4a9d-a4bf-142cbb7abb20', '雜曲歌辭 宮中行樂詞 八', '杂曲歌辞 宮中行乐词 八', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["水綠南薰殿，花紅北闕樓。","鶯歌聞太液，鳳吹遶瀛洲。","素女鳴珠佩，天人弄綵毬。","今朝風日好，宜入未央遊。"]', '["水綠南薰殿，花紅北闕楼。","鶯歌闻太液，鳳吹遶瀛洲。","素女鳴珠佩，天人弄綵毬。","今朝风日好，宜入未央游。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中行樂詞 八 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285f3aa7-dd99-4093-82d7-d1169be93f25', '雜曲歌辭 宮中樂 一', '杂曲歌辞 宮中乐 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["楚塞金陵靜，巴山玉壘空。","萬方無一事，端拱大明宮。"]', '["楚塞金陵静，巴山玉壘空。","万方無一事，端拱大明宮。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a80692d-16d6-4815-91d1-9ccdfbbd88fc', '雜曲歌辭 宮中樂 二', '杂曲歌辞 宮中乐 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["霜霽長楊苑，冰開太液池。","宮中行樂日，天下盛明時。"]', '["霜霽长楊苑，冰开太液池。","宮中行乐日，天下盛明时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb80cdf8-51f3-4c21-bc0c-0d91a06cf5aa', '雜曲歌辭 宮中樂 三', '杂曲歌辞 宮中乐 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["柳色烟相似，梨花雪不如。","春風真有意，一一麗皇居。"]', '["柳色烟相似，梨花雪不如。","春风真有意，一一丽皇居。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809956a8-dcaf-4277-9a71-fbce74051301', '雜曲歌辭 宮中樂 四', '杂曲歌辞 宮中乐 四', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["月上宮花靜，煙含苑樹深。","銀臺門已閉，仙漏夜沈沈。"]', '["月上宮花静，煙含苑樹深。","銀台门已閉，仙漏夜沈沈。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 四 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d97707a-791b-48dd-be26-9672cbdb6327', '雜曲歌辭 宮中樂 五', '杂曲歌辞 宮中乐 五', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["九重青鎖闥，百尺碧雲樓。","明月秋風起，珠簾上玉鉤。"]', '["九重青鎖闥，百尺碧云楼。","明月秋风起，珠簾上玉鉤。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 五 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac7c3a76-6aca-4818-8dd0-a2d6eb49fb21', '雜曲歌辭 宮中樂 一', '杂曲歌辞 宮中乐 一', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["網戶交如綺，紗窗薄似烟。","樂吹天上曲，人是月中仙。"]', '["網戶交如綺，紗窗薄似烟。","乐吹天上曲，人是月中仙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 一 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c52423cc-8f28-4e64-b673-61a8d66bfe5e', '雜曲歌辭 宮中樂 二', '杂曲歌辞 宮中乐 二', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["翠匣開寒鏡，珠釵挂步搖。","妝成秖畏曉，更漏促春宵。"]', '["翠匣开寒镜，珠釵挂步搖。","妝成秖畏晓，更漏促春宵。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 二 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5347fb05-5700-4f05-8caa-ec40bcbaa3e0', '雜曲歌辭 宮中樂 三', '杂曲歌辞 宮中乐 三', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["江果瑤池實，金盤露井冰。","甘泉將避暑，臺殿曉光凝。"]', '["江果瑤池實，金盤露井冰。","甘泉將避暑，台殿晓光凝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 三 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32dce2a2-9ad9-4af4-b523-9fa5e5d0bbc1', '雜曲歌辭 宮中樂 四', '杂曲歌辞 宮中乐 四', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["月彩浮鸞殿，砧聲隔鳳樓。","笙歌臨水檻，紅燭乍迎秋。"]', '["月彩浮鸾殿，砧声隔鳳楼。","笙歌臨水檻，紅燭乍迎秋。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 四 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7c05ead-1324-449f-a2c2-2736f0e19526', '雜曲歌辭 宮中樂 五', '杂曲歌辞 宮中乐 五', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["奇樹留寒翠，神池結夕波。","黃山一夜雪，渭水雁聲多。"]', '["奇樹留寒翠，神池結夕波。","黄山一夜雪，渭水雁声多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 宮中樂 五 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61e4f760-45f1-4231-9a19-e69c0010edb1', '雜曲歌辭 踏歌詞 一', '杂曲歌辞 踏歌词 一', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["綵女迎金屋，仙姬出畫堂。","鴛鴦裁錦袖，翡翠帖花黃。","歌響舞分行，豔色動流光。"]', '["綵女迎金屋，仙姬出畫堂。","鴛鴦裁錦袖，翡翠帖花黄。","歌响舞分行，豔色动流光。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 一 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('638c7caa-e512-4b6a-8c8e-f3ce5d708454', '雜曲歌辭 踏歌詞 二', '杂曲歌辞 踏歌词 二', '1d8e074f-60a4-43b8-9b9b-63b47e35082b', '唐', '["庭際花微落，樓前漢已橫。","金壺催夜盡，羅袖拂寒輕。","樂笑暢歡情，未半著天明。"]', '["庭際花微落，楼前漢已橫。","金壺催夜尽，羅袖拂寒轻。","乐笑暢歡情，未半著天明。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 二 崔液 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4a5522-a206-4223-98e1-f19ad8b34496', '雜曲歌辭 踏歌詞 一', '杂曲歌辞 踏歌词 一', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["春景嬌春臺，新露泣新梅。","春葉參差吐，新花重疊開。","花影飛鶯去，歌聲度鳥來。","倩看飄颻雪，何如舞袖迴。"]', '["春景嬌春台，新露泣新梅。","春葉參差吐，新花重叠开。","花影飞鶯去，歌声度鸟来。","倩看飄颻雪，何如舞袖迴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 一 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d514b940-ba90-4240-b574-ce212f15803d', '雜曲歌辭 踏歌詞 二', '杂曲歌辞 踏歌词 二', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["逶迤度香閣，顧步出蘭閨。","欲遶鴛鴦殿，先過桃李蹊。","風帶舒還卷，簪花舉復低。","欲問今宵樂，但聽歌聲齊。"]', '["逶迤度香閣，顧步出蘭閨。","欲遶鴛鴦殿，先過桃李蹊。","风带舒還卷，簪花舉复低。","欲问今宵乐，但听歌声齊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 二 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c41f11-ee59-48d4-a426-c3aefd113ae3', '雜曲歌辭 踏歌詞 三', '杂曲歌辞 踏歌词 三', 'faa6b30a-a174-4330-9d64-fae124ad6c88', '唐', '["夜久星沈沒，更深月影斜。","裙輕纔動佩，鬟薄不勝花。","細風吹寶袜，輕露濕紅紗。","相看樂未已，蘭燈照九華。"]', '["夜久星沈沒，更深月影斜。","裙轻纔动佩，鬟薄不勝花。","細风吹寶袜，轻露濕紅紗。","相看乐未已，蘭灯照九华。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 三 謝偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639eeff6-4209-44c7-a7b7-e1fe5f80f0de', '雜曲歌辭 踏歌詞 一', '杂曲歌辞 踏歌词 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["花蕚樓前雨露新，長安城裏太平人。","龍銜火樹千燈豔，雞踏蓮花萬歲春。"]', '["花蕚楼前雨露新，长安城裏太平人。","龙銜火樹千灯豔，雞踏蓮花万歲春。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e998972-8925-45e1-a3bd-e7f8ab5c26a5', '雜曲歌辭 踏歌詞 二', '杂曲歌辞 踏歌词 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝宮三五戲春臺，行雨流風莫妒來。","西域燈輪千影合，東華金闕萬重開。"]', '["帝宮三五戲春台，行雨流风莫妒来。","西域灯輪千影合，东华金闕万重开。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌詞 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577b61e8-7a6a-4622-88b2-d789149910e2', '雜曲歌辭 踏歌行 一', '杂曲歌辞 踏歌行 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["春江月出大堤平，堤上女郎連袂行。","唱盡新詞看不見，紅霞影樹鷓鴣鳴。"]', '["春江月出大堤平，堤上女郎連袂行。","唱尽新词看不见，紅霞影樹鷓鴣鳴。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌行 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805963b8-7066-4be3-8aea-e95562dcab80', '雜曲歌辭 踏歌行 二', '杂曲歌辞 踏歌行 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["桃蹊柳陌好經過，燈下妝成月下歌。","爲是襄王故宮地，至今猶自細腰多。"]', '["桃蹊柳陌好經過，灯下妝成月下歌。","爲是襄王故宮地，至今猶自細腰多。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌行 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffc94cde-e10c-45f8-b663-40a2f40b2014', '雜曲歌辭 踏歌行 三', '杂曲歌辞 踏歌行 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["新詞宛轉遞相傳，振袖傾鬟風露前。","月落烏啼雲雨散，遊童陌上拾花鈿。"]', '["新词宛轉遞相傳，振袖傾鬟风露前。","月落烏啼云雨散，游童陌上拾花鈿。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌行 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dba2d290-6910-4676-813c-02b622d559a1', '雜曲歌辭 踏歌行 四', '杂曲歌辞 踏歌行 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["日暮江頭聞竹枝，南人行樂北人悲。","自從雪裏唱新曲，直至三春花盡時。"]', '["日暮江头闻竹枝，南人行乐北人悲。","自從雪裏唱新曲，直至三春花尽时。"]', '诗', 'shi', '', NULL, '雜曲歌辭 踏歌行 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5286243-fe81-45de-8dd0-2c9b10612a43', '雜曲歌辭 天長地久詞 一', '杂曲歌辞 天长地久词 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["玉砌紅花樹，香風不敢吹。","春光解天意，偏發殿南枝。"]', '["玉砌紅花樹，香风不敢吹。","春光解天意，偏發殿南枝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 天長地久詞 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95eff32-3f6e-4f15-95a1-6b87be854b5d', '雜曲歌辭 天長地久詞 二', '杂曲歌辞 天长地久词 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["虹橋千步廊，半在水中央。","天子方清暑，宮人重暮妝。"]', '["虹橋千步廊，半在水中央。","天子方清暑，宮人重暮妝。"]', '诗', 'shi', '', NULL, '雜曲歌辭 天長地久詞 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a7867a-1613-459e-bc85-9a7a97d24a4e', '雜曲歌辭 天長地久詞 三', '杂曲歌辞 天长地久词 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["辭輦復當熊，傾心奉上宮。","君王若看貌，甘在衆妃中。"]', '["辞輦复當熊，傾心奉上宮。","君王若看貌，甘在衆妃中。"]', '诗', 'shi', '', NULL, '雜曲歌辭 天長地久詞 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41bab4a4-f0f9-461b-b886-e36f04532da9', '雜曲歌辭 天長地久詞 四', '杂曲歌辞 天长地久词 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["雲日呈祥禮物殊，北庭生獻五單于。","塞天萬里無飛鳥，可在邊城用郅都。"]', '["云日呈祥禮物殊，北庭生獻五單于。","塞天万里無飞鸟，可在邊城用郅都。"]', '诗', 'shi', '', NULL, '雜曲歌辭 天長地久詞 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1181c21-874a-4a68-94a2-536a7149656f', '雜曲歌辭 天長地久詞 五', '杂曲歌辞 天长地久词 五', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["臺殿雲涼風日微，君王初賜六宮衣。","樓船罷泛歸猶早，行道才人鬬射飛。"]', '["台殿云涼风日微，君王初賜六宮衣。","楼船罷泛归猶早，行道才人鬬射飞。"]', '诗', 'shi', '', NULL, '雜曲歌辭 天長地久詞 五 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09997a32-f020-4acc-8f09-4fe811150ef6', '雜曲歌辭 欸乃曲 一', '杂曲歌辞 欸乃曲 一', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["偏存名跡在人間，順俗與時未安閑。","來謁大官兼問政，扁舟却入九疑山。"]', '["偏存名跡在人间，順俗與时未安闲。","来謁大官兼问政，扁舟却入九疑山。"]', '诗', 'shi', '', NULL, '雜曲歌辭 欸乃曲 一 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d1f2587-bac2-4b2a-89e5-626edd8188f5', '雜曲歌辭 欸乃曲 二', '杂曲歌辞 欸乃曲 二', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["湘江二月春水平，滿月和風宜夜行。","唱橈欲過平陽戍，守吏相呼問姓名。"]', '["湘江二月春水平，满月和风宜夜行。","唱橈欲過平陽戍，守吏相呼问姓名。"]', '诗', 'shi', '', NULL, '雜曲歌辭 欸乃曲 二 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6e3b4f-dbcd-4132-8942-9ac825f88aa8', '雜曲歌辭 欸乃曲 三', '杂曲歌辞 欸乃曲 三', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["千里楓林煙雨深，無朝無暮有猨吟。","停橈靜聽曲中意，好是雲山韶濩音。"]', '["千里楓林煙雨深，無朝無暮有猨吟。","停橈静听曲中意，好是云山韶濩音。"]', '诗', 'shi', '', NULL, '雜曲歌辭 欸乃曲 三 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c3b7a8-351d-4621-8c12-c0391e566d3a', '雜曲歌辭 欸乃曲 四', '杂曲歌辞 欸乃曲 四', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["零陵郡北湘水東，浯溪形勝滿湘中。","溪口石顛堪自逸，誰能相伴作漁翁。"]', '["零陵郡北湘水东，浯溪形勝满湘中。","溪口石顛堪自逸，誰能相伴作漁翁。"]', '诗', 'shi', '', NULL, '雜曲歌辭 欸乃曲 四 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78891fad-2452-41fa-b710-b7c0433a8a53', '雜曲歌辭 欸乃曲 五', '杂曲歌辞 欸乃曲 五', '2670b0e8-51a0-4229-906b-d172a9ec9314', '唐', '["下瀧船似入深淵，上瀧船似欲昇天。","瀧南始到九疑郡，應絕高人乘興船。"]', '["下瀧船似入深淵，上瀧船似欲昇天。","瀧南始到九疑郡，應絕高人乘兴船。"]', '诗', 'shi', '', NULL, '雜曲歌辭 欸乃曲 五 元結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8def6541-16ab-4f82-a669-17b2bb5195c7', '雜曲歌辭 十二月樂辭 正月', '杂曲歌辞 十二月乐辞 正月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["上樓迎春新春歸，暗黃著柳宮漏遲。","薄薄淡靄弄野姿，寒綠幽泥生短絲。","錦牀曉臥玉肌冷，露臉未開對朝暝。","官街柳帶不堪折，早晚菖蒲勝綰結。"]', '["上楼迎春新春归，暗黄著柳宮漏遲。","薄薄淡靄弄野姿，寒綠幽泥生短絲。","錦牀晓臥玉肌冷，露臉未开对朝暝。","官街柳带不堪折，早晚菖蒲勝綰結。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 正月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1164451a-78ce-4ced-b45a-a0cab3dacd1e', '雜曲歌辭 十二月樂辭 二月', '杂曲歌辞 十二月乐辞 二月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["二月飲酒采桑津，宜男草生蘭笑人。","蒲如交劒風如薰，勞勞胡燕怨酣春。","薇帳逗烟生綠塵，金翅峨髻愁暮雲。","沓颯起舞真珠裙，津頭送別唱流水。","酒客背寒南山死。"]', '["二月饮酒采桑津，宜男草生蘭笑人。","蒲如交劒风如薰，勞勞胡燕怨酣春。","薇帳逗烟生綠塵，金翅峨髻愁暮云。","沓颯起舞真珠裙，津头送別唱流水。","酒客背寒南山死。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 二月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6edb4622-4f09-4d1c-bc71-a7f284956462', '雜曲歌辭 十二月樂辭 三月', '杂曲歌辞 十二月乐辞 三月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["東方風來滿眼春，花城柳暗愁幾人，複宮深殿竹風起。","新翠舞襟靜如水，光風轉蕙百餘里。","暖霧驅雲撲天地，軍裝宮妓掃蛾淺。","搖搖錦旗夾城暖，曲水飄香去不歸。","梨花落盡成秋苑。"]', '["东方风来满眼春，花城柳暗愁幾人，複宮深殿竹风起。","新翠舞襟静如水，光风轉蕙百餘里。","暖霧驱云撲天地，軍裝宮妓掃蛾淺。","搖搖錦旗夾城暖，曲水飄香去不归。","梨花落尽成秋苑。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 三月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d92df58-5c25-4916-a6c7-15c92e0a5240', '雜曲歌辭 十二月樂辭 四月', '杂曲歌辞 十二月乐辞 四月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["曉涼暮涼樹如蓋，千山濃綠生雲外。","依微香雨青氛氳，膩葉蟠花照曲門。","金塘閑水搖碧漪，老景沈重無驚飛，墮紅殘蕚暗參差。"]', '["晓涼暮涼樹如蓋，千山濃綠生云外。","依微香雨青氛氳，膩葉蟠花照曲门。","金塘闲水搖碧漪，老景沈重無驚飞，墮紅殘蕚暗參差。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 四月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8acb4e2-2db4-47e8-97e4-6f8f3239654d', '雜曲歌辭 十二月樂辭 五月', '杂曲歌辞 十二月乐辞 五月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雕玉押簾上，輕縠籠虛門。","井汲鉛華水，扇織鴛鴦文。","回雪舞涼殿，甘露洗空綠。","羅袖從徊翔，香汗霑寶粟。"]', '["雕玉押簾上，轻縠籠虛门。","井汲鉛华水，扇织鴛鴦文。","回雪舞涼殿，甘露洗空綠。","羅袖從徊翔，香汗霑寶粟。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 五月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3063abd2-4d18-4f71-aebe-3f433607900a', '雜曲歌辭 十二月樂辭 六月', '杂曲歌辞 十二月乐辞 六月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["裁生羅，伐湘竹。","帔拂疎霜簟秋玉，炎炎紅鏡東方開。","暈如車輪上徘徊，啾啾赤帝騎龍來。"]', '["裁生羅，伐湘竹。","帔拂疎霜簟秋玉，炎炎紅镜东方开。","暈如车輪上徘徊，啾啾赤帝騎龙来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 六月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1168acab-dc79-42cd-82a8-439ee1fc51ae', '雜曲歌辭 十二月樂辭 七月', '杂曲歌辞 十二月乐辞 七月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["星依雲渚冷，露滴盤中圓。","好花生木末，衰蕙愁空園。","夜天如玉砌，池葉極青錢。","僅厭舞衫薄，稍知花簟寒。","曉風何拂拂，北斗光闌干。"]', '["星依云渚冷，露滴盤中圓。","好花生木末，衰蕙愁空园。","夜天如玉砌，池葉極青錢。","僅厭舞衫薄，稍知花簟寒。","晓风何拂拂，北斗光闌干。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 七月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('387c1c09-f29d-47b3-8a4b-34b6956497e0', '雜曲歌辭 十二月樂辭 八月', '杂曲歌辞 十二月乐辞 八月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["孀妾怨長夜，獨客夢歸家。","傍簷蟲緝絲，向壁燈垂花。","簷外月光吐，簾中樹影斜。","悠悠飛露姿，點綴池中荷。"]', '["孀妾怨长夜，独客梦归家。","傍簷蟲緝絲，向壁灯垂花。","簷外月光吐，簾中樹影斜。","悠悠飞露姿，点綴池中荷。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 八月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72c72576-060e-4185-88c2-f4b31c9dcc89', '雜曲歌辭 十二月樂辭 九月', '杂曲歌辞 十二月乐辞 九月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["離宮散螢天似水，竹黃池冷芙蓉死。","月綴金鋪光脉脉，涼苑虛庭空澹白。","霜花飛飛風草草，翠錦斕斑滿層道。","雞人罷唱曉瓏璁，鴉啼金井下疎桐。"]', '["離宮散螢天似水，竹黄池冷芙蓉死。","月綴金鋪光脉脉，涼苑虛庭空澹白。","霜花飞飞风草草，翠錦斕斑满層道。","雞人罷唱晓瓏璁，鴉啼金井下疎桐。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 九月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3250a75a-201d-4c4c-a3ac-4b0bb4a246f8', '雜曲歌辭 十二月樂辭 十月', '杂曲歌辞 十二月乐辞 十月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["玉壺銀箭稍難傾，釭花夜笑凝幽明。","碎霜斜舞上羅幕，燭籠兩行照飛閣。","珠帷怨臥不成眠，金鳳刺衣著體寒，長眉對月鬬彎環。"]', '["玉壺銀箭稍难傾，釭花夜笑凝幽明。","碎霜斜舞上羅幕，燭籠兩行照飞閣。","珠帷怨臥不成眠，金鳳刺衣著體寒，长眉对月鬬彎环。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 十月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb2ce8a-906f-4f7f-8025-8f5cf56a692d', '雜曲歌辭 十二月樂辭 十一月', '杂曲歌辞 十二月乐辞 十一月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["宮城團回凜嚴光，白光碎碎墮瓊芳。","撾鍾高飲千日酒，却天凝寒作君壽。"]', '["宮城團回凜嚴光，白光碎碎墮瓊芳。","撾鍾高饮千日酒，却天凝寒作君壽。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 十一月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d6a9883-9575-42d7-ba2e-43cd44086f87', '雜曲歌辭 十二月樂辭 十二月', '杂曲歌辞 十二月乐辞 十二月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["日脚淡光紅灑灑，薄霜不銷桂枝下。","依稀和氣解冬嚴，已就長日辭長夜。"]', '["日脚淡光紅灑灑，薄霜不銷桂枝下。","依稀和氣解冬嚴，已就长日辞长夜。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 十二月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b1201d-f671-428d-867e-0eecc02e47ca', '雜曲歌辭 十二月樂辭 閏月', '杂曲歌辞 十二月乐辞 閏月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["帝重光，年重時，七十二候回環推。","天官玉琯灰剩飛，今歲何長來歲遲。","王母移桃獻天子，羲氏和氏迂龍轡。"]', '["帝重光，年重时，七十二候回环推。","天官玉琯灰剩飞，今歲何长来歲遲。","王母移桃獻天子，羲氏和氏迂龙轡。"]', '诗', 'shi', '', NULL, '雜曲歌辭 十二月樂辭 閏月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a02551b7-28e1-4a79-8e2c-a185c70cffcb', '雜曲歌辭 桃花行 一', '杂曲歌辞 桃花行 一', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["歲去無言忽顦顇，時來含笑吐氛氳。","不能擁路迷仙客，故欲開蹊侍聖君。"]', '["歲去無言忽顦顇，时来含笑吐氛氳。","不能擁路迷仙客，故欲开蹊侍聖君。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桃花行 一 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6685502b-4f24-4ab8-82db-c0b0b155c13e', '雜曲歌辭 桃花行 二', '杂曲歌辞 桃花行 二', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["綺蕚成蹊遍籞芳，紅英撲地滿筵香。","莫將秋宴傳王母，來比春華壽聖皇。"]', '["綺蕚成蹊遍籞芳，紅英撲地满筵香。","莫將秋宴傳王母，来比春华壽聖皇。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桃花行 二 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('065b8cb6-8cbd-461e-8ed8-62ee4ba449e8', '雜曲歌辭 桃花行 三', '杂曲歌辞 桃花行 三', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["源水叢花無數開，丹跗紅蕚間青梅。","從今結子三千歲，預喜仙游復摘來。"]', '["源水叢花無數开，丹跗紅蕚间青梅。","從今結子三千歲，預喜仙游复摘来。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桃花行 三 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39588d10-121c-4f20-aace-8cd5392070a7', '雜曲歌辭 桃花行 四', '杂曲歌辞 桃花行 四', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["桃花灼灼有光輝，無數成蹊點更飛。","爲見芳林含笑待，遂同溫樹不言歸。"]', '["桃花灼灼有光輝，無數成蹊点更飞。","爲见芳林含笑待，遂同溫樹不言归。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桃花行 四 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17097de0-b154-43fd-9213-91d38353eb8c', '雜曲歌辭 桃花行 五', '杂曲歌辞 桃花行 五', '5222ef24-2258-46f7-b33f-5fefb57b56a6', '唐', '["紅蕚競妍春苑曙，粉茸新向御筵開。","長年願奉西王宴，近侍慙無東朔才。"]', '["紅蕚競妍春苑曙，粉茸新向御筵开。","长年願奉西王宴，近侍慙無东朔才。"]', '诗', 'shi', '', NULL, '雜曲歌辭 桃花行 五 李嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03af6588-16af-493e-8988-e64b86562558', '雜曲歌辭 蘇摩遮 一', '杂曲歌辞 蘇摩遮 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["摩遮本出海西胡，琉璃寶服紫髯胡。","聞道皇恩遍宇宙，來時歌舞助歡娛。"]', '["摩遮本出海西胡，琉璃寶服紫髯胡。","闻道皇恩遍宇宙，来时歌舞助歡娛。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蘇摩遮 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31890cda-050b-4716-a248-2489f7552a6f', '雜曲歌辭 蘇摩遮 二', '杂曲歌辞 蘇摩遮 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["繡裝帕額寶花冠，夷歌騎舞借人看。","自能激水成陰氣，不慮今年寒不寒。"]', '["繡裝帕額寶花冠，夷歌騎舞借人看。","自能激水成陰氣，不慮今年寒不寒。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蘇摩遮 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf878bf1-cd9c-4c41-b35d-02c122cbb1d3', '雜曲歌辭 蘇摩遮 三', '杂曲歌辞 蘇摩遮 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["臘月凝陰積帝臺，豪歌擊鼓送寒來。","油囊取得天河水，將添上壽萬年杯。"]', '["臘月凝陰積帝台，豪歌擊鼓送寒来。","油囊取得天河水，將添上壽万年杯。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蘇摩遮 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9983abd-6e12-4219-aa38-ee9b3226f257', '雜曲歌辭 蘇摩遮 四', '杂曲歌辞 蘇摩遮 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["寒氣宜人最可憐，故將寒水散庭前。","惟願聖君無限壽，長取新年續舊年。"]', '["寒氣宜人最可怜，故將寒水散庭前。","惟願聖君無限壽，长取新年續旧年。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蘇摩遮 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef4403b-b3ba-438f-bd74-2d502ebafb9a', '雜曲歌辭 蘇摩遮 五', '杂曲歌辞 蘇摩遮 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["昭成皇后帝家親，榮樂諸人不比倫。","往日霜前花委地，今年雪後樹逢春。"]', '["昭成皇后帝家親，榮乐諸人不比倫。","往日霜前花委地，今年雪後樹逢春。"]', '诗', 'shi', '', NULL, '雜曲歌辭 蘇摩遮 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cf94db2-1392-40b4-9e1d-773601af0411', '雜曲歌辭 舞馬詞 一', '杂曲歌辞 舞马词 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["萬玉朝宗鳳扆，千金率領龍媒。","眄鼓凝驕躞蹀，聽歌弄影徘徊。"]', '["万玉朝宗鳳扆，千金率領龙媒。","眄鼓凝驕躞蹀，听歌弄影徘徊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬詞 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96e24608-9aef-4bbf-ae5a-5a27e6883a14', '雜曲歌辭 舞馬詞 二', '杂曲歌辞 舞马词 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天祿遙徵衛叔，日龍上借羲和。","將共兩驂爭舞，來隨八駿齊歌。"]', '["天祿遙徵衛叔，日龙上借羲和。","將共兩驂爭舞，来隨八駿齊歌。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬詞 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e29b8b64-cab1-44e4-a8ec-665bc16f9915', '雜曲歌辭 舞馬詞 三', '杂曲歌辞 舞马词 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["綵旄八佾成行，時龍五色因方。","屈膝銜杯赴節，傾心獻壽無疆。"]', '["綵旄八佾成行，时龙五色因方。","屈膝銜杯赴節，傾心獻壽無疆。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬詞 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4f456b-e653-4474-8eb6-d72ba31bf034', '雜曲歌辭 舞馬詞 四', '杂曲歌辞 舞马词 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["帝皁龍駒沛艾，星蘭驥子權奇。","騰倚驤洋應節，繁驕接迹不移。"]', '["帝皁龙駒沛艾，星蘭驥子權奇。","腾倚驤洋應節，繁驕接迹不移。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬詞 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf5279f1-ea02-48a0-a04d-6ebaf54c4c45', '雜曲歌辭 舞馬詞 五', '杂曲歌辞 舞马词 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["二聖先天合德，羣靈率土可封。","擊石驂驔紫燕，摐金顧步蒼龍。"]', '["二聖先天合德，羣靈率土可封。","擊石驂驔紫燕，摐金顧步蒼龙。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬詞 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9600d61f-6d07-4fa1-809f-113485971356', '雜曲歌辭 舞馬詞 六', '杂曲歌辞 舞马词 六', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖君出震應籙，神馬浮河獻圖。","足踏天庭鼓舞，心將帝樂蜘躊。"]', '["聖君出震應籙，神马浮河獻圖。","足踏天庭鼓舞，心將帝乐蜘躊。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬詞 六 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d06cba-a215-48cd-861a-1d0c2edba893', '雜曲歌辭 舞馬千秋萬歲樂府詞 一', '杂曲歌辞 舞马千秋万歲乐府词 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["金天誕聖千秋節，玉醴還分萬壽觴。","試聽紫騮歌樂府，何如騄驥舞華岡。","連騫勢出魚龍變，蹀躞驕生鳥獸行。","歲歲相傳指樹日，翩翩來伴慶雲翔。"]', '["金天誕聖千秋節，玉醴還分万壽觴。","試听紫騮歌乐府，何如騄驥舞华岡。","連騫勢出鱼龙变，蹀躞驕生鸟獸行。","歲歲相傳指樹日，翩翩来伴慶云翔。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬千秋萬歲樂府詞 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfcec9f-998b-4132-af84-34467c59f754', '雜曲歌辭 舞馬千秋萬歲樂府詞 二', '杂曲歌辞 舞马千秋万歲乐府词 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["聖王至德與天齊，天馬來儀自海西。","腕足齊行拜兩膝，繁驕不進蹈千蹄。","䯱髵奮鬣時蹲踏，鼓怒驤身忽上躋。","更有銜杯終宴曲，垂頭掉尾醉如泥。"]', '["聖王至德與天齊，天马来儀自海西。","腕足齊行拜兩膝，繁驕不進蹈千蹄。","䯱髵奮鬣时蹲踏，鼓怒驤身忽上躋。","更有銜杯終宴曲，垂头掉尾醉如泥。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬千秋萬歲樂府詞 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c82f04b-e75b-4136-8905-f66fd3d33361', '雜曲歌辭 舞馬千秋萬歲樂府詞 三', '杂曲歌辞 舞马千秋万歲乐府词 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["遠聽明君愛逸才，玉鞭金翅引龍媒。","不因茲白人間有，定是飛黃天上來。","影弄日華相照耀，噴含雲色且徘徊。","莫言闕下桃花舞，別有河中蘭葉開。"]', '["远听明君愛逸才，玉鞭金翅引龙媒。","不因茲白人间有，定是飞黄天上来。","影弄日华相照耀，噴含云色且徘徊。","莫言闕下桃花舞，別有河中蘭葉开。"]', '诗', 'shi', '', NULL, '雜曲歌辭 舞馬千秋萬歲樂府詞 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b0ad0f-0619-4b48-9f77-63be8c086cc5', '雜曲歌辭 小曲新詞 一', '杂曲歌辞 小曲新词 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霽色鮮宮殿，秋聲脆管弦。","聖明千歲樂，歲歲似今年。"]', '["霽色鲜宮殿，秋声脆管弦。","聖明千歲乐，歲歲似今年。"]', '诗', 'shi', '', NULL, '雜曲歌辭 小曲新詞 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6040755-04d0-4eed-a189-573ee13f56e6', '雜曲歌辭 小曲新詞 二', '杂曲歌辞 小曲新词 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅裙明月夜，碧殿早秋時。","好向昭陽宿，天涼玉漏遲。"]', '["紅裙明月夜，碧殿早秋时。","好向昭陽宿，天涼玉漏遲。"]', '诗', 'shi', '', NULL, '雜曲歌辭 小曲新詞 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a01bda7-e94e-4968-b635-0697fabe823f', '雜曲歌辭 閨怨詞 一', '杂曲歌辞 閨怨词 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝憎鶯百囀，夜妒燕雙棲。","不慣經春別，誰知到曉啼。"]', '["朝憎鶯百囀，夜妒燕雙棲。","不慣經春別，誰知到晓啼。"]', '诗', 'shi', '', NULL, '雜曲歌辭 閨怨詞 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a1c0b7b-5f64-4136-ba4c-3f9b2ffdc98b', '雜曲歌辭 閨怨詞 二', '杂曲歌辞 閨怨词 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["珠箔籠寒月，紗窗背曉燈。","夜來巾上淚，一半是春冰。"]', '["珠箔籠寒月，紗窗背晓灯。","夜来巾上泪，一半是春冰。"]', '诗', 'shi', '', NULL, '雜曲歌辭 閨怨詞 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d872e96e-c064-4fa4-a3f3-8f74a61116e7', '雜曲歌辭 閨怨詞 三', '杂曲歌辞 閨怨词 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["關山征戍遠，閨閣別離難。","苦戰應顦顇，寒衣不要寬。"]', '["关山征戍远，閨閣別離难。","苦戰應顦顇，寒衣不要寬。"]', '诗', 'shi', '', NULL, '雜曲歌辭 閨怨詞 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('624d5fb5-98fb-41af-9dbd-be9367d82630', '雜曲歌辭 皇帝感詞 一', '杂曲歌辞 皇帝感词 一', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["提劒雲雷動，垂衣日月明。","禁花呈瑞色，國老見星精。","發棹魚先躍，窺巢鳥不驚。","山呼一萬歲，直入九重城。"]', '["提劒云雷动，垂衣日月明。","禁花呈瑞色，国老见星精。","發棹鱼先躍，窺巢鸟不驚。","山呼一万歲，直入九重城。"]', '诗', 'shi', '', NULL, '雜曲歌辭 皇帝感詞 一 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a58f543-bac5-42c3-834b-fd6781a18a18', '雜曲歌辭 皇帝感詞 二', '杂曲歌辞 皇帝感词 二', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["天衣五鳳彩，御馬六龍文。","雨露清馳道，風雷翊上軍。","高旍花外轉，行漏樂前聞。","時見金鞭舉，空中指瑞雲。"]', '["天衣五鳳彩，御马六龙文。","雨露清驰道，风雷翊上軍。","高旍花外轉，行漏乐前闻。","时见金鞭舉，空中指瑞云。"]', '诗', 'shi', '', NULL, '雜曲歌辭 皇帝感詞 二 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b05eada0-57c8-43aa-a739-94ebfbfaf250', '雜曲歌辭 皇帝感詞 三', '杂曲歌辞 皇帝感词 三', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["妙算干戈止，神謀宇宙清。","兩階文物盛，七德武功成。","校獵長楊苑，屯軍細柳營。","歸來獻明主，歌舞隘春城。"]', '["妙算干戈止，神謀宇宙清。","兩階文物盛，七德武功成。","校獵长楊苑，屯軍細柳營。","归来獻明主，歌舞隘春城。"]', '诗', 'shi', '', NULL, '雜曲歌辭 皇帝感詞 三 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7df3122-f82a-4ff5-a7c0-ab8b766f448b', '雜曲歌辭 皇帝感詞 四', '杂曲歌辞 皇帝感词 四', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["天樂下天中，雲軿儼在空。","鉛黃豔河漢，語笑合笙鏞。","已見長隨鳳，仍聞不避熊。","君王親試舞，閶闔靜無風。"]', '["天乐下天中，云軿儼在空。","鉛黄豔河漢，語笑合笙鏞。","已见长隨鳳，仍闻不避熊。","君王親試舞，閶闔静無风。"]', '诗', 'shi', '', NULL, '雜曲歌辭 皇帝感詞 四 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5c45b3-3e85-4eeb-b9de-eba380e530b6', '雜歌謠辭 漁父歌 一', '杂歌謠辞 漁父歌 一', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["西塞山邊白鷺飛，桃花流水鱖魚肥。","青箬笠，綠蓑衣，春江細雨不須歸。"]', '["西塞山邊白鷺飞，桃花流水鱖鱼肥。","青箬笠，綠蓑衣，春江細雨不須归。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 一 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7393bcdc-a605-4f44-ab7f-506000d4a052', '雜歌謠辭 漁父歌 二', '杂歌謠辞 漁父歌 二', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["釣臺漁父褐爲裘，兩兩三三舴艋舟。","能縱棹，慣乘流，長江白浪不曾憂。"]', '["釣台漁父褐爲裘，兩兩三三舴艋舟。","能縱棹，慣乘流，长江白浪不曾憂。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 二 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9286dac-14c5-4239-8c1b-bd90bc91baa2', '雜歌謠辭 漁父歌 三', '杂歌謠辞 漁父歌 三', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["霅溪灣裏釣漁翁，舴艋爲家西復東。","江上雪，浦邊風，笑著荷衣不歎窮。"]', '["霅溪灣裏釣漁翁，舴艋爲家西复东。","江上雪，浦邊风，笑著荷衣不歎窮。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 三 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d40b60b9-c4c1-4dc2-8d4a-b4d5122bf03a', '雜歌謠辭 漁父歌 四', '杂歌謠辞 漁父歌 四', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["松江蟹舍主人歡，菰飯莼羹亦共餐。","楓葉落，荻花乾，醉宿漁舟不覺寒。"]', '["松江蟹舍主人歡，菰飯莼羹亦共餐。","楓葉落，荻花乾，醉宿漁舟不覺寒。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 四 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e4ea5d5-bb63-41ce-81c1-44716ae9dcbf', '雜歌謠辭 漁父歌 五', '杂歌謠辞 漁父歌 五', '3fc597cf-a582-4e78-8c74-ab0b74b7f33c', '唐', '["青草湖中月正圓，巴陵漁父棹歌連。","釣車子，掘頭船，樂在風波不用仙。"]', '["青草湖中月正圓，巴陵漁父棹歌連。","釣车子，掘头船，乐在风波不用仙。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 五 張志和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3e1062-ee73-4c2e-9fcf-9554fae22e1e', '雜歌謠辭 漁父歌', '杂歌謠辞 漁父歌', '1cb41a4f-98ae-42ca-9063-01c4fff674e2', '唐', '["白芷汀寒立鷺[鷥]，蘋風輕翦浪花時。","煙冪冪，日遲遲，香引芙蓉惹釣絲。"]', '["白芷汀寒立鷺[鷥]，蘋风轻翦浪花时。","煙冪冪，日遲遲，香引芙蓉惹釣絲。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 和凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8bbfe74-0389-473a-a93d-abe9690a4761', '雜歌謠辭 漁父歌', '杂歌謠辞 漁父歌', '6d9da17b-618b-43ab-84f8-da5e0f4c9c89', '唐', '["風浩寒溪照膽明，小君山上玉蟾生。","荷露墜，翠煙輕，撥[拉]遊魚幾處驚。"]', '["风浩寒溪照膽明，小君山上玉蟾生。","荷露墜，翠煙轻，撥[拉]游鱼幾处驚。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 歐陽炯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a70b6e-d6a8-4155-a043-64664ff6a496', '雜歌謠辭 漁父歌 一', '杂歌謠辞 漁父歌 一', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["水接衡門十里餘，信船歸去臥看書。","輕爵祿，慕玄虛，莫道漁人只爲魚。"]', '["水接衡门十里餘，信船归去臥看书。","轻爵祿，慕玄虛，莫道漁人只爲鱼。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 一 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b365df-54d9-4b2a-b63a-327ecc746a89', '雜歌謠辭 漁父歌 二', '杂歌謠辞 漁父歌 二', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["避世垂綸不記年，官高爭得似君閑。","傾白酒，對青山，笑指柴門待月還。"]', '["避世垂綸不記年，官高爭得似君闲。","傾白酒，对青山，笑指柴门待月還。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 二 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaca9abf-2fae-4634-8f47-89acf32a72a1', '雜歌謠辭 漁父歌 三', '杂歌謠辞 漁父歌 三', '1f39d954-dff7-4eb1-a509-2579c3ae57ea', '唐', '["棹警鷗飛水濺袍，影侵潭面柳垂絛。","終日醉，絕塵勞，曾見錢塘八月濤。"]', '["棹警鷗飞水濺袍，影侵潭面柳垂絛。","終日醉，絕塵勞，曾见錢塘八月濤。"]', '诗', 'shi', '', NULL, '雜歌謠辭 漁父歌 三 李珣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83d2e1b3-c1cb-4ac4-be0b-c98532af2ba6', '雜歌謠辭 雞鳴曲', '杂歌謠辞 雞鳴曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["雞初鳴，明星照東屋。","雞再鳴，紅霞生海腹。","百官待漏雙闕前，聖人亦挂山龍服。","寶釵命婦燈下起，環珮玲瓏曉光裏。","直內初燒玉[案]香，司更尚滴銅壺水。","金吾衛裏直郎妻，到明不睡聽晨雞。","天頭日月相送迎，夜棲旦鳴人不迷。"]', '["雞初鳴，明星照东屋。","雞再鳴，紅霞生海腹。","百官待漏雙闕前，聖人亦挂山龙服。","寶釵命婦灯下起，环珮玲瓏晓光裏。","直內初燒玉[案]香，司更尚滴銅壺水。","金吾衛裏直郎妻，到明不睡听晨雞。","天头日月相送迎，夜棲旦鳴人不迷。"]', '诗', 'shi', '', NULL, '雜歌謠辭 雞鳴曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e0e651d-6a4a-4d76-8798-10de3225cd48', '雜歌謠辭 雞鳴曲', '杂歌謠辞 雞鳴曲', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["星稀月沒上五更，膠膠角角雞初鳴。","征人牽馬出門立，辭妾欲向安西行。","再鳴引頸簷頭下，月中角聲催上馬。","纔分地色第三鳴，旌旗紅塵已出城。","婦人上城亂招手，夫壻不聞遙哭聲。","長恨雞鳴別時苦，不遣雞栖近窗戶。"]', '["星稀月沒上五更，膠膠角角雞初鳴。","征人牽马出门立，辞妾欲向安西行。","再鳴引頸簷头下，月中角声催上马。","纔分地色第三鳴，旌旗紅塵已出城。","婦人上城亂招手，夫壻不闻遙哭声。","长恨雞鳴別时苦，不遣雞栖近窗戶。"]', '诗', 'shi', '', NULL, '雜歌謠辭 雞鳴曲 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d040c0-e9c8-4ab6-9e3e-59613427b5de', '雜歌謠辭 吳楚歌', '杂歌謠辞 吳楚歌', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["庭前春鳥啄林聲，紅夾羅襦縫未成。","今朝社日停針線，起向朱櫻樹下行。"]', '["庭前春鸟啄林声，紅夾羅襦縫未成。","今朝社日停針線，起向朱櫻樹下行。"]', '诗', 'shi', '', NULL, '雜歌謠辭 吳楚歌 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d855a9-3d50-4905-887c-e05e440a7182', '雜歌謠辭 李夫人歌 一', '杂歌謠辞 李夫人歌 一', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["一帶不結心，兩股方安髻。","慙愧白茅人，月沒教星替。"]', '["一带不結心，兩股方安髻。","慙愧白茅人，月沒教星替。"]', '诗', 'shi', '', NULL, '雜歌謠辭 李夫人歌 一 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f163557-30e2-4035-a535-f33d12b6dc19', '雜歌謠辭 李夫人歌 二', '杂歌謠辞 李夫人歌 二', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["剩結茱萸枝，多擘秋蓮的。","獨自有波光，綵囊盛不得。"]', '["剩結茱萸枝，多擘秋蓮的。","独自有波光，綵囊盛不得。"]', '诗', 'shi', '', NULL, '雜歌謠辭 李夫人歌 二 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33255d95-3c66-4307-9cc9-6918b69b3fb0', '雜歌謠辭 李夫人歌 三', '杂歌謠辞 李夫人歌 三', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["蠻絲繫條脫，妍眼和香屑。","壽宮不惜鑄南人，柔腸早被秋波割。","清澄有餘幽素香，鰥魚渴鳳真珠房。","不知瘦骨類冰井，更許夜簾通曉霜。","土花漠碧雲[茫茫]，黃河欲盡天蒼黃。"]', '["蠻絲繫條脫，妍眼和香屑。","壽宮不惜鑄南人，柔腸早被秋波割。","清澄有餘幽素香，鰥鱼渴鳳真珠房。","不知瘦骨類冰井，更許夜簾通晓霜。","土花漠碧云[茫茫]，黄河欲尽天蒼黄。"]', '诗', 'shi', '', NULL, '雜歌謠辭 李夫人歌 三 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d28ae53e-8dac-47ac-a610-5a935826e2a9', '雜歌謠辭 李夫人歌', '杂歌謠辞 李夫人歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["紫皇宮殿重重開，夫人飛入瓊瑤臺。","綠香繡帳何時歇，青雲無光宮水咽。","翩聯桂花墜秋月，孤鸞驚啼商絲發。","紅璧闌珊懸佩璫，歌臺小妓遙相望。","玉蟾滴水雞人唱，露華蘭葉參差光。"]', '["紫皇宮殿重重开，夫人飞入瓊瑤台。","綠香繡帳何时歇，青云無光宮水咽。","翩聯桂花墜秋月，孤鸾驚啼商絲發。","紅璧闌珊懸佩璫，歌台小妓遙相望。","玉蟾滴水雞人唱，露华蘭葉參差光。"]', '诗', 'shi', '', NULL, '雜歌謠辭 李夫人歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490298b8-51c5-4438-8adf-109d4f642abc', '雜歌謠辭 李夫人歌', '杂歌謠辞 李夫人歌', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["璿閨羽帳華燭陳，方士夜降夫人神。","葳蕤半露芙蓉色，窈窕將期環珮身。","麗如三五月，可望難親近。","嚬黛含犀竟不言，春思秋怨誰能問。","欲求巧笑如生時，歌塵在空瑟銜絲。","神來未及夢相見，帝比初亡心更悲。","愛之欲其生又死，東流萬代無回水。","宮漏丁丁夜向晨，煙銷霧散愁方士。"]', '["璿閨羽帳华燭陳，方士夜降夫人神。","葳蕤半露芙蓉色，窈窕將期环珮身。","丽如三五月，可望难親近。","嚬黛含犀竟不言，春思秋怨誰能问。","欲求巧笑如生时，歌塵在空瑟銜絲。","神来未及梦相见，帝比初亡心更悲。","愛之欲其生又死，东流万代無回水。","宮漏丁丁夜向晨，煙銷霧散愁方士。"]', '诗', 'shi', '', NULL, '雜歌謠辭 李夫人歌 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8046faf5-f9d6-47fe-89b1-b2b105400aee', '雜歌謠辭 李夫人歌', '杂歌謠辞 李夫人歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["延年不語望三星，莫說夫人上涕零。","爭奈世間惆悵在，甘泉宮夜看圖形。"]', '["延年不語望三星，莫说夫人上涕零。","爭奈世间惆悵在，甘泉宮夜看圖形。"]', '诗', 'shi', '', NULL, '雜歌謠辭 李夫人歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c415df9-f9f3-468d-ae2b-79994ff4a5cf', '雜歌謠辭 中山孺子妾歌', '杂歌謠辞 中山孺子妾歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["中山孺子妾，特以色見珍。","雖不如延年妹，亦是當時絕世人。","桃李出深井，花豔驚上春。","一貴復一賤，關天豈由身。","芙蓉老秋霜，團扇羞網塵。","戚姬髡翦入舂市，萬古共悲辛。"]', '["中山孺子妾，特以色见珍。","雖不如延年妹，亦是當时絕世人。","桃李出深井，花豔驚上春。","一貴复一賤，关天豈由身。","芙蓉老秋霜，團扇羞網塵。","戚姬髡翦入舂市，万古共悲辛。"]', '诗', 'shi', '', NULL, '雜歌謠辭 中山孺子妾歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e88a20da-6a82-4840-8389-afa8722810ec', '雜歌謠辭 臨江王節士歌', '杂歌謠辞 臨江王節士歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["洞庭白波木葉稀，燕鴻始入吳雲飛。","吳雲寒，燕鴻苦。","風號沙宿瀟湘浦，節士感秋淚如雨。","白日當天心，照之可以事明主。","壯士憤，雄風生。","安得倚天劒，跨海斬長鯨。"]', '["洞庭白波木葉稀，燕鴻始入吳云飞。","吳云寒，燕鴻苦。","风號沙宿瀟湘浦，節士感秋泪如雨。","白日當天心，照之可以事明主。","壯士憤，雄风生。","安得倚天劒，跨海斬长鯨。"]', '诗', 'shi', '', NULL, '雜歌謠辭 臨江王節士歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c25daef9-1903-4899-a965-231f12448f2b', '雜歌謠辭 司馬將軍歌', '杂歌謠辞 司马將軍歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["狂風吹古月，竊弄章華臺。","北落明星動光彩，南征猛將如雲雷。","手中電曳倚天劒，直斬長鯨海水開。","我見樓船壯心目，頗似龍驤下三蜀。","揚兵習戰張虎旗，江中白浪如銀屋。","身居玉帳臨河魁，紫髯若戟冠崔嵬。","細柳開營揖天子，始知灞上爲嬰孩。","羌笛橫吹阿嚲回，向月樓中吹落梅。","將軍自起舞長劒，壯士呼聲動九垓。","功成獻凱見明主，丹青畫像麒麟臺。"]', '["狂风吹古月，竊弄章华台。","北落明星动光彩，南征猛將如云雷。","手中電曳倚天劒，直斬长鯨海水开。","我见楼船壯心目，頗似龙驤下三蜀。","揚兵習戰張虎旗，江中白浪如銀屋。","身居玉帳臨河魁，紫髯若戟冠崔嵬。","細柳开營揖天子，始知灞上爲嬰孩。","羌笛橫吹阿嚲回，向月楼中吹落梅。","將軍自起舞长劒，壯士呼声动九垓。","功成獻凱见明主，丹青畫像麒麟台。"]', '诗', 'shi', '', NULL, '雜歌謠辭 司馬將軍歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('396cd474-fdac-49f4-9594-f28d013760ac', '雜歌謠辭 鄭櫻桃歌', '杂歌謠辞 鄭櫻桃歌', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["石季龍，僭天祿。","擅雄豪，美人姓鄭名櫻桃。","櫻桃美顏香且澤，娥娥侍寢專宮掖。","後庭卷衣三萬人，翠眉清鏡不得親。","官軍女騎一千匹，繁花照耀漳河春。","織成花映紅綸巾，紅旗掣曳鹵簿新。","鳴鼙走馬接飛鳥，銅[馱]琴瑟隨去塵。","鳳陽重門如意館，百尺金梯倚銀漢。","自言富貴不可量，女爲公主男爲王。","赤花雙簟珊瑚牀，盤龍斗帳琥珀光。","淫昏僞位神所惡，滅石者陵終不誤。","鄴城蒼蒼白露微，世事飜覆黃雲飛。"]', '["石季龙，僭天祿。","擅雄豪，美人姓鄭名櫻桃。","櫻桃美顏香且澤，娥娥侍寢專宮掖。","後庭卷衣三万人，翠眉清镜不得親。","官軍女騎一千匹，繁花照耀漳河春。","织成花映紅綸巾，紅旗掣曳鹵簿新。","鳴鼙走马接飞鸟，銅[馱]琴瑟隨去塵。","鳳陽重门如意館，百尺金梯倚銀漢。","自言富貴不可量，女爲公主男爲王。","赤花雙簟珊瑚牀，盤龙斗帳琥珀光。","淫昏僞位神所惡，滅石者陵終不誤。","鄴城蒼蒼白露微，世事飜覆黄云飞。"]', '诗', 'shi', '', NULL, '雜歌謠辭 鄭櫻桃歌 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aeb685d-f7d1-446f-942f-3ad5167cda9b', '雜歌謠辭 襄陽歌', '杂歌謠辞 襄陽歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["落日欲沒峴山西，倒著接䍦花下迷。","襄陽小兒齊拍手，攔街爭唱白銅鞮。","傍人借問笑何事，笑殺山公醉似泥。","鸕鷀杓，鸚鵡杯，百年三萬六千日，一日須傾三百杯。","遙看漢水鴨頭綠，恰似蒲萄初醱醅。","此江若變作春酒，壘麴便築糟丘臺。","千金駿馬換少妾，醉坐雕鞍歌落梅。","車傍側挂一壺酒，鳳笙龍管行相催。","咸陽市上歎黃犬，何如月下傾金罍。","君不見晉朝羊公一片石，龜龍剝落生莓苔。","淚亦不能爲之墮，心亦不能爲之哀。","誰能憂彼身後事，金鳧銀鴨葬死灰。","清風朗月不用一錢買，玉山自倒非人推。","舒州杓，力士鐺，李白與爾同死生。","襄王雲雨今安在，江水東流猨夜聲。"]', '["落日欲沒峴山西，倒著接䍦花下迷。","襄陽小兒齊拍手，攔街爭唱白銅鞮。","傍人借问笑何事，笑殺山公醉似泥。","鸕鷀杓，鸚鵡杯，百年三万六千日，一日須傾三百杯。","遙看漢水鴨头綠，恰似蒲萄初醱醅。","此江若变作春酒，壘麴便築糟丘台。","千金駿马換少妾，醉坐雕鞍歌落梅。","车傍側挂一壺酒，鳳笙龙管行相催。","咸陽市上歎黄犬，何如月下傾金罍。","君不见晉朝羊公一片石，龟龙剝落生莓苔。","泪亦不能爲之墮，心亦不能爲之哀。","誰能憂彼身後事，金鳧銀鴨葬死灰。","清风朗月不用一錢買，玉山自倒非人推。","舒州杓，力士鐺，李白與爾同死生。","襄王云雨今安在，江水东流猨夜声。"]', '诗', 'shi', '', NULL, '雜歌謠辭 襄陽歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e41582e-5f47-43e7-a146-5db2dd908a3d', '雜歌謠辭 襄陽曲 一', '杂歌謠辞 襄陽曲 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["襄陽行樂處，歌舞白銅鞮。","江城回淥水，花月使人迷。"]', '["襄陽行乐处，歌舞白銅鞮。","江城回淥水，花月使人迷。"]', '诗', 'shi', '', NULL, '雜歌謠辭 襄陽曲 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eb7ecb4-fb52-417b-869a-b0abaab68dd9', '雜歌謠辭 襄陽曲 二', '杂歌謠辞 襄陽曲 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["山公醉酒時，酩酊襄陽下。","頭上白接䍦，倒著還騎馬。"]', '["山公醉酒时，酩酊襄陽下。","头上白接䍦，倒著還騎马。"]', '诗', 'shi', '', NULL, '雜歌謠辭 襄陽曲 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52efc05d-16c8-4a3d-895b-729e4ff185a7', '雜歌謠辭 襄陽曲 三', '杂歌謠辞 襄陽曲 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["峴山臨漢江，水淥沙如雪。","上有墮淚碑，青苔久磨滅。"]', '["峴山臨漢江，水淥沙如雪。","上有墮泪碑，青苔久磨滅。"]', '诗', 'shi', '', NULL, '雜歌謠辭 襄陽曲 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57174957-5250-4879-83ca-38637fa8ae0d', '雜歌謠辭 襄陽曲 四', '杂歌謠辞 襄陽曲 四', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["且醉習家池，莫看墮淚碑。","山公欲上馬，笑殺襄陽兒。"]', '["且醉習家池，莫看墮泪碑。","山公欲上马，笑殺襄陽兒。"]', '诗', 'shi', '', NULL, '雜歌謠辭 襄陽曲 四 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586765d4-d654-4d4b-ae42-ddf1d407b0ec', '雜歌謠辭 蘇小小歌', '杂歌謠辞 蘇小小歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["幽蘭露，如啼眼。","無物結同心，煙花不堪翦。","草如茵，松如蓋。","風爲裳，水爲佩。","油壁車，久相待。","冷翠燭，勞光彩。","西陵下，風吹雨。"]', '["幽蘭露，如啼眼。","無物結同心，煙花不堪翦。","草如茵，松如蓋。","风爲裳，水爲佩。","油壁车，久相待。","冷翠燭，勞光彩。","西陵下，风吹雨。"]', '诗', 'shi', '', NULL, '雜歌謠辭 蘇小小歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83f293a-4450-4e24-88d2-1a2982c39954', '雜歌謠辭 蘇小小歌', '杂歌謠辞 蘇小小歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["買蓮莫破券，買酒莫解金。","酒裏春容抱離恨，水中蓮子懷芳心。","吳公女兒腰似束，家在錢塘小江曲。","一自檀郎逐便風，門前春水年年綠。"]', '["買蓮莫破券，買酒莫解金。","酒裏春容抱離恨，水中蓮子懷芳心。","吳公女兒腰似束，家在錢塘小江曲。","一自檀郎逐便风，门前春水年年綠。"]', '诗', 'shi', '', NULL, '雜歌謠辭 蘇小小歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd515d96-d07b-4570-bace-388ee60058fa', '雜歌謠辭 蘇小小歌 一', '杂歌謠辞 蘇小小歌 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["車輪不可遮，馬足不可絆。","長怨十字街，使郎心四散。"]', '["车輪不可遮，马足不可絆。","长怨十字街，使郎心四散。"]', '诗', 'shi', '', NULL, '雜歌謠辭 蘇小小歌 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61db4e7e-e0ec-4b52-9364-5666e4a009a5', '雜歌謠辭 蘇小小歌 二', '杂歌謠辞 蘇小小歌 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["新人千里去，故人千里來。","翦刀橫眼底，方覺淚難裁。"]', '["新人千里去，故人千里来。","翦刀橫眼底，方覺泪难裁。"]', '诗', 'shi', '', NULL, '雜歌謠辭 蘇小小歌 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f88e80a3-43e2-444f-a79e-87e461bc0e35', '雜歌謠辭 蘇小小歌 三', '杂歌謠辞 蘇小小歌 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["登山不愁峻，涉海不愁深。","中擘庭前棗，教郎見赤心。"]', '["登山不愁峻，涉海不愁深。","中擘庭前棗，教郎见赤心。"]', '诗', 'shi', '', NULL, '雜歌謠辭 蘇小小歌 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f6be926-a548-417f-8d4f-0a4b6a7c97fc', '雜歌謠辭 挾瑟歌', '杂歌謠辞 挾瑟歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["挾瑟爲君撫，君嫌聲太古。","寥寥倚浪絲，㗫㗫沈湘語。","賴有秋風知，清泠吹玉柱。"]', '["挾瑟爲君撫，君嫌声太古。","寥寥倚浪絲，㗫㗫沈湘語。","賴有秋风知，清泠吹玉柱。"]', '诗', 'shi', '', NULL, '雜歌謠辭 挾瑟歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f51fdf-af33-4359-9f89-f521724a9d0e', '雜歌謠辭 勅勒歌', '杂歌謠辞 勅勒歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["敕勒金隤壁，陰山無歲華。","帳外風飄雪，營前月照沙。","羌兒吹玉管，胡姬踏錦花。","却笑江南客，梅落不歸家。"]', '["敕勒金隤壁，陰山無歲华。","帳外风飄雪，營前月照沙。","羌兒吹玉管，胡姬踏錦花。","却笑江南客，梅落不归家。"]', '诗', 'shi', '', NULL, '雜歌謠辭 勅勒歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9ce3e6-afc6-4795-9744-9fe046c20acb', '雜歌謠辭 黃麞歌', '杂歌謠辞 黄麞歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黃麞黃麞草裏藏，彎弓射爾傷。"]', '["黄麞黄麞草裏藏，彎弓射爾傷。"]', '诗', 'shi', '', NULL, '雜歌謠辭 黃麞歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73afcd7d-4d62-49ea-96dc-b7a780311361', '雜歌謠辭 得体歌', '杂歌謠辞 得体歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["得体紇那也，紇囊得体那。","潭裏船車鬧，揚州銅器多。","三郎當殿坐，聽唱得体歌。"]', '["得体紇那也，紇囊得体那。","潭裏船车鬧，揚州銅器多。","三郎當殿坐，听唱得体歌。"]', '诗', 'shi', '', NULL, '雜歌謠辭 得体歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf12a3f4-93d1-436f-a7ec-c1c128cf326c', '雜歌謠辭 得寶歌', '杂歌謠辞 得寶歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["得寶弘農野，弘農得寶那。","潭裏船車鬧，揚州銅器多。","三郎當殿坐，聽唱得寶歌。"]', '["得寶弘農野，弘農得寶那。","潭裏船车鬧，揚州銅器多。","三郎當殿坐，听唱得寶歌。"]', '诗', 'shi', '', NULL, '雜歌謠辭 得寶歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac94232f-5510-466a-bac5-5a443c504a7b', '雜歌謠辭 黃臺瓜辭', '杂歌謠辞 黄台瓜辞', '0fc43481-64f8-4539-82e0-3dc7c4038e96', '唐', '["種瓜黃臺下，瓜熟子離離。","一摘使瓜好，再摘令瓜稀。","三摘尚自可，摘絕抱蔓歸。"]', '["種瓜黄台下，瓜熟子離離。","一摘使瓜好，再摘令瓜稀。","三摘尚自可，摘絕抱蔓归。"]', '诗', 'shi', '', NULL, '雜歌謠辭 黃臺瓜辭 章懷太子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a05bf553-aa6e-49b8-8988-a104d0207473', '雜歌謠辭 古歌', '杂歌謠辞 古歌', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["落葉流風向玉臺，夜寒秋思洞房開。","水精簾外金波下，雲母窗前銀漢迴。","玉階陰陰苔蘚色，君王履綦難再得。","璇閨窈窕秋夜長，繡戶徘徊秋月光。","燕姬綵帳芙蓉色，秦子金爐蘭麝香。","北斗七星橫夜半，清歌一曲斷君腸。"]', '["落葉流风向玉台，夜寒秋思洞房开。","水精簾外金波下，云母窗前銀漢迴。","玉階陰陰苔蘚色，君王履綦难再得。","璇閨窈窕秋夜长，繡戶徘徊秋月光。","燕姬綵帳芙蓉色，秦子金爐蘭麝香。","北斗七星橫夜半，清歌一曲斷君腸。"]', '诗', 'shi', '', NULL, '雜歌謠辭 古歌 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c3a6775-c5e3-49e6-9164-ddce72b05365', '雜歌謠辭 古歌 一', '杂歌謠辞 古歌 一', '0d7363f4-dd67-4fec-b5be-35d9a3e36323', '唐', '["美人怨何深，含情倚金閣。","不嚬復不語，紅淚雙雙落。"]', '["美人怨何深，含情倚金閣。","不嚬复不語，紅泪雙雙落。"]', '诗', 'shi', '', NULL, '雜歌謠辭 古歌 一 薛維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99febbb4-c89d-4dd3-b5b0-34f214cc495f', '雜歌謠辭 古歌 二', '杂歌謠辞 古歌 二', '0d7363f4-dd67-4fec-b5be-35d9a3e36323', '唐', '["美人閉紅燭，獨坐裁新錦。","頻放翦刀聲，夜寒知未寢。"]', '["美人閉紅燭，独坐裁新錦。","頻放翦刀声，夜寒知未寢。"]', '诗', 'shi', '', NULL, '雜歌謠辭 古歌 二 薛維翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a41b75c5-bd7f-48a5-b58f-a0f222e529ee', '雜歌謠辭 黃曇子歌', '杂歌謠辞 黄曇子歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["參差綠蒲短，搖豔雲塘滿。","紅瀲蕩融融，鶯翁鸂鶒暖。","萋芊小城路，馬上脩蛾懶。","羅衫褭向風，點粉金鸝卵。"]', '["參差綠蒲短，搖豔云塘满。","紅瀲蕩融融，鶯翁鸂鶒暖。","萋芊小城路，马上脩蛾懶。","羅衫褭向风，点粉金鸝卵。"]', '诗', 'shi', '', NULL, '雜歌謠辭 黃曇子歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9ac257-b84c-46fc-a19f-6e9ef2dae523', '雜歌謠辭 邯鄲郭公辭', '杂歌謠辞 邯鄲郭公辞', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["金笳悲故曲，玉座積深塵。","言是邯鄲伎，不易鄴城人。","青苔竟埋骨，紅粉自傷神。","唯有漳河柳，還向舊營春。"]', '["金笳悲故曲，玉座積深塵。","言是邯鄲伎，不易鄴城人。","青苔竟埋骨，紅粉自傷神。","唯有漳河柳，還向旧營春。"]', '诗', 'shi', '', NULL, '雜歌謠辭 邯鄲郭公辭 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9b92e2-c6ef-40fd-bf31-1bee53d208b7', '雜歌謠辭 箜篌謠', '杂歌謠辞 箜篌謠', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["攀天莫登龍，走山莫騎虎。","貴賤結交心不移，唯有嚴陵及光武。","周公稱大聖，管蔡寧相容。","漢謠一斗粟，不與淮南舂。","兄弟尚路人，吾心安所從。","它人方寸間，山海幾千重。","輕言託朋友，對面九疑峰。","多花必早落，桃李不如松。","管鮑久已死，何人繼其蹤。"]', '["攀天莫登龙，走山莫騎虎。","貴賤結交心不移，唯有嚴陵及光武。","周公稱大聖，管蔡寧相容。","漢謠一斗粟，不與淮南舂。","兄弟尚路人，吾心安所從。","它人方寸间，山海幾千重。","轻言託朋友，对面九疑峰。","多花必早落，桃李不如松。","管鲍久已死，何人繼其蹤。"]', '诗', 'shi', '', NULL, '雜歌謠辭 箜篌謠 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8d92958-dde2-4799-a5e0-0dab8a19f730', '雜歌謠辭 鄴城童子謠', '杂歌謠辞 鄴城童子謠', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["鄴城中，暮塵起。","將黑丸，斫文吏。","棘爲鞭，虎爲馬。","團團走，鄴城下。","切玉劒，射日弓。","獻何人，奉相公。","扶轂來，關右兒。","香掃塗，相公歸。"]', '["鄴城中，暮塵起。","將黑丸，斫文吏。","棘爲鞭，虎爲马。","團團走，鄴城下。","切玉劒，射日弓。","獻何人，奉相公。","扶轂来，关右兒。","香掃塗，相公归。"]', '诗', 'shi', '', NULL, '雜歌謠辭 鄴城童子謠 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e618dad-49ae-4159-acf0-afe65cd2a9c5', '雜歌謠辭 大麥行', '杂歌謠辞 大麦行', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["大麥乾枯小麥黃，婦人行泣夫走藏。","東至集壁西梁洋，問誰腰鎌胡與羌。","豈無蜀兵三千人，部領辛苦江山長。","安得如鳥有羽翅，託身白雲還故鄉。"]', '["大麦乾枯小麦黄，婦人行泣夫走藏。","东至集壁西梁洋，问誰腰鎌胡與羌。","豈無蜀兵三千人，部領辛苦江山长。","安得如鸟有羽翅，託身白云還故乡。"]', '诗', 'shi', '', NULL, '雜歌謠辭 大麥行 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f19b2b91-a9b0-483a-97f8-020e1578bc7a', '雜歌謠辭 白鼉鳴', '杂歌謠辞 白鼉鳴', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["天欲雨，有東風，南谿白鼉鳴窟中。","六月人家井無水，夜聞白鼉人盡起。"]', '["天欲雨，有东风，南谿白鼉鳴窟中。","六月人家井無水，夜闻白鼉人尽起。"]', '诗', 'shi', '', NULL, '雜歌謠辭 白鼉鳴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a6a3a76-5ac9-40f2-adfd-6f44708f4af7', '雜歌謠辭 步虛詞', '杂歌謠辞 步虛词', '5ae26e41-52b1-4abf-9b0e-4fb0336eac15', '唐', '["漢武清齋讀鼎書，內官扶上畫雲車。","壇上月明宮殿閉，仰看星斗禮空虛。"]', '["漢武清斋读鼎书，內官扶上畫云车。","壇上月明宮殿閉，仰看星斗禮空虛。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 陳羽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e915b2ba-e270-407f-82ef-581a2251363a', '雜歌謠辭 步虛詞', '杂歌謠辞 步虛词', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["逈步遊三洞，清心禮七真。","飛符超羽翼，禁火醮星辰。","殘藥霑雞犬，靈香出鳳麟。","壺中無窄處，願得一容身。"]', '["逈步游三洞，清心禮七真。","飞符超羽翼，禁火醮星辰。","殘藥霑雞犬，靈香出鳳麟。","壺中無窄处，願得一容身。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1419a84b-2586-444b-b987-5b874c580d0f', '雜歌謠辭 步虛詞 一', '杂歌謠辞 步虛词 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["阿母種桃雲海際，花落子成二千歲。","海風吹折最繁枝，跪捧瓊盤獻天帝。"]', '["阿母種桃云海際，花落子成二千歲。","海风吹折最繁枝，跪捧瓊盤獻天帝。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d83153-fbd8-42df-8bd5-86adda8647f0', '雜歌謠辭 步虛詞 二', '杂歌謠辞 步虛词 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["華表千年鶴一歸，凝丹爲頂雪爲衣。","星星仙語人聽盡，卻向五雲翻翅飛。"]', '["华表千年鹤一归，凝丹爲頂雪爲衣。","星星仙語人听尽，卻向五云翻翅飞。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3866dfc-b35f-4509-b5f8-5982afc6f8e9', '雜歌謠辭 步虛詞 一', '杂歌謠辞 步虛词 一', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["玉簡真人降，金書道籙通。","煙霞方蔽日，雲雨已生風。","四極威儀異，三天使命同。","那將人世戀，不去上清宮。"]', '["玉簡真人降，金书道籙通。","煙霞方蔽日，云雨已生风。","四極威儀異，三天使命同。","那將人世戀，不去上清宮。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 一 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da3bd0b-1b39-466b-b993-6c443efa6eda', '雜歌謠辭 步虛詞 二', '杂歌謠辞 步虛词 二', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["羽駕正翩翩，雲鴻最自然。","霞冠將月曉，珠佩與星連。","鏤玉留新訣，雕金得舊編。","不知飛鳥學，更有幾人仙。"]', '["羽駕正翩翩，云鴻最自然。","霞冠將月晓，珠佩與星連。","鏤玉留新訣，雕金得旧編。","不知飞鸟学，更有幾人仙。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 二 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b83ec7-0da0-466f-bb58-1760e11c5db1', '雜歌謠辭 步虛詞 三', '杂歌謠辞 步虛词 三', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["上帝求仙使，真符取玉郎。","三才閑布象，二景鬱生光。","騎吏排龍虎，笙歌走鳳凰。","天高人不見，暗入白雲鄉。"]', '["上帝求仙使，真符取玉郎。","三才闲布象，二景鬱生光。","騎吏排龙虎，笙歌走鳳凰。","天高人不见，暗入白云乡。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 三 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbbb2201-0886-4e21-9a12-97df21b3e7d1', '雜歌謠辭 步虛詞 四', '杂歌謠辞 步虛词 四', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["鸞鶴共徘徊，仙官使者催。","香花三洞啓，風雨百神來。","鳳篆文初定，龍泥印已開。","何須生羽翼，始得上瑤臺。"]', '["鸾鹤共徘徊，仙官使者催。","香花三洞啓，风雨百神来。","鳳篆文初定，龙泥印已开。","何須生羽翼，始得上瑤台。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 四 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0517b13e-619d-4ba5-997d-3e292a687710', '雜歌謠辭 步虛詞 五', '杂歌謠辞 步虛词 五', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["羽節忽排煙，蘇君已得仙。","命風驅日月，縮地走山川。","幾處留丹竈，何時種玉田。","一朝騎白虎，直上紫微天。"]', '["羽節忽排煙，蘇君已得仙。","命风驱日月，縮地走山川。","幾处留丹竈，何时種玉田。","一朝騎白虎，直上紫微天。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 五 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8083909a-98a6-41c4-9af4-9a6340fe0803', '雜歌謠辭 步虛詞 六', '杂歌謠辞 步虛词 六', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["靜發降靈香，思神意智長。","虎存時促步，龍想更成章。","扣齒風雷響，挑燈日月光。","仙雲在何處？髣髴滿空堂。"]', '["静發降靈香，思神意智长。","虎存时促步，龙想更成章。","扣齒风雷响，挑灯日月光。","仙云在何处？髣髴满空堂。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 六 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43156b03-9cf2-4570-ba54-39e7703d013c', '雜歌謠辭 步虛詞 七', '杂歌謠辞 步虛词 七', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["幾度遊三洞，何方召百神。","風雲皆守一，龍虎亦全真。","執節仙童小，燒香玉女春。","應須絕巖內，委曲問皇人。"]', '["幾度游三洞，何方召百神。","风云皆守一，龙虎亦全真。","執節仙童小，燒香玉女春。","應須絕巖內，委曲问皇人。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 七 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba7df95-43d1-4edc-97fa-67d1c5a04670', '雜歌謠辭 步虛詞 八', '杂歌謠辞 步虛词 八', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["上法杳無營，玄脩似有情。","道宮瓊作想，真帝玉爲名。","召岳驅旌節，馳雷發吏兵。","雲車降何處，齋室有仙卿。"]', '["上法杳無營，玄脩似有情。","道宮瓊作想，真帝玉爲名。","召岳驱旌節，驰雷發吏兵。","云车降何处，斋室有仙卿。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 八 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac905a3-45b5-4f3d-bbc8-41e5c013c536', '雜歌謠辭 步虛詞 九', '杂歌謠辞 步虛词 九', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["羽衛一何鮮，香雲起莫煙。","方朝太素帝，更向玉清天。","鳳曲凝猶吹，龍驂儼欲前。","真文幾時降，知在永和年。"]', '["羽衛一何鲜，香云起莫煙。","方朝太素帝，更向玉清天。","鳳曲凝猶吹，龙驂儼欲前。","真文幾时降，知在永和年。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 九 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbeb1985-4ecd-414c-b1fa-93291d9a3584', '雜歌謠辭 步虛詞 十', '杂歌謠辞 步虛词 十', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["大道何年學，真符此日催。","還持金作印，未要玉爲臺。","羽節分明授，霞衣整頓裁。","應緣五雲使，教上列仙來。"]', '["大道何年学，真符此日催。","還持金作印，未要玉爲台。","羽節分明授，霞衣整頓裁。","應緣五云使，教上列仙来。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b022e6f1-f198-4b97-9bb9-abbf7d5f449d', '雜歌謠辭 步虛詞 十一', '杂歌謠辞 步虛词 十一', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["獨自授金書，蕭條詠紫虛。","龍行還當馬，雲起自成車。","九轉風煙合，千年井竈餘。","參差從太一，壽等混元初。"]', '["独自授金书，蕭條詠紫虛。","龙行還當马，云起自成车。","九轉风煙合，千年井竈餘。","參差從太一，壽等混元初。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十一 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69dd2b05-b6db-4c1f-8bd4-25eb2f0e52da', '雜歌謠辭 步虛詞 十二', '杂歌謠辞 步虛词 十二', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["道學已通神，香花會女真。","霞牀珠斗帳，金薦玉輿輪。","一室心偏靜，三天夜正春。","靈官竟誰降，仙相有夫人。"]', '["道学已通神，香花會女真。","霞牀珠斗帳，金薦玉輿輪。","一室心偏静，三天夜正春。","靈官竟誰降，仙相有夫人。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十二 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b7348a-f58e-45d9-b189-a44006b6cbf9', '雜歌謠辭 步虛詞 十三', '杂歌謠辞 步虛词 十三', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["上界有黃房，仙家道路長。","神來知位次，樂變協宮商。","競把瑠璃椀，誰傾白玉漿。","霞衣最芬馥，蘇合是靈香。"]', '["上界有黄房，仙家道路长。","神来知位次，乐变協宮商。","競把瑠璃椀，誰傾白玉漿。","霞衣最芬馥，蘇合是靈香。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十三 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1aca20-ff6b-4fee-a980-51837a113859', '雜歌謠辭 步虛詞 十四', '杂歌謠辞 步虛词 十四', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["珠佩紫霞纓，夫人會八靈。","太霄猶有觀，絕宅豈無形。","暮雨徘徊降，仙歌宛轉聽。","誰逢玉妃輦，應檢九真經。"]', '["珠佩紫霞纓，夫人會八靈。","太霄猶有观，絕宅豈無形。","暮雨徘徊降，仙歌宛轉听。","誰逢玉妃輦，應檢九真經。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十四 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba8aaa0-cfe6-43e7-8719-37788175ab51', '雜歌謠辭 步虛詞 十五', '杂歌謠辞 步虛词 十五', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["西海辭金母，東方拜木公。","雲行疑帶雨，星步欲凌風。","羽袖揮丹鳳，霞巾曳彩虹。","飄颻九霄外，下視望仙宮。"]', '["西海辞金母，东方拜木公。","云行疑带雨，星步欲凌风。","羽袖揮丹鳳，霞巾曳彩虹。","飄颻九霄外，下視望仙宮。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十五 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad936cc9-207f-4294-82ef-8e9c33c9af77', '雜歌謠辭 步虛詞 十六', '杂歌謠辞 步虛词 十六', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["玉樹雜金花，天河織女家。","月邀丹鳳舄，風送紫鸞車。","霧縠籠綃帶，雲屏列錦霞。","瑤臺千萬里，不覺往來賒。"]', '["玉樹杂金花，天河织女家。","月邀丹鳳舄，风送紫鸾车。","霧縠籠綃带，云屏列錦霞。","瑤台千万里，不覺往来賒。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十六 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a98b4ea-6579-4c08-a8ce-06acde7b0969', '雜歌謠辭 步虛詞 十七', '杂歌謠辞 步虛词 十七', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["舞鳳凌天出，歌麟入夜聽。","雲容衣眇眇，風韻曲泠泠。","扣齒端金簡，焚香檢玉經。","仙宮知不遠，只近太微星。"]', '["舞鳳凌天出，歌麟入夜听。","云容衣眇眇，风韻曲泠泠。","扣齒端金簡，焚香檢玉經。","仙宮知不远，只近太微星。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十七 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d971bf7f-46c9-4db7-bf96-a5e2aaaaeac3', '雜歌謠辭 步虛詞 十八', '杂歌謠辞 步虛词 十八', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["紫府與玄洲，誰來物外遊。","無煩騎白鹿，不用駕青牛。","金化顏應駐，雲飛鬢不秋。","仍聞碧海上，更用玉爲樓。"]', '["紫府與玄洲，誰来物外游。","無煩騎白鹿，不用駕青牛。","金化顏應駐，云飞鬢不秋。","仍闻碧海上，更用玉爲楼。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十八 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d135fc0c-6b64-4717-a622-dd8364180d8a', '雜歌謠辭 步虛詞 十九', '杂歌謠辞 步虛词 十九', 'adbd8eca-9171-4bf6-adfa-c1653da9fc9b', '唐', '["轡鶴復驂鸞，全家去不難。","雞聲隨羽化，犬影入雲看。","釀玉當成酒，燒金且轉丹。","何妨五色綬，次第給仙官。"]', '["轡鹤复驂鸾，全家去不难。","雞声隨羽化，犬影入云看。","釀玉當成酒，燒金且轉丹。","何妨五色綬，次第給仙官。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 十九 韋渠牟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b2d4ae-5cfb-4466-b83f-8eac8698c4de', '雜歌謠辭 步虛詞', '杂歌謠辞 步虛词', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["予因覽真訣，遂感西域君。","玉笙下青冥，人間未曾聞。","日華鍊魂魄，皎皎無垢氛。","謂我有仙骨，且令餌氤氳。","俯仰媿靈顏，願隨鸞鶴羣。","俄然動風馭，縹眇歸青雲。"]', '["予因覽真訣，遂感西域君。","玉笙下青冥，人间未曾闻。","日华鍊魂魄，皎皎無垢氛。","謂我有仙骨，且令餌氤氳。","俯仰媿靈顏，願隨鸾鹤羣。","俄然动风馭，縹眇归青云。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c6ad53-fd93-491b-9813-403ffa980c9c', '雜歌謠辭 步虛詞', '杂歌謠辞 步虛词', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["青溪道士人不識，上天下天鶴一隻。","洞門深[鎖]碧窗寒，滴露妍朱寫周易。"]', '["青溪道士人不識，上天下天鹤一隻。","洞门深[鎖]碧窗寒，滴露妍朱寫周易。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛詞 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc078f6-329e-4946-9119-45a21dc0b296', '雜歌謠辭 步虛引', '杂歌謠辞 步虛引', 'fb352359-7e7f-42ea-b777-0181bc1d9aeb', '唐', '["小隱山人十洲客，莓苔爲衣雙耳白。","青編爲我忽降書，暮雨虹蜺一千尺。","赤城門閉六丁直，曉日已燒東海色。","朝天半夜聞玉雞，星斗離離礙龍翼。"]', '["小隐山人十洲客，莓苔爲衣雙耳白。","青編爲我忽降书，暮雨虹蜺一千尺。","赤城门閉六丁直，晓日已燒东海色。","朝天半夜闻玉雞，星斗離離礙龙翼。"]', '诗', 'shi', '', NULL, '雜歌謠辭 步虛引 陳陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca656c4-d936-46cb-8630-b2dae6251766', '詠漢高祖', '詠漢高祖', '53023a4e-4e2c-434f-9995-61119152afcb', '唐', '["漢祖起豐沛，乘運以躍鱗。","手奮三尺劒，西滅無道秦。","十月五星聚，七年四海賓。","高抗威宇宙，貴有天下人。","憶昔與項王，契闊時未伸。","鴻門既薄蝕，滎陽亦蒙塵。","蟣虱生介胄，將卒多苦辛。","爪牙驅信越，腹心謀張陳。","赫赫西楚國，化爲丘與榛。"]', '["漢祖起豐沛，乘運以躍鱗。","手奮三尺劒，西滅無道秦。","十月五星聚，七年四海賓。","高抗威宇宙，貴有天下人。","憶昔與項王，契闊时未伸。","鴻门既薄蝕，滎陽亦蒙塵。","蟣虱生介胄，將卒多苦辛。","爪牙驱信越，腹心謀張陳。","赫赫西楚国，化爲丘與榛。"]', '诗', 'shi', '', NULL, '詠漢高祖 王珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2b4d9df-6414-4a7a-8a4b-ee05830d0371', '詠淮陰侯', '詠淮陰侯', '53023a4e-4e2c-434f-9995-61119152afcb', '唐', '["秦王日凶慝，豪傑爭共亡。","信亦胡爲者，劍歌從項梁。","項羽不能用，脫身歸漢王。","道契君臣合，時來名位彰。","北討燕承命，東驅楚絕糧。","斬龍堰濉水，擒豹熸夏陽。","功成享天祿，建旗還南昌。","千金答漂母，百錢酬下鄉。","吉凶成糾纏，倚伏難預詳。","弓藏狡兔盡，慷慨念心傷。"]', '["秦王日凶慝，豪傑爭共亡。","信亦胡爲者，劍歌從項梁。","項羽不能用，脫身归漢王。","道契君臣合，时来名位彰。","北討燕承命，东驱楚絕糧。","斬龙堰濉水，擒豹熸夏陽。","功成享天祿，建旗還南昌。","千金答漂母，百錢酬下乡。","吉凶成糾纏，倚伏难預詳。","弓藏狡兔尽，慷慨念心傷。"]', '诗', 'shi', '', NULL, '詠淮陰侯 王珪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d0056af-ad39-4df9-adf3-aed70b2c3ac0', '早春桂林殿應詔', '早春桂林殿應詔', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["金鋪照春色，玉律動年華。","朱樓雲似蓋，丹桂雪如花。","水岸銜階轉，風條出柳斜。","輕輿臨太液，湛露酌流霞。"]', '["金鋪照春色，玉律动年华。","朱楼云似蓋，丹桂雪如花。","水岸銜階轉，风條出柳斜。","轻輿臨太液，湛露酌流霞。"]', '诗', 'shi', '', NULL, '早春桂林殿應詔 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce59dfc-a30e-4e52-a9c7-f2e77552e7d8', '後渚置酒', '後渚置酒', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["大渚初驚夜，中流沸鼓鼙。","寒沙滿曲浦，夕霧上邪谿。","岸廣鳧飛急，雲深鴈度低。","嚴關猶未遂，此夕待晨雞。"]', '["大渚初驚夜，中流沸鼓鼙。","寒沙满曲浦，夕霧上邪谿。","岸廣鳧飞急，云深鴈度低。","嚴关猶未遂，此夕待晨雞。"]', '诗', 'shi', '', NULL, '後渚置酒 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da6fb81c-3737-4c6a-9762-b278d6148a14', '聽鄰人琵琶', '听鄰人琵琶', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["本是龍門桐，因妍入漢宮。","香緣羅袖裏，聲逐朱弦中。","雖有相思韻，翻將入塞同。","關山臨却月，花蘂散迴風。","爲將金谷引，添令曲未終。"]', '["本是龙门桐，因妍入漢宮。","香緣羅袖裏，声逐朱弦中。","雖有相思韻，翻將入塞同。","关山臨却月，花蘂散迴风。","爲將金谷引，添令曲未終。"]', '诗', 'shi', '', NULL, '聽鄰人琵琶 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79dff142-77e3-45b2-8760-27629772a923', '州城西園入齋祠社', '州城西园入斋祠社', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["升壇預潔祀，詰早肅分司。","達氣風霜積，登光日色遲。","農教先八政，陽和秩四時。","祈年服垂冕，告幣動褰帷。","瘞地尊餘奠，人天庶有資。","椒蘭卒清酌，簠簋徹香萁。","折俎分歸胙，充庭降受釐。","方憑知禮節，況奉化雍熙。"]', '["升壇預潔祀，詰早肅分司。","達氣风霜積，登光日色遲。","農教先八政，陽和秩四时。","祈年服垂冕，告幣动褰帷。","瘞地尊餘奠，人天庶有資。","椒蘭卒清酌，簠簋徹香萁。","折俎分归胙，充庭降受釐。","方憑知禮節，況奉化雍熙。"]', '诗', 'shi', '', NULL, '州城西園入齋祠社 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('883d2200-4f5e-4961-9844-e33ec60c592c', '春首', '春首', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["雪花聯玉樹，冰彩散瑤池。","翔禽遙出沒，積翠遠參差。"]', '["雪花聯玉樹，冰彩散瑤池。","翔禽遙出沒，積翠远參差。"]', '诗', 'shi', '', NULL, '春首 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d30d32b3-3fcb-421a-b6fe-220633ce047d', '初年', '初年', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["和風起天路，嚴氣消冰井。","索索枝未柔，厭厭漏猶永。"]', '["和风起天路，嚴氣消冰井。","索索枝未柔，厭厭漏猶永。"]', '诗', 'shi', '', NULL, '初年 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc114608-fa50-4999-8471-217ef1936685', '詠菊', '詠菊', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["霜間開紫蔕，露下發金英。","但令逢採摘，寧辭獨晚榮。"]', '["霜间开紫蔕，露下發金英。","但令逢採摘，寧辞独晚榮。"]', '诗', 'shi', '', NULL, '詠菊 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bc9397-7390-4011-8e08-9b0dc66b9288', '自君之出矣', '自君之出矣', 'eea28cb8-ee3d-4709-889b-f87f9e8bf36f', '唐', '["自君之出矣，金爐香不然。","思君當明燭，終宵空自煎。"]', '["自君之出矣，金爐香不然。","思君當明燭，終宵空自煎。"]', '诗', 'shi', '', NULL, '自君之出矣 王融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba4c2e3-c8e8-44f3-97db-8185dba8db72', '自君之出矣  一', '自君之出矣  一', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["自君之出矣，紅顏轉憔悴。","思君如明燭，煎心且銜淚。"]', '["自君之出矣，紅顏轉憔悴。","思君如明燭，煎心且銜泪。"]', '诗', 'shi', '', NULL, '自君之出矣  一 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1210127-bddc-42f8-bd1b-8bd84f016114', '自君之出矣  二', '自君之出矣  二', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["自君之出矣，明鏡罷紅妝。","思君如夜燭，煎淚幾千行。"]', '["自君之出矣，明镜罷紅妝。","思君如夜燭，煎泪幾千行。"]', '诗', 'shi', '', NULL, '自君之出矣  二 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c6f3b8e-01b6-4086-ad0c-5342311fafb1', '賦飲馬長城窟', '賦饮马长城窟', '7f5b8321-3a66-4a98-8eae-a72d67d79920', '唐', '["朔風動秋草，清蹕長安道。","長城連不窮，所以隔華戎。","規模惟聖作，負荷曉成功。","鳥庭已向內，龍荒更鑿空。","玉關塵卷靜，金微路已通。","湯征隨北怨，舜詠起南風。","畫地功初立，綏邊事云集。","朝服踐狼居，凱歌旋馬邑。","山響傳鳳吹，霜華藻瓊鈒。","屬國擁節歸，單于款關入。","日落寒風起，驚蓬被原隰。","零落葉已寒，河流清且急。","四時徭役盡，千載干戈戢。","太平今若斯，汗馬竟無施。","唯當事筆硯，歸去草封禪。"]', '["朔风动秋草，清蹕长安道。","长城連不窮，所以隔华戎。","規模惟聖作，負荷晓成功。","鸟庭已向內，龙荒更鑿空。","玉关塵卷静，金微路已通。","湯征隨北怨，舜詠起南风。","畫地功初立，綏邊事云集。","朝服踐狼居，凱歌旋马邑。","山响傳鳳吹，霜华藻瓊鈒。","屬国擁節归，單于款关入。","日落寒风起，驚蓬被原隰。","零落葉已寒，河流清且急。","四时徭役尽，千載干戈戢。","太平今若斯，汗马竟無施。","唯當事笔硯，归去草封禪。"]', '诗', 'shi', '', NULL, '賦飲馬長城窟 袁朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1e06d6d-3965-450a-8705-4a9a9a907aa0', '和洗掾登城南坂望京邑', '和洗掾登城南坂望京邑', '7f5b8321-3a66-4a98-8eae-a72d67d79920', '唐', '["二華連陌塞，九隴統金方。","奧區稱富貴，重險擅雄強。","龍飛灞水上，鳳集岐山陽。","神皐多瑞蹟，列代有興王。","我后膺靈命，爰求宅茲土。","宸居法太微，建國資天府。","玄風叶黎庶，德澤浸區宇。","醒醉各相扶，謳歌從聖主。","南登少陵岸，還望帝城中。","帝城何鬱鬱，佳氣乃蔥蔥。","金鳳凌綺觀，璇題敞蘭宮。","複道東西合，交衢南北通。","萬國朝前殿，羣公議宣室。","鳴珮含早風，華蟬曜朝日。","栢梁宴初罷，千鍾歡未畢。","端拱肅巖廊，思賢聽琴瑟。","逶迤萬雉列，隱軫千閭布。","飛甍夾御溝，曲臺臨上路。","處處歌鐘鳴，喧闐車馬度。","日落長楸間，含情兩相顧。","是月冬之季，陰寒晝不開。","驚風四面集，飛雪千里迴。","狐白登廊廟，牛衣出草萊。","詎知韓長孺，無復重然灰。"]', '["二华連陌塞，九隴統金方。","奧區稱富貴，重險擅雄強。","龙飞灞水上，鳳集岐山陽。","神皐多瑞蹟，列代有兴王。","我后膺靈命，爰求宅茲土。","宸居法太微，建国資天府。","玄风叶黎庶，德澤浸區宇。","醒醉各相扶，謳歌從聖主。","南登少陵岸，還望帝城中。","帝城何鬱鬱，佳氣乃蔥蔥。","金鳳凌綺观，璇題敞蘭宮。","複道东西合，交衢南北通。","万国朝前殿，羣公議宣室。","鳴珮含早风，华蟬曜朝日。","栢梁宴初罷，千鍾歡未畢。","端拱肅巖廊，思賢听琴瑟。","逶迤万雉列，隐軫千閭布。","飞甍夾御溝，曲台臨上路。","处处歌鐘鳴，喧闐车马度。","日落长楸间，含情兩相顧。","是月冬之季，陰寒晝不开。","驚风四面集，飞雪千里迴。","狐白登廊廟，牛衣出草萊。","詎知韓长孺，無复重然灰。"]', '诗', 'shi', '', NULL, '和洗掾登城南坂望京邑 袁朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8790539-a9ff-4935-b413-02b36e109943', '秋日應詔', '秋日應詔', '7f5b8321-3a66-4a98-8eae-a72d67d79920', '唐', '["玉樹涼風舉，金塘細草萎。","葉落商飆觀，鴻歸明月池。","迎寒桂酒熟，含露菊花垂。","一奉章臺宴，千秋長願斯。"]', '["玉樹涼风舉，金塘細草萎。","葉落商飆观，鴻归明月池。","迎寒桂酒熟，含露菊花垂。","一奉章台宴，千秋长願斯。"]', '诗', 'shi', '', NULL, '秋日應詔 袁朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e33d15-96d6-41a8-b473-067d61204335', '秋夜獨坐', '秋夜独坐', '7f5b8321-3a66-4a98-8eae-a72d67d79920', '唐', '["危弦斷客心，虛彈落驚禽。","新秋百慮淨，獨夜九愁深。","枯蓬唯逐吹，墜葉不歸林。","如何悲此曲，坐作白頭吟。"]', '["危弦斷客心，虛彈落驚禽。","新秋百慮淨，独夜九愁深。","枯蓬唯逐吹，墜葉不归林。","如何悲此曲，坐作白头吟。"]', '诗', 'shi', '', NULL, '秋夜獨坐 袁朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7f6bafd-608d-456f-a3b7-b83a99baebc5', '出塞曲', '出塞曲', 'c1fedae5-e7a5-4a8f-888b-1bf1e4629b80', '唐', '["匈奴屢不平，漢將欲縱橫。","看雲方結陣，却月始連營。","潛軍度馬邑，揚斾掩龍城。","會勒燕然石，方傳車騎名。"]', '["匈奴屢不平，漢將欲縱橫。","看云方結陣，却月始連營。","潛軍度马邑，揚斾掩龙城。","會勒燕然石，方傳车騎名。"]', '诗', 'shi', '', NULL, '出塞曲 竇威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d640d9f-392a-462d-8c28-2d491b55a855', '新曲二首 一', '新曲二首 一', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["阿儂家住朝歌下，早傳名。","結伴來游淇水上，舊長情。","玉珮金鈿隨步遠，雲羅霧縠逐風輕。","轉目機心懸自許，何須更待聽琴聲。"]', '["阿儂家住朝歌下，早傳名。","結伴来游淇水上，旧长情。","玉珮金鈿隨步远，云羅霧縠逐风轻。","轉目機心懸自許，何須更待听琴声。"]', '诗', 'shi', '', NULL, '新曲二首 一 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b24f270a-b351-4b5e-b576-3ced55cd14f9', '新曲二首 二', '新曲二首 二', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["迴雪凌波游洛浦，遇陳王。","婉約娉婷工語笑，侍蘭房。","芙蓉綺帳還開揜，翡翠珠被爛齊光。","長願今宵奉顏色，不愛吹簫逐鳳皇。"]', '["迴雪凌波游洛浦，遇陳王。","婉約娉婷工語笑，侍蘭房。","芙蓉綺帳還开揜，翡翠珠被爛齊光。","长願今宵奉顏色，不愛吹簫逐鳳皇。"]', '诗', 'shi', '', NULL, '新曲二首 二 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1948620-90a5-4133-a42a-4d7724a2e518', '灞橋待李將軍', '灞橋待李將軍', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["颯颯風葉下，遙遙煙景曛。","霸陵無醉尉，誰滯李將軍。"]', '["颯颯风葉下，遙遙煙景曛。","霸陵無醉尉，誰滯李將軍。"]', '诗', 'shi', '', NULL, '灞橋待李將軍 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9a5f31-2b78-46fb-9217-3d51e10af5bf', '奉和正日臨朝', '奉和正日臨朝', 'b6836194-e82a-4608-9d1e-caf1ad420ea0', '唐', '["七府璿衡始，三元寶曆新。","負扆延百辟，垂旒御九賓。","肅肅皆鵷鷺，濟濟盛簪紳。","天涯致重譯，日域獻奇珍。"]', '["七府璿衡始，三元寶曆新。","負扆延百辟，垂旒御九賓。","肅肅皆鵷鷺，濟濟盛簪紳。","天涯致重譯，日域獻奇珍。"]', '诗', 'shi', '', NULL, '奉和正日臨朝 顏師古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e6ba48f-a140-4e73-9f1d-f00a55c2c9bd', '召拜御史大夫贈袁天綱', '召拜御史大夫贈袁天綱', '758ace17-4da9-471d-a106-2ce666d48378', '唐', '["伊呂深可慕，松喬定是虛。","繫風終不得，脫屣欲安如。","且珍紈素美，當與薜蘿疎。","既逢楊得意，非復久閑居。"]', '["伊呂深可慕，松喬定是虛。","繫风終不得，脫屣欲安如。","且珍紈素美，當與薜蘿疎。","既逢楊得意，非复久闲居。"]', '诗', 'shi', '', NULL, '召拜御史大夫贈袁天綱 杜淹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0212665-b88b-4425-8c17-9c78aaca8203', '詠寒食鬬雞應秦王教', '詠寒食鬬雞應秦王教', '758ace17-4da9-471d-a106-2ce666d48378', '唐', '["寒食東郊道，揚鞲競出籠。","花冠初照日，芥羽正生風。","顧敵知心勇，先鳴覺氣雄。","長翹頻掃陣，利爪屢通中。","飛毛遍綠野，灑血漬芳叢。","雖然百戰勝，會自不論功。"]', '["寒食东郊道，揚鞲競出籠。","花冠初照日，芥羽正生风。","顧敵知心勇，先鳴覺氣雄。","长翹頻掃陣，利爪屢通中。","飞毛遍綠野，灑血漬芳叢。","雖然百戰勝，會自不論功。"]', '诗', 'shi', '', NULL, '詠寒食鬬雞應秦王教 杜淹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3270b5d8-2783-41fe-9868-ad4cbab63477', '寄贈齊公', '寄贈齊公', '758ace17-4da9-471d-a106-2ce666d48378', '唐', '["冠蓋游梁日，詩書問志年。","佩蘭長坂上，攀桂小山前。","結交澹若水，履道直如弦。","此歡終未極，于茲獨播遷。","赭衣登蜀道，白首別秦川。","淚隨溝水逝，心逐曉旌懸。","去去逾千里，悠悠隔九天。","郊野間長薄，城闕隱凝煙。","關門共月對，山路與雲連。","此時寸心裏，難用尺書傳。"]', '["冠蓋游梁日，诗书问志年。","佩蘭长坂上，攀桂小山前。","結交澹若水，履道直如弦。","此歡終未極，于茲独播遷。","赭衣登蜀道，白首別秦川。","泪隨溝水逝，心逐晓旌懸。","去去逾千里，悠悠隔九天。","郊野间长薄，城闕隐凝煙。","关门共月对，山路與云連。","此时寸心裏，难用尺书傳。"]', '诗', 'shi', '', NULL, '寄贈齊公 杜淹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c15a70-31d9-4e06-92c1-d3363a58a937', '五郊樂章 黃帝宮音', '五郊乐章 黄帝宮音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["黃中正位，含章居貞。","既長六律，兼和五聲。","畢陳萬舞，乃薦斯牲。","神其下降，永祚休平。"]', '["黄中正位，含章居貞。","既长六律，兼和五声。","畢陳万舞，乃薦斯牲。","神其下降，永祚休平。"]', '诗', 'shi', '', NULL, '五郊樂章 黃帝宮音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5acfc1c-dc8a-46a0-8be1-6d03c83b50a7', '五郊樂章 黃帝宮音 肅和', '五郊乐章 黄帝宮音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["眇眇方輿，蒼蒼圜蓋。","至哉樞紐，宅中圖大。","氣調四序，風和萬籟。","祚我明德，時雍道泰。"]', '["眇眇方輿，蒼蒼圜蓋。","至哉樞紐，宅中圖大。","氣調四序，风和万籟。","祚我明德，时雍道泰。"]', '诗', 'shi', '', NULL, '五郊樂章 黃帝宮音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3d63b68-644c-48ef-b1f7-be8c09a68c76', '五郊樂章 黃帝宮音 雍和', '五郊乐章 黄帝宮音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["金懸夕肆，玉俎朝陳。","饗薦黃道，芬流紫辰。","廼誠廼敬，載享載禋。","崇薦斯在，惟皇是賓。"]', '["金懸夕肆，玉俎朝陳。","饗薦黄道，芬流紫辰。","廼誠廼敬，載享載禋。","崇薦斯在，惟皇是賓。"]', '诗', 'shi', '', NULL, '五郊樂章 黃帝宮音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bba78c6c-280c-4775-bf56-953cb976e743', '五郊樂章 黃帝宮音 舒和', '五郊乐章 黄帝宮音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["御徵乘宮出郊甸，安歌率舞逓將迎。","自有雲門符帝賞，猶持雷鼓荅天成。"]', '["御徵乘宮出郊甸，安歌率舞逓將迎。","自有云门符帝賞，猶持雷鼓荅天成。"]', '诗', 'shi', '', NULL, '五郊樂章 黃帝宮音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bcd14f2-8b14-48f3-9be8-a49ccb2985d1', '五郊樂章 青帝角音', '五郊乐章 青帝角音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["鶴雲旦起，鳥星昏集。","律候新風，陽開初蟄。","至德可饗，行潦斯挹。","錫以無疆，烝人乃粒。"]', '["鹤云旦起，鸟星昏集。","律候新风，陽开初蟄。","至德可饗，行潦斯挹。","錫以無疆，烝人乃粒。"]', '诗', 'shi', '', NULL, '五郊樂章 青帝角音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b4011f-a3cb-4d7a-bbc5-bfbb382dd23b', '五郊樂章 青帝角音 肅和', '五郊乐章 青帝角音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["玄鳥司春，蒼龍登歲。","節物變柳，光風轉蕙。","瑤席降神，朱弦饗帝。","誠備祝嘏，禮殫珪幣。"]', '["玄鸟司春，蒼龙登歲。","節物变柳，光风轉蕙。","瑤席降神，朱弦饗帝。","誠備祝嘏，禮殫珪幣。"]', '诗', 'shi', '', NULL, '五郊樂章 青帝角音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5e0fdf-9fcb-4228-b07e-332764956a0b', '五郊樂章 青帝角音 雍和', '五郊乐章 青帝角音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["大樂稀音，至誠簡禮。","文物棣棣，聲名濟濟。","六變有成，三登無體。","廼眷豐絜，恩覃愷悌。"]', '["大乐稀音，至誠簡禮。","文物棣棣，声名濟濟。","六变有成，三登無體。","廼眷豐絜，恩覃愷悌。"]', '诗', 'shi', '', NULL, '五郊樂章 青帝角音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f90090ac-d9c6-42f1-840f-9a09f4db1448', '五郊樂章 青帝角音 舒和', '五郊乐章 青帝角音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["笙歌籥舞屬年韶，鷺鼓鳧鐘展時豫。","調露初迎綺春節，承雲遽踐蒼霄馭。"]', '["笙歌籥舞屬年韶，鷺鼓鳧鐘展时豫。","調露初迎綺春節，承云遽踐蒼霄馭。"]', '诗', 'shi', '', NULL, '五郊樂章 青帝角音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('101e2502-ed57-4e83-b18f-b8d2529933be', '五郊樂章 赤帝徵音', '五郊乐章 赤帝徵音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["青陽告謝，朱明戒序。","咸長是祈，敬陳椒醑。","博碩斯薦，笙鏞備舉。","庶盡肅恭，非馨稷黍。"]', '["青陽告謝，朱明戒序。","咸长是祈，敬陳椒醑。","博碩斯薦，笙鏞備舉。","庶尽肅恭，非馨稷黍。"]', '诗', 'shi', '', NULL, '五郊樂章 赤帝徵音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc4c33d7-2981-4377-8468-5bc401128ffc', '五郊樂章 赤帝徵音 肅和', '五郊乐章 赤帝徵音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["離位克明，火中宵見。","峯雲暮起，景風晨扇。","木槿初榮，含桃可薦。","芬馥百品，鏗鏘三變。"]', '["離位克明，火中宵见。","峯云暮起，景风晨扇。","木槿初榮，含桃可薦。","芬馥百品，鏗鏘三变。"]', '诗', 'shi', '', NULL, '五郊樂章 赤帝徵音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('904bb636-f948-4ace-9822-ee7eb54a525c', '五郊樂章 赤帝徵音 雍和', '五郊乐章 赤帝徵音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["昭昭丹陸，帟帟炎方。","禮陳牲幣，樂備箎簧。","瓊羞溢俎，玉𨣧浮觴。","恭惟正直，歆此馨香。"]', '["昭昭丹陸，帟帟炎方。","禮陳牲幣，乐備箎簧。","瓊羞溢俎，玉𨣧浮觴。","恭惟正直，歆此馨香。"]', '诗', 'shi', '', NULL, '五郊樂章 赤帝徵音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8068673e-5d5b-48be-8474-96204ac348ef', '五郊樂章 赤帝徵音 舒和', '五郊乐章 赤帝徵音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["千里溫風飄降羽，十枝炎景媵朱干。","陳觴薦俎歌三獻，拊石摐金會七盤。"]', '["千里溫风飄降羽，十枝炎景媵朱干。","陳觴薦俎歌三獻，拊石摐金會七盤。"]', '诗', 'shi', '', NULL, '五郊樂章 赤帝徵音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1dafdd-8251-46d8-a703-e7422bec309d', '五郊樂章 白帝商音', '五郊乐章 白帝商音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["白藏應節，天高氣清。","歲功既阜，庶類收成。","萬方靜謐，九土和平。","馨香是薦，受祚聰明。"]', '["白藏應節，天高氣清。","歲功既阜，庶類收成。","万方静謐，九土和平。","馨香是薦，受祚聰明。"]', '诗', 'shi', '', NULL, '五郊樂章 白帝商音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a7bd4e-421b-409c-ba86-5511f9738184', '五郊樂章 白帝商音 肅和', '五郊乐章 白帝商音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["金行在節，素靈居正。","氣肅霜嚴，林凋草勁。","豺祭隼擊，潦收川鏡。","九穀已登，萬箱流詠。"]', '["金行在節，素靈居正。","氣肅霜嚴，林凋草勁。","豺祭隼擊，潦收川镜。","九穀已登，万箱流詠。"]', '诗', 'shi', '', NULL, '五郊樂章 白帝商音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b5b795-87d8-43eb-b05a-7a704d4797ed', '五郊樂章 白帝商音 雍和', '五郊乐章 白帝商音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["律應西成，氣躔南呂。","珪幣咸列，笙竽備舉。","苾苾蘭羞，芬芬桂醑。","式資宴貺，用調霜序。"]', '["律應西成，氣躔南呂。","珪幣咸列，笙竽備舉。","苾苾蘭羞，芬芬桂醑。","式資宴貺，用調霜序。"]', '诗', 'shi', '', NULL, '五郊樂章 白帝商音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76f7c1a8-e4db-4732-8dcc-5238520ef773', '五郊樂章 白帝商音 舒和', '五郊乐章 白帝商音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["璿儀氣爽驚緹籥，玉呂灰飛含素商。","鳴鞞奏管芳羞薦，會舞安歌葆眊揚。"]', '["璿儀氣爽驚緹籥，玉呂灰飞含素商。","鳴鞞奏管芳羞薦，會舞安歌葆眊揚。"]', '诗', 'shi', '', NULL, '五郊樂章 白帝商音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b395577-7cc4-4fbb-ab36-9165fd1bc743', '五郊樂章 黑帝羽音', '五郊乐章 黑帝羽音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["嚴冬季月，星迴風厲。","享祀報功，方祚來歲。"]', '["嚴冬季月，星迴风厲。","享祀報功，方祚来歲。"]', '诗', 'shi', '', NULL, '五郊樂章 黑帝羽音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16da4545-4983-4058-90a0-3358e343c732', '五郊樂章 黑帝羽音 肅和', '五郊乐章 黑帝羽音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["律周玉琯，星回金度。","次極陽烏，紀窮陰兔。","火林霰雪，陽泉凝冱。","八蜡已登，三農息務。"]', '["律周玉琯，星回金度。","次極陽烏，紀窮陰兔。","火林霰雪，陽泉凝冱。","八蜡已登，三農息務。"]', '诗', 'shi', '', NULL, '五郊樂章 黑帝羽音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bec2d117-726f-46cd-9822-6161ce1554c5', '五郊樂章 黑帝羽音 雍和', '五郊乐章 黑帝羽音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["陽月斯紀，應鍾在候。","載絜牲牷，爰登俎豆。","既高既遠，無聲無臭。","靜言格思，惟神保祐。"]', '["陽月斯紀，應鍾在候。","載絜牲牷，爰登俎豆。","既高既远，無声無臭。","静言格思，惟神保祐。"]', '诗', 'shi', '', NULL, '五郊樂章 黑帝羽音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aefd176-e102-43cf-a731-1c73427ae9f8', '五郊樂章 黑帝羽音 舒和', '五郊乐章 黑帝羽音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["執籥持羽初終曲，朱干玉鏚始分行。","七德九功咸已暢，明靈降福具穰穰。"]', '["執籥持羽初終曲，朱干玉鏚始分行。","七德九功咸已暢，明靈降福具穰穰。"]', '诗', 'shi', '', NULL, '五郊樂章 黑帝羽音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6467fb7f-094f-4c66-96f8-8b02ace07db4', '享太廟樂章 永和', '享太廟乐章 永和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["於穆烈祖，弘此丕基。","永言配命，子孫保之。","百神既洽，萬國在茲。","是用孝享，神其格思。"]', '["於穆烈祖，弘此丕基。","永言配命，子孫保之。","百神既洽，万国在茲。","是用孝享，神其格思。"]', '诗', 'shi', '', NULL, '享太廟樂章 永和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2cf9832-0b09-4085-8a27-40aea6d0745d', '享太廟樂章 肅和', '享太廟乐章 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["大哉至德，允茲明聖。","格于上下，聿遵誠敬。","嘉樂斯登，鳴球以詠。","神其降止，式隆景命。"]', '["大哉至德，允茲明聖。","格于上下，聿遵誠敬。","嘉乐斯登，鳴球以詠。","神其降止，式隆景命。"]', '诗', 'shi', '', NULL, '享太廟樂章 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce96d9d5-069c-4bf3-97bc-71c7e919f03b', '享太廟樂章 雍和', '享太廟乐章 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["崇茲享祀，誠敬兼至。","樂以感靈，禮以昭事。","粢盛咸絜，牲牷孔備。","永言孝思，庶幾不匱。"]', '["崇茲享祀，誠敬兼至。","乐以感靈，禮以昭事。","粢盛咸絜，牲牷孔備。","永言孝思，庶幾不匱。"]', '诗', 'shi', '', NULL, '享太廟樂章 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7a169a-2803-4d8d-b6ac-f7183f316a32', '享太廟樂章 長發舞', '享太廟乐章 长發舞', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["濬哲惟唐，長發其祥。","帝命斯祐，王業克昌。","配天載德，就日重光。","本枝百代，申錫無疆。"]', '["濬哲惟唐，长發其祥。","帝命斯祐，王業克昌。","配天載德，就日重光。","本枝百代，申錫無疆。"]', '诗', 'shi', '', NULL, '享太廟樂章 長發舞 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df80ac1b-a18f-48ce-a1eb-dde0a22fcd79', '享太廟樂章 大基舞', '享太廟乐章 大基舞', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["猗與祖業，皇矣帝先。","剪商德厚，封唐慶延。","在姬猶稷，方晉踰宣。","基我鼎運，于斯萬年。"]', '["猗與祖業，皇矣帝先。","剪商德厚，封唐慶延。","在姬猶稷，方晉踰宣。","基我鼎運，于斯万年。"]', '诗', 'shi', '', NULL, '享太廟樂章 大基舞 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d001393-f402-4cce-9c09-666c24bb6e1d', '享太廟樂章 大成舞', '享太廟乐章 大成舞', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["周穆王季，晉美帝文。","明明盛德，穆穆齊芬。","藏用四履，屈道參分。","鏗鏘鐘石，載紀鴻勳。"]', '["周穆王季，晉美帝文。","明明盛德，穆穆齊芬。","藏用四履，屈道參分。","鏗鏘鐘石，載紀鴻勳。"]', '诗', 'shi', '', NULL, '享太廟樂章 大成舞 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cea9f2c3-df03-40db-8607-e18fa81d25f9', '享太廟樂章 大明舞', '享太廟乐章 大明舞', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["五紀更運，三正逓升。","勛華既沒，禹湯勃興。","神武命代，靈睠是膺。","望雲彰德，察緯告徵。","上紐天維，下安地軸。","徵師涿野，萬國咸服。","偃伯靈臺，九官允穆。","殊域委贐，懷生介福。","大禮既飾，大樂已和。","黑章擾囿，赤字浮河。","功宣載籍，德被詠歌。","克昌厥後，百祿是荷。"]', '["五紀更運，三正逓升。","勛华既沒，禹湯勃兴。","神武命代，靈睠是膺。","望云彰德，察緯告徵。","上紐天維，下安地軸。","徵師涿野，万国咸服。","偃伯靈台，九官允穆。","殊域委贐，懷生介福。","大禮既飾，大乐已和。","黑章擾囿，赤字浮河。","功宣載籍，德被詠歌。","克昌厥後，百祿是荷。"]', '诗', 'shi', '', NULL, '享太廟樂章 大明舞 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f50edb58-c2da-4b4c-8313-cb0228bf8421', '享太廟樂章 壽和', '享太廟乐章 壽和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["八音斯奏，三獻畢陳。","寶祚惟永，暉光日新。"]', '["八音斯奏，三獻畢陳。","寶祚惟永，暉光日新。"]', '诗', 'shi', '', NULL, '享太廟樂章 壽和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14f70ec7-e472-4803-a619-06874f28567a', '享太廟樂章 舒和', '享太廟乐章 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["聖敬通神光七廟，靈心薦祚和萬方。","嚴禋克配鴻基遠，明德惟馨鳳曆昌。"]', '["聖敬通神光七廟，靈心薦祚和万方。","嚴禋克配鴻基远，明德惟馨鳳曆昌。"]', '诗', 'shi', '', NULL, '享太廟樂章 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c09e229-cfc8-4a2d-a3fa-d01c6a0dbfbe', '享太廟樂章 雍和', '享太廟乐章 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["於穆清廟，聿脩嚴祀。","四縣載陳，三獻斯止。","籩豆撤薦，人祗介祉。","神惟格思，錫祚不已。"]', '["於穆清廟，聿脩嚴祀。","四縣載陳，三獻斯止。","籩豆撤薦，人祗介祉。","神惟格思，錫祚不已。"]', '诗', 'shi', '', NULL, '享太廟樂章 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3acb17-3c28-4d18-a11d-0b44b5552970', '享太廟樂章 永和', '享太廟乐章 永和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["肅肅清祀，烝烝孝思。","薦享昭備，虔恭在茲。","雍歌撤俎，祝嘏陳辭。","用光武志，永固鴻基。"]', '["肅肅清祀，烝烝孝思。","薦享昭備，虔恭在茲。","雍歌撤俎，祝嘏陳辞。","用光武志，永固鴻基。"]', '诗', 'shi', '', NULL, '享太廟樂章 永和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c25975-9405-4c66-af2d-0d9a080dbc8e', '賦西漢', '賦西漢', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["受降臨軹道，爭長趣鴻門。","驅傳渭橋上，觀兵細柳屯。","夜宴經柏谷，朝遊出杜原。","終藉叔孫禮，方知皇帝尊。"]', '["受降臨軹道，爭长趣鴻门。","驱傳渭橋上，观兵細柳屯。","夜宴經柏谷，朝游出杜原。","終藉叔孫禮，方知皇帝尊。"]', '诗', 'shi', '', NULL, '賦西漢 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e19050d3-c051-46cc-b1a7-fd0e64c776ab', '暮秋言懷', '暮秋言懷', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["首夏別京輔，杪秋滯三河。","沈沈蓬萊閣，日夕鄉思多。","霜剪涼階蕙，風捎幽渚荷。","歲芳坐淪歇，感此式微歌。"]', '["首夏別京輔，杪秋滯三河。","沈沈蓬萊閣，日夕乡思多。","霜剪涼階蕙，风捎幽渚荷。","歲芳坐淪歇，感此式微歌。"]', '诗', 'shi', '', NULL, '暮秋言懷 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5de65084-28e0-44c9-b2fc-3bb7a1e2db6d', '述懷', '述懷', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["中原初逐鹿，投筆事戎軒。","縱橫計不就，慷慨志猶存。","杖策謁天子，驅馬出關門。","請纓繫南粵，憑軾下東藩。","鬱紆陟高岫，出沒望平原。","古木鳴寒鳥，空山啼夜猿。","既傷千里目，還驚九折魂。","豈不憚艱險，深懷國士恩。","季布無二諾，侯嬴重一言。","人生感意氣，功名誰復論。"]', '["中原初逐鹿，投笔事戎軒。","縱橫計不就，慷慨志猶存。","杖策謁天子，驱马出关门。","請纓繫南粵，憑軾下东藩。","鬱紆陟高岫，出沒望平原。","古木鳴寒鸟，空山啼夜猿。","既傷千里目，還驚九折魂。","豈不憚艱險，深懷国士恩。","季布無二諾，侯嬴重一言。","人生感意氣，功名誰复論。"]', '诗', 'shi', '', NULL, '述懷 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4672e3-4f3d-46c3-afd3-bddc1a48aa73', '奉和正日臨朝應詔', '奉和正日臨朝應詔', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["百靈侍軒后，萬國會塗山。","豈如今睿哲，邁古獨光前。","聲教溢四海，朝宗引百川。","鏘洋鳴玉珮，灼爍耀金蟬。","淑景輝雕輦，高旌揚翠煙。","庭實超王會，廣樂盛鈞天。","既欣東日戶，復詠南風篇。","願奉光華慶，從斯億萬年。"]', '["百靈侍軒后，万国會塗山。","豈如今睿哲，邁古独光前。","声教溢四海，朝宗引百川。","鏘洋鳴玉珮，灼爍耀金蟬。","淑景輝雕輦，高旌揚翠煙。","庭實超王會，廣乐盛鈞天。","既欣东日戶，复詠南风篇。","願奉光华慶，從斯億万年。"]', '诗', 'shi', '', NULL, '奉和正日臨朝應詔 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61eb5ea5-7deb-4c42-adf0-b3d6cac9e569', '祈穀樂章 肅和', '祈穀乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["履艮斯繩，居中體正。","龍運垂祉，昭符啓聖。","式事嚴禋，聿懷嘉慶。","惟帝永錫，時皇休命。"]', '["履艮斯繩，居中體正。","龙運垂祉，昭符啓聖。","式事嚴禋，聿懷嘉慶。","惟帝永錫，时皇休命。"]', '诗', 'shi', '', NULL, '祈穀樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b150eb-0a37-4885-bd6b-367808236532', '祈穀樂章 雍和', '祈穀乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["殷薦乘春，太壇臨曙。","八簋盈和，六瑚登御。","嘉稷匪歆，德馨斯飫。","祝嘏無易，靈心有豫。"]', '["殷薦乘春，太壇臨曙。","八簋盈和，六瑚登御。","嘉稷匪歆，德馨斯飫。","祝嘏無易，靈心有豫。"]', '诗', 'shi', '', NULL, '祈穀樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2313b75-6c38-4707-8631-936ab9a87df1', '祈穀樂章 舒和', '祈穀乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["玉帛犧牲申敬享，金絲鏚羽盛音容。","庶俾億齡禔景福，長欣萬宇洽時邕。"]', '["玉帛犧牲申敬享，金絲鏚羽盛音容。","庶俾億齡禔景福，长欣万宇洽时邕。"]', '诗', 'shi', '', NULL, '祈穀樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062bf763-b5d0-4b3d-97ff-3cf51b77fee7', '明堂樂章 肅和', '明堂乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["象天御宇，乘時布政。","嚴配申虔，宗禋展敬。","罇罍盈列，樹羽交暎。","玉幣通誠，祚隆皇聖。"]', '["象天御宇，乘时布政。","嚴配申虔，宗禋展敬。","罇罍盈列，樹羽交暎。","玉幣通誠，祚隆皇聖。"]', '诗', 'shi', '', NULL, '明堂樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b881a7-13af-4ad0-aa42-a18adc6872bd', '明堂樂章 雍和', '明堂乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["八牖晨披，五精朝奠。","霧凝璇篚，風清金縣。","神滌備全，明粢豐衍。","載[絜]彝俎，陳誠以薦。"]', '["八牖晨披，五精朝奠。","霧凝璇篚，风清金縣。","神滌備全，明粢豐衍。","載[絜]彝俎，陳誠以薦。"]', '诗', 'shi', '', NULL, '明堂樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b5664c-a547-40b6-9526-9c78006bb151', '明堂樂章 舒和', '明堂乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["御扆合宮承寶曆，席圖重館奉明靈。","偃武修文九圍泰，沈烽靜柝八荒寧。"]', '["御扆合宮承寶曆，席圖重館奉明靈。","偃武修文九圍泰，沈烽静柝八荒寧。"]', '诗', 'shi', '', NULL, '明堂樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0eef0a0-bbe6-45c6-a18f-086a92af4234', '雩祀樂章 肅和', '雩祀乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["朱鳥開辰，蒼龍啓暎。","大帝昭饗，羣生展敬。","禮備懷柔，功宣舞詠。","旬液應序，年祥叶慶。"]', '["朱鸟开辰，蒼龙啓暎。","大帝昭饗，羣生展敬。","禮備懷柔，功宣舞詠。","旬液應序，年祥叶慶。"]', '诗', 'shi', '', NULL, '雩祀樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3950db34-3491-4a51-b6c6-3f14c63f66d8', '雩祀樂章 雍和', '雩祀乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["紺筵分彩，珤圖吐絢。","鳳管晨凝，雲歌曉囀。","肅事蘋藻，虔申桂奠。","百穀斯登，萬箱攸薦。"]', '["紺筵分彩，珤圖吐絢。","鳳管晨凝，云歌晓囀。","肅事蘋藻，虔申桂奠。","百穀斯登，万箱攸薦。"]', '诗', 'shi', '', NULL, '雩祀樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb7a703d-e2ee-4d2b-9994-b69ca125d56f', '雩祀樂章 舒和', '雩祀乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["鳳曲登歌調令序，龍雩集舞泛祥風。","綵旞雲迴昭睿德，朱干電發表神功。"]', '["鳳曲登歌調令序，龙雩集舞泛祥风。","綵旞云迴昭睿德，朱干電發表神功。"]', '诗', 'shi', '', NULL, '雩祀樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b0605e8-43a2-4763-8c62-bbb8e3afd186', '享先農樂章 誠和', '享先農乐章 誠和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["粒食伊始，農之所先。","古今攸賴，是曰人天。","耕斯帝籍，播厥公田。","式崇明祀，神其福焉。"]', '["粒食伊始，農之所先。","古今攸賴，是曰人天。","耕斯帝籍，播厥公田。","式崇明祀，神其福焉。"]', '诗', 'shi', '', NULL, '享先農樂章 誠和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0076a66-ee4f-4bd2-9f05-1cc30fc694db', '享先農樂章 肅和', '享先農乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["罇彝既列，瑚簋方薦。","歌工載登，幣禮斯奠。","肅肅享祀，顒顒纓弁。","神之聽之，福流寰縣。"]', '["罇彝既列，瑚簋方薦。","歌工載登，幣禮斯奠。","肅肅享祀，顒顒纓弁。","神之听之，福流寰縣。"]', '诗', 'shi', '', NULL, '享先農樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8594acb1-1052-41f5-a2b3-77be32b002ed', '享先農樂章 雍和', '享先農乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["前夕視牲，質明奉俎。","沐芳整弁，其儀式序。","盛禮畢陳，嘉樂備舉。","歆我懿德，非馨稷黍。"]', '["前夕視牲，質明奉俎。","沐芳整弁，其儀式序。","盛禮畢陳，嘉乐備舉。","歆我懿德，非馨稷黍。"]', '诗', 'shi', '', NULL, '享先農樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05065565-9306-4524-ba88-52621f4c1431', '享先農樂章 舒和', '享先農乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["羽籥低昂文綴已，干戚蹈厲武行初。","望歲祈農神所聽，延祥介福豈云虛。"]', '["羽籥低昂文綴已，干戚蹈厲武行初。","望歲祈農神所听，延祥介福豈云虛。"]', '诗', 'shi', '', NULL, '享先農樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb1e7d92-ba37-417f-a4eb-f5d5eb1307be', '祭神州樂章 肅和', '祭神州乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["大矣坤儀，至哉神縣。","包含日域，牢籠月竁。","露絜三清，風調六變。","皇祗届止，式歆恭薦。"]', '["大矣坤儀，至哉神縣。","包含日域，牢籠月竁。","露絜三清，风調六变。","皇祗届止，式歆恭薦。"]', '诗', 'shi', '', NULL, '祭神州樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b24addb-6986-4eb1-ae0a-e7fbfb72e243', '祭神州樂章 雍和', '祭神州乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["泰圻嚴享，陰郊展敬。","禮以導神，樂以和性。","黝牲在列，黃琮俯暎。","九土既平，萬邦貽慶。"]', '["泰圻嚴享，陰郊展敬。","禮以導神，乐以和性。","黝牲在列，黄琮俯暎。","九土既平，万邦貽慶。"]', '诗', 'shi', '', NULL, '祭神州樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a25609-1ade-477a-8eb6-b28394686b83', '祭神州樂章 舒和', '祭神州乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["坤道降祥和庶品，靈心載德厚羣生。","水土既調三極泰，文武畢備九區平。"]', '["坤道降祥和庶品，靈心載德厚羣生。","水土既調三極泰，文武畢備九區平。"]', '诗', 'shi', '', NULL, '祭神州樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74f48a9-4a52-429e-b2ff-1ceb5c6eb8ad', '祭方丘樂章 順和', '祭方丘乐章 順和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["萬物資以化，交泰屬昇平。","易從業惟簡，得一道斯寧。","具儀光玉帛，送舞變咸英。","黍稷良非貴，明德信惟馨。"]', '["万物資以化，交泰屬昇平。","易從業惟簡，得一道斯寧。","具儀光玉帛，送舞变咸英。","黍稷良非貴，明德信惟馨。"]', '诗', 'shi', '', NULL, '祭方丘樂章 順和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffecaa96-c386-42c9-a448-da003bf1be10', '祭方丘樂章 肅和', '祭方丘乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["至矣坤德，皇哉地祗。","開元統紐，合大承規。","九宮肅列，六典相儀。","永言配命，長保無虧。"]', '["至矣坤德，皇哉地祗。","开元統紐，合大承規。","九宮肅列，六典相儀。","永言配命，长保無虧。"]', '诗', 'shi', '', NULL, '祭方丘樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('def95fdf-e5f0-4ac5-a803-ea969cccb395', '祭方丘樂章 雍和', '祭方丘乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["柔而能方，直而能敬。","厚載以德，大亨以正。","有滌斯牷，有馨斯盛。","介茲景福，祚我休慶。"]', '["柔而能方，直而能敬。","厚載以德，大亨以正。","有滌斯牷，有馨斯盛。","介茲景福，祚我休慶。"]', '诗', 'shi', '', NULL, '祭方丘樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b22c264-5ba8-4583-b2c3-b170681e4eec', '祭方丘樂章 舒和', '祭方丘乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["玉幣牲牷分薦享，羽旄干鏚遰成容。","一德惟寧兩儀泰，三材保合四時邕。"]', '["玉幣牲牷分薦享，羽旄干鏚遰成容。","一德惟寧兩儀泰，三材保合四时邕。"]', '诗', 'shi', '', NULL, '祭方丘樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a2901c-330a-4ad5-a082-4dbf2c28c87f', '祭方丘樂章 順和', '祭方丘乐章 順和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["陰祗協贊，厚載方貞。","牲幣具舉，簫管備成。","其禮惟肅，其德惟明。","神之聽矣，式鑒虔誠。"]', '["陰祗協贊，厚載方貞。","牲幣具舉，簫管備成。","其禮惟肅，其德惟明。","神之听矣，式鑒虔誠。"]', '诗', 'shi', '', NULL, '祭方丘樂章 順和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56ba6ccc-ed3b-41f5-8995-2d506fcad31f', '臨高臺', '臨高台', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["高臺暫俯臨，飛翼聳輕音。","浮光隨日度，漾影逐波深。","迴瞰周平野，開懷暢遠襟。","獨此三休上，還傷千歲心。"]', '["高台暫俯臨，飞翼聳轻音。","浮光隨日度，漾影逐波深。","迴瞰周平野，开懷暢远襟。","独此三休上，還傷千歲心。"]', '诗', 'shi', '', NULL, '臨高臺 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f9cbbe-1916-4d4f-acec-9d4faf669916', '賦得蜀都', '賦得蜀都', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["列宿光參井，分芒跨梁岷。","沈犀對江浦，駟馬入城闉。","英圖多霸跡，歷選有名臣。","連騎簪纓滿，含章詞賦新。","得上仙槎路，無待訪嚴遵。"]', '["列宿光參井，分芒跨梁岷。","沈犀对江浦，駟马入城闉。","英圖多霸跡，歷選有名臣。","連騎簪纓满，含章词賦新。","得上仙槎路，無待訪嚴遵。"]', '诗', 'shi', '', NULL, '賦得蜀都 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a900189-b746-4fca-bbf6-ec056ea29d63', '奉和詠日午', '奉和詠日午', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["曦車日亭午，浮箭未移暉。","日光無落照，樹影正中圍。","草萎看稍靡，葉燥望疑稀。","晝寢慙經笥，暫解入朝衣。"]', '["曦车日亭午，浮箭未移暉。","日光無落照，樹影正中圍。","草萎看稍靡，葉燥望疑稀。","晝寢慙經笥，暫解入朝衣。"]', '诗', 'shi', '', NULL, '奉和詠日午 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdfbb09a-d41f-49bc-a7e7-4ed6c9335d71', '奉和望月應魏王教', '奉和望月應魏王教', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["層軒登皎月，流照滿中天。","色共梁珠遠，光隨趙璧圓。","落影臨秋扇，虛輪入夜弦。","所欣東館裏，預奉西園篇。"]', '["層軒登皎月，流照满中天。","色共梁珠远，光隨趙璧圓。","落影臨秋扇，虛輪入夜弦。","所欣东館裏，預奉西园篇。"]', '诗', 'shi', '', NULL, '奉和望月應魏王教 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2907d5c7-28c9-457d-9b1d-eae0cabb5cc7', '詠花燭', '詠花燭', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["蘭逕香風滿，梅梁暖日斜。","言是東方騎，來尋南陌車。","靨星臨夜燭，眉月隱輕紗。","莫言春稍晚，自有鎮開花。"]', '["蘭逕香风满，梅梁暖日斜。","言是东方騎，来尋南陌车。","靨星臨夜燭，眉月隐轻紗。","莫言春稍晚，自有鎮开花。"]', '诗', 'shi', '', NULL, '詠花燭 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('035d3b86-2369-4700-b853-2b1c55db3600', '在隴頭哭潘學士', '在隴头哭潘学士', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["隴底嗟長別，流襟一慟君。","何言幽咽所，更作死生分。","轉蓬飛不息，悲松斷更聞。","誰能駐征馬，回首望孤墳。"]', '["隴底嗟长別，流襟一慟君。","何言幽咽所，更作死生分。","轉蓬飞不息，悲松斷更闻。","誰能駐征马，回首望孤墳。"]', '诗', 'shi', '', NULL, '在隴頭哭潘學士 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8dd378c-a8ad-449f-8382-ea370477e289', '奉和禁苑餞別應令', '奉和禁苑餞別應令', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["大藩初錫瑞，出牧邇皇京。","暫以綠車重，言承朱傳榮。","舒桃臨遠騎，垂柳映京營。","惠化宣千里，威風動百城。","禁籞芳嘉節，神襟餞送情。","金笳催別景，玉琯切離聲。","野花開更落，山鳥哢還驚。","微臣夙多幸，薄宦奉儲明。","釣臺慙作賦，伊水濫聞笙。","懷德良知久，酬恩識命輕。"]', '["大藩初錫瑞，出牧邇皇京。","暫以綠车重，言承朱傳榮。","舒桃臨远騎，垂柳映京營。","惠化宣千里，威风动百城。","禁籞芳嘉節，神襟餞送情。","金笳催別景，玉琯切離声。","野花开更落，山鸟哢還驚。","微臣夙多幸，薄宦奉儲明。","釣台慙作賦，伊水濫闻笙。","懷德良知久，酬恩識命轻。"]', '诗', 'shi', '', NULL, '奉和禁苑餞別應令 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31e0ffc-0463-4e84-aaf4-7e50db6fda6c', '和御史韋大夫喜霽之作', '和御史韋大夫喜霽之作', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["晴天度旅雁，斜影照殘虹。","野淨餘煙盡，山明遠色同。","沙平寒水落，葉脆晚枝空。","白簡光朝幰，彤騶出禁中。","息駕遊蘭[坂]，雕文折桂叢。","無因輕羽扇，徒自仰仁風。"]', '["晴天度旅雁，斜影照殘虹。","野淨餘煙尽，山明远色同。","沙平寒水落，葉脆晚枝空。","白簡光朝幰，彤騶出禁中。","息駕游蘭[坂]，雕文折桂叢。","無因轻羽扇，徒自仰仁风。"]', '诗', 'shi', '', NULL, '和御史韋大夫喜霽之作 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d657619-0d58-46c1-9e1f-3af22bf57230', '晚別樂記室彥', '晚別乐記室彥', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["窮途屬歲晚，臨水忽分悲。","抱影同爲客，傷情共此時。","霧色侵虛牖，霜氛冷薄帷。","舉袂慘將別，停杯悵不怡。","風嚴征雁遠，雪暗去篷遲。"]', '["窮途屬歲晚，臨水忽分悲。","抱影同爲客，傷情共此时。","霧色侵虛牖，霜氛冷薄帷。","舉袂慘將別，停杯悵不怡。","风嚴征雁远，雪暗去篷遲。"]', '诗', 'shi', '', NULL, '晚別樂記室彥 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60de425a-6756-42a6-a0ef-8eb2b8f34699', '傷始平李少府正己', '傷始平李少府正己', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["勞息本相循，悲歡理自均。","誰能免玄夜，惜爾正青春。","邁德惟家寶，生才諒國珍。","高文綴翡翠，茂學掩麒麟。","述作紛無已，言談妙入神。","斷腸雖累月，分手未盈旬。","輔嗣俄長往，顏生即短辰。","聲華滿昭代，形影委窮塵。","禪草迴中使，生芻引弔賓。","同遊祕府日，方駕直城闉。","並拜黃圖右，分曹清渭濱。","風期嵇呂好，存歿范張親。","虛座憐王述，遺篇慟景純。","精靈與毫翰，千祀壽何人。"]', '["勞息本相循，悲歡理自均。","誰能免玄夜，惜爾正青春。","邁德惟家寶，生才諒国珍。","高文綴翡翠，茂学掩麒麟。","述作紛無已，言談妙入神。","斷腸雖累月，分手未盈旬。","輔嗣俄长往，顏生即短辰。","声华满昭代，形影委窮塵。","禪草迴中使，生芻引弔賓。","同游祕府日，方駕直城闉。","並拜黄圖右，分曹清渭濱。","风期嵇呂好，存歿范張親。","虛座怜王述，遺篇慟景純。","精靈與毫翰，千祀壽何人。"]', '诗', 'shi', '', NULL, '傷始平李少府正己 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d3d8ac4-987d-4978-920a-fac094a709d2', '秋鴈', '秋鴈', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["日暮霜風急，羽翮轉難任。","爲有傳書意，翩翩入上林。"]', '["日暮霜风急，羽翮轉难任。","爲有傳书意，翩翩入上林。"]', '诗', 'shi', '', NULL, '秋鴈 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('935d8505-f3c1-4cbc-867c-d10b3a52a620', '句', '句', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["神羊既不觸，夕鳥欲依人。"]', '["神羊既不觸，夕鸟欲依人。"]', '诗', 'shi', '', NULL, '句 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d36a855-49b6-41d7-8fc7-3c83e20031e2', '冬日宴羣公於宅各賦一字得杯', '冬日宴羣公於宅各賦一字得杯', 'ff0f5f00-c510-47f7-b483-b689de401fa9', '唐', '["陋巷朱軒擁，衡門緹騎來。","俱裁七步詠，同傾三雅杯。","色動迎春柳，花發犯寒梅。","賓筵未半醉，驪歌不用催。"]', '["陋巷朱軒擁，衡门緹騎来。","俱裁七步詠，同傾三雅杯。","色动迎春柳，花發犯寒梅。","賓筵未半醉，驪歌不用催。"]', '诗', 'shi', '', NULL, '冬日宴羣公於宅各賦一字得杯 于志寧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d7fd022-1305-438f-9189-c263d7a9e7c9', '冬日宴于庶子宅各賦一字得趣', '冬日宴于庶子宅各賦一字得趣', '8cffc7dc-9696-4c8d-916f-8ee6a5f5d0ce', '唐', '["高門聊命賞，羣英於此遇。","放曠山水情，留連文酒趣。","夕煙起林蘭，霜枝殞庭樹。","落景雖已傾，歸軒幸能駐。"]', '["高门聊命賞，羣英於此遇。","放曠山水情，留連文酒趣。","夕煙起林蘭，霜枝殞庭樹。","落景雖已傾，归軒幸能駐。"]', '诗', 'shi', '', NULL, '冬日宴于庶子宅各賦一字得趣 令狐德棻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f0553b-299b-4f5a-afe3-bd4fa740ad73', '冬日宴于庶子宅各賦一字得色', '冬日宴于庶子宅各賦一字得色', 'cb85f0af-fe1e-4bdb-a79e-544f920b2c64', '唐', '["夫君敬愛重，歡言情不極。","雅引發清音，麗藻窮雕飾。","水結曲池冰，日暖平亭色。","引滿既杯傾，終之以弁側。"]', '["夫君敬愛重，歡言情不極。","雅引發清音，丽藻窮雕飾。","水結曲池冰，日暖平亭色。","引满既杯傾，終之以弁側。"]', '诗', 'shi', '', NULL, '冬日宴于庶子宅各賦一字得色 封行高 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25f2e98f-1527-4a5d-aece-4474b716209a', '冬日宴于庶子宅各賦一字得節', '冬日宴于庶子宅各賦一字得節', '23e547c7-655b-4784-a090-cc53adce28a0', '唐', '["李門余妄進，徐榻君恆設。","清論暢玄言，雅琴飛白雪。","寒雲曖落景，朔風淒暮節。","方欣投轄情，且駐當歸別。"]', '["李门余妄進，徐榻君恆設。","清論暢玄言，雅琴飞白雪。","寒云曖落景，朔风淒暮節。","方欣投轄情，且駐當归別。"]', '诗', 'shi', '', NULL, '冬日宴于庶子宅各賦一字得節 杜正倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('278abb55-9c5e-4456-a748-64639a55ad7e', '玄武門侍宴', '玄武门侍宴', '23e547c7-655b-4784-a090-cc53adce28a0', '唐', '["大君端扆暇，睿賞狎林泉。","開軒臨禁籞，藉野列芳筵。","參差歌管颺，容裔羽旗懸。","玉池流若醴，雲閣聚非煙。","湛露晞堯日，熏風入舜弦。","大德侔玄造，微物荷陶甄。","謬陪瑤水宴，仍廁栢梁篇。","闞名徒上月，鄒辯詎談天。","既喜光華旦，還傷遲暮年。","猶冀升中日，簪裾奉肅然。"]', '["大君端扆暇，睿賞狎林泉。","开軒臨禁籞，藉野列芳筵。","參差歌管颺，容裔羽旗懸。","玉池流若醴，云閣聚非煙。","湛露晞堯日，熏风入舜弦。","大德侔玄造，微物荷陶甄。","謬陪瑤水宴，仍廁栢梁篇。","闞名徒上月，鄒辯詎談天。","既喜光华旦，還傷遲暮年。","猶冀升中日，簪裾奉肅然。"]', '诗', 'shi', '', NULL, '玄武門侍宴 杜正倫 shi');
